// ============================================================
// 3D-мир: рельеф, биомы, вода, города — Empire of Safavids
// ============================================================
// Бесшовный ландшафт 6350x6350: поля вокруг Исфахана, пустыня с
// дюнами на востоке, лес на северо-западе, северный хребет со
// снежными шапками, озеро с рекой и водопадом. Биомы красят рельеф
// и выбирают флору/фауну. groundHeight() — единственный источник
// высоты для сущностей: билинейная интерполяция видимого меша
// + плита городской площади (иначе персонажи проваливаются).

import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { DRACOLoader } from 'three/examples/jsm/loaders/DRACOLoader.js';
import { clone as копияСкелета } from 'three/examples/jsm/utils/SkeletonUtils.js';
import {
  sandTexture, plasterTexture, stoneTexture, mosaicTexture, plazaTexture, woodTexture,
  waterTexture, waterfallTexture,
} from './textures';
import { t } from '../i18n';
import { GATE_STELES, inscriptionFor, steleMesh } from './inscriptions';

// Половина стороны мира. Мир 6350x6350 единиц - в семь раз больше прежних
// 2400x2400 по площади, как и просили: (6350/2400)^2 = 7.000.
//
// ЧИСЛО ВЗЯТО ИЗ КОРНЯ, А НЕ ОКРУГЛЕНО. 3175 = 1200 * sqrt(7) = 3174.9.
// Круглое 3200 дало бы (6400/2400)^2 = 7.111 - и проверка «мир стал в семь
// раз больше» перестала бы проверять что-либо. Первую версию этого
// комментария я написал с числом 7.005: арифметика была неверна,
// (6350/2400)^2 равно 7.000, и ошибку поймала проверка, а не глаз.
export const WORLD_HALF = 3175;         // половина стороны мира

/** Половина стороны СТАРОГО мира: 2400x2400. Граница, за которой
 *  начинается рельеф. Внутри него мир сделан руками и не трогается. */
export const СТАРЫЙ_МИР = 1200;
export const CITY = { x: 34, z: 26, radius: 116 }; // Столица: радиус x2 = площадь x4

// ── Размеры городской стены (решение владельца 08.10.2026) ───
//
// Живут на верхнем уровне модуля, а не внутри buildCity, потому что их
// использует навигатор: «внутри города» — это не CITY.radius, а внутренняя
// грань кладки. Пока толщина стены была нулевой, границы совпадали, и
// навигатор обслуживал оба случая одной строкой `CITY.radius - 2`.
// С появлением 13-метровой стены такая строка стала враньём: четыре с
// половиной метров камня считались городом, и маршрут мог пройти сквозь
// стену в стороне от ворот.
//
// Модель `Wall-Type01.glb` в натуральном виде 12.551 × 4.922 × 5.653 м:
// ширина, ВЫСОТА, толщина. Начало координат в основании по центру, и в этом
// файле так оно и есть: min Y = 0.000, центры X и Z равны нулю.
//
// ЧТО ЗДЕСЬ РАНЬШЕ БЫЛО ПЕРЕПУТАНО, И КАК ЭТО ВЫЯСНИЛОСЬ. В коде стояло
// «высота 5.653, толщина 4.922» — ровно наоборот. Проверка на габариты файла
// упала и указала на ошибку в игровом коде, и это была лучшая из возможных
// развязок: падала она на число, взятое из настоящего GLB, а не вычисленное.
//
// Почему вообще перепуталось. FBX Z-вертикален: у исходной стены вертикаль —
// это 4.922, а 5.653 у неё поперек. Проверка габаритов сначала читала
// только accessor'ы GLB, то есть координаты МЕША локально, и не учитывала
// `translation` узла: конвертер двигал модель сдвигом узла, а не вершин. На
// бумаге высота была 4.922 — ровно та величина, что стояла в коде как
// «толщина». Две ошибки в разных местах сошлись и дали правдоподобный
// неправдоподобный результат: в коде толщина стояла на месте высоты.
//
// Теперь модель ещё и перегнана заново: конвертер прижимал к нулю ось Y, а
// после разворота Blender -> glTF прижатой оказывалась НЕ высота. Стена
// вставала отцентрованной по вертикали и уезжала на 2.46 м под землю. Отчёт
// конвертера обещал `min = [-6.276, 0.0, -2.461]`, а в игре она стояла
// наполовину в песке. Заметить это можно было только сверкой с моделями,
// которые уже работают: у башни и моста `min Y = 0.000`.
//
// Масштаб считается от требуемой общей высоты, а не выбирается на глаз:
//   (WALL_TOP + WALL_SUNK) / 4.922 = 15 / 4.922 = 3.0475
export const WALL_TOP = 12;   // гребень над землёй под сегментом
export const WALL_SUNK = 3;   // уход в грунт, чтобы не было щели
const СТЕНА_МОДЕЛЬ = 'decor/Wall-Type01.glb';
const СТЕНА_ВЫСОТА_МОДЕЛИ = 4.922;
const СТЕНА_ШИРИНА_МОДЕЛИ = 12.551;
const СТЕНА_ГЛУБИНА_МОДЕЛИ = 5.653;
const СТЕНА_ВЫСОТА = WALL_TOP + WALL_SUNK;
export const СТЕНА_МАСШТАБ = СТЕНА_ВЫСОТА / СТЕНА_ВЫСОТА_МОДЕЛИ;
export const СТЕНА_ШИРИНА = СТЕНА_ШИРИНА_МОДЕЛИ * СТЕНА_МАСШТАБ;
export const СТЕНА_ГЛУБИНА = СТЕНА_ГЛУБИНА_МОДЕЛИ * СТЕНА_МАСШТАБ;

/** Внутренняя грань стены: всё, что ближе, — город. Всё, что дальше, — камень
 *  или поля. Навигатор, мини-карта и спавн должны мерить до неё, а не до оси. */
export const CITY_INNER = CITY.radius - СТЕНА_ГЛУБИНА / 2;

/** Наружная грань стены. Всё, что ближе, — камень, и растительность туда
 *  расти не должна.
 *
 *  Эта граница нужна из-за той же причины, что и CITY_INNER, только с другой
 *  стороны. Пока стена имела нулевую толщину, отступ «CITY.radius + 6»
 *  оставлял её в покое: ось стены совпадала с её поверхностью. Теперь ось
 *  проходит в середине массива, и отступ в шесть метров от него попадает
 *  ВНУТРЬ кладки — трава прорастала сквозь камень.
 */
export const СТЕНА_НАРУЖНАЯ = CITY.radius + СТЕНА_ГЛУБИНА / 2;
export const CAMP = { x: 167, z: 132, radius: 16 }; // Полевой лагерь ВНЕ стен (город r=116)

// ── Вода и достопримечательности ─────────────────────────────
// Вода описана в ОДНОМ месте — shared/water.ts. До этого контуры были
// продублированы здесь и на сервере (utils/spawn.ts), и копии разошлись:
// море появилось в клиенте, а сервер о нём не узнал. Реэкспорт нужен для
// существующих потребителей, которые берут LAKE и реки из terrain.ts.
import {
  LAKE, POND, RIVER_A, RIVER_B, BRIDGES, SEA, SEA_ISLANDS,
  seaMask, seaIslandAt, waterMask, isWater, isDeepWater, canFloatAt,
  bridgeDeckY, BRIDGE_DECK_END, BRIDGE_SPAN,
} from '../../../../shared/water';
export {
  LAKE, POND, RIVER_A, RIVER_B, BRIDGES, SEA, SEA_ISLANDS,
  seaMask, seaIslandAt, waterMask, isWater, isDeepWater, canFloatAt,
};

export const WATERFALL = { x: -352, z: -568, width: 11, height: 15 };


/** Проверяет, находится ли точка на мосту. Возвращает высоту настила
 *  (по дуге - см. bridgeDeckY) или null, если моста нет */
export function bridgeAt(x: number, z: number): number | null {
  for (const b of BRIDGES) {
    // Преобразуем точку в локальные координаты моста
    const lx = (x - b.x) * b.dx + (z - b.z) * b.dz;   // вдоль моста
    const lz = -(x - b.x) * b.dz + (z - b.z) * b.dx;  // поперёк моста
    if (Math.abs(lx) < b.length / 2 && Math.abs(lz) < b.width / 2) {
      return bridgeDeckY(b, lx);
    }
  }
  return null;
}

