export const PORT = { x: -225, z: -150, radius: 26, level: -0.6 };     // приозёрный порт
export const CARAVANSERAI = { x: 505, z: 55, radius: 30, level: 1.2 }; // караван-сарай в пустыне
export const VILLAGE = { x: -495, z: -415, radius: 26, level: 2.0 };   // лесная деревня
export const FORT = { x: -320, z: -705, radius: 28, level: 22 };       // горный форт

// Дворец. Площадка ровная — по той же причине, что и у караван-сарая: под
// комплексом перепад 1.72 м, а угол утонул бы в земле, а противоположный
// висел бы в воздухе.
//
// РАДИУС 84, И ЭТО ПО ТРЕМ ТРЕБОВАНИЯМ СРАЗУ. flatten() держит ровную землю
// только до 0.55r, то есть здесь до 46.2 м, а три требования к этому кругу:
//
//   1. Комплекс вместе с башнями. Половинная диагональ 30.7 м: стена 32 м в
//      ширину, башни добавляют по 3.2 м, в глубину от -22 до +24.
//   2. Сетка рельефа. meshHeight берёт не формулу, а интерполяцию по вершинам
//      шагом 14.11 м, и вершина в углу ячейки уезжает на 9.98 м — половина
//      диагонали клетки. Отсюда 30.7 + 9.98 = 40.7, и 0.55r должен быть выше.
//   3. Запас сверх этого. Оставлено 5.5 м: при следующем расширении двора
//      радиус не придётся трогать, иначе придётся перемеривать заново.
//
// ПОЧЕМУ НЕ 60, КАК БЫЛО СНАЧАЛА. При 60 ровная часть кончалась на 33 м, а
// дальний угол башни выходил на 31.7 — впритык, без запаста на сетку. Потом
// двор удлинили до 24 м, и стало хуже: запас 7.77 м против 9.98 м. Проверка
// на сетку поймала это раньше, чем рендер.
//
// УРОВЕНЬ 2.2 — это высота двери по СЕТКЕ. Игрок выходит из дворца ровно туда,
// куда приходит: world3d ставит его на groundHeight, а она равна meshHeight
// плюс только надплита площади Исфахана, в шестистах метрах отсюда.
// Замер: meshHeight в двери и в точке выхода 2.2000, отклонение 0.0000;
// перепад по всему комплексу с башнями 0.004 м.
export const PALACE = { x: 620, z: -299, radius: 84, level: 2.2 };   // дворец шаха

// ── Габариты дворца ──────────────────────────────────────────────
//
// Всё в МЕТРАХ и в местных координатах группы дворца. Группа стоит в
// (PALACE.x, PALACE.level, PALACE.z), и начало координат — центр площадки, а
// не дверь. Отсюда и смещения: дверь в данных (620, -300) — это местные
// (0, -1), потому что PALACE.z = -299.
//
// ПОЧЕМУ ПЕРЕДНЯЯ СТЕНА ЗАЛА НА z = -1, А НЕ НА z = 0. Дверь одна, и игрок
// выходит из зала ровно туда. Стена на нуле отодвинула бы дверь на метр от
// данных: игрок вышел бы в пустоту террасы и встал бы лицом в стену.
export const PALACE_GEO = {
  /** Тронный зал: 26 x 18, стены 11 м, стена 2 м. */
  hall: { w: 26, d: 18, h: 11, t: 2 },
  /**
   * Стена комплекса: 32 м в ширину, высота 9 м, толщина 1.6 м.
   *
   * ГЛУБИНЫ ЗДЕСЬ НЕТ, И ЭТО НЕ УПУЩЕНИЕ. Длина боковых стен считается из
   * ЗАДНЯЯ_СТЕНА_Z и GATE_Z, потому что обе линии нужны ещё и коллайдерам,
   * и забибцам двора. Поле d было третьим числом об одном и том же, и оно
   * разошлось с GATE_Z: в комментарии стояло 46, в GATE_Z было 20, а боковые
   * стены получали длину из поля и вылезали за ворота на 2 м с каждой стороны.
   */
  wall: { w: 32, h: 9, t: 1.6 },
  /** Ворота: 7 м в проёме, айван над ними 6.5 м. */
  gate: { w: 7, h: 6.5 },
} as const;

/** Местная линия передней стены зала. На ней стоит дверь. */
export const HALL_FRONT_Z = -1;

/** Местная линия задней стены комплекса. За ней зал, дальше склон. */
