// ── Ткацкая с кладовой ──────────────────────────────────────────────
//
// Продолжение заказа «заполним здание экстерьером». Мечетный двор — §63,
// дворец — §65, таможня — §68, ткацкая — здесь.
//
// ГДЕ. Запись интерьера: ткацкая с кладовой, (820, -260), выход (820, -256).
// Комментарий в коде обещал, что там сухо по замеру, — проверено, обещание
// держится: центр на 2.4 м выше уровня моря.
//
// УРОВЕНЬ ВЫБРАН ЗАМЕРОМ, И ПЕРВЫЙ ПЕРЕБОР ТАМ СБОЯЛ. Искать уровень начали от
// нуля, а вся земля под ткацкой отрицательна: от -1.26 до -0.12. Сумма «срез
// плюс засыпка» тогда только росла, и минимум выпал на нижнюю границу поиска —
// то есть оптимум не был найден, а просто выдан край диапазона за ответ.
// Пересчёт вокруг медианы: по габариту 26 x 24 собрано 1023 точки высоты,
// медиана -0.74, и уровень -0.7 даёт сумму 174.2 против 276.4 у -0.5 и 290.1
// у -1.0. Общий вывод записан в скрипт замера: перебор, у которого весь массив
// по одну сторону от диапазона, оптимума не находит.
//
// При уровне -0.7 срез до 0.58 м и засыпка до 0.56 м — площадка почти вровень с
// родной землёй, без цоколя и без насыпи.
//
// РАДИУС 50, А НЕ 46. При 46 ровная часть была 25.3 м против полудиагонали
// комплекса 24.2 м, то есть запас всего 1.1 м, и замер показал перепад по
// комплексу 0.187 м против 0.051 у таможни: угол уезжал из-под ровнялки.
// При 50 ровная часть 27.5 м и запас 3.3 м.
//
// ДАЛЕКО ЛИ ОТ ДВОРЦА. В 204 м. Круги смешивания не пересекаются: 84 плюс 50 —
// это 134 м, а до дворца 204. Но расстояние проверяется числом в тесте дворца,
// а не «на глаз далеко».
export const WEAVER = { x: 820, z: -260, radius: 50, level: -0.7 };

// ── Габариты ткацкой ───────────────────────────────────────────────
//
// Всё в МЕТРАХ и в МЕСТНЫХ координатах группы. Начало — линия двери, как у
// таможни: в данных (820, -260) это сама дверь, а выход на четыре метра дальше
// по плюс z.
//
// ЧЕМ ОТЛИЧАЕТСЯ ОТ ТАМОЖНИ. Таможня — застава: стена, ворота, проезд.
// Ткацкая — мастерская: высокое здание с узкими окнами в верхнем ярусе (станкам
// нужен свет, а в интерьере они стоят у дальней стены), пристроенная кладовая
// у самого порога («занятого снегут первым, и видно от входа») и сушильные
// вешалы во дворе. Ворот нет: это не застава, и забор с проёмом здесь был бы
// враньём.
export const WEAVER_GEO = {
  /** Мастерская: 16 x 12, стены 9 м. Выше таможни — станки требуют высоты. */
  house: { w: 16, d: 12, h: 9.0, t: 0.5 },
  /** Кладовая: пристройка 7 x 6, стены 4.5 м. */
  store: { w: 7, d: 6, h: 4.5, t: 0.4 },
  /** Проём двери мастерской: 2.6 м. */
  door: { w: 2.6, h: 3.4 },
  /** Вешалы для сушки: два ряда столбов, между ними провисает ткань. */
  racks: { count: 2, w: 9.0, h: 3.2, gap: 4.5 },
} as const;

/** Местная линия задней стены мастерской. Мастерская стоит от неё до нуля. */
export const ТКАЦКАЯ_ЗАДНЯЯ_Z = -WEAVER_GEO.house.d;

/**
 * Местная линия дальней границы двора.
 *
 * 11, А НЕ 8. Вешалы занимают по 4.5 м в глубину и стоят в два ряда; при 8
 * второй ряд подвисал бы над землёй за забором, а первый перекрывал подход к
 * двери. При 11 между вешалами и дверью остаётся 6.5 м чистого прохода.
 */
export const ТКАЦКАЯ_ДВОР_Z = 11;

/** Заглушка в проёме двери: за мастерской нет зала, и небо видно не должно. */
export const ТКАЦКАЯ_ЗАГЛУШКА = { w: 2.6, h: 3.4, t: 0.25 };

/** Плита двора: толщина и подъём. Подъём 3 см — мощение, а не цоколь. */
export const ТКАЦКАЯ_ДВОР = { t: 0.2, подъём: 0.03 };
// ── Горное святилище ─────────────────────────────────────────────
//
// Пятый по счёту экстерьер по заказу «заполним здание экстерьером». Мечетный
// двор — §63, дворец — §65, таможня — §68, ткацкая — §69, святилище — здесь.
//
// ГДЕ. Запись интерьера: святилище, (1200, 1200), выход (1200, 1204).
//
// ПЛАНИРОВКА ВЗЯТА ИЗ ИНТЕРЬЕРА, А НЕ ПРИДУМАНА. Первая сборка стоила замера:
// я поставил руинную стену между дверью и алтарём, и замер показал просвет по
// оси -2.54 м, то есть прохода не было. В furnishShrine стена с проломом стоит
// на cz - 10.2, а алтарь с огнём на cz - 7: стена ЗА алтарём, это дальняя стена
// руинного двора. Игрок выходит через дверь спереди и идёт к алтарю, а пролом —
// в дальней стене. Теперь так и построено: дверь на локальном z = 0, зал уходит
// в минус z, терраса тянется в плюс z.
//
// СНАЧАЛА Я ПОСЧИТАЛ, ЧТО ЗДЕСЬ ВОДА, И ЭТО БЫЛО НЕВЕРНО. Замер по высоте дал
// минимум -4.96 при уровне моря -3.2, то есть ниже моря, и я решил, что
// площадка стоит в заливе. Проверка isWater дала 0 мокрых точек из 1089. Вода в
// игре задана КОНТУРАМИ (море, озеро, пруд, реки), а не высотой: сухая долина
// ниже уровня моря — это впадина, а не залив. Ошибка была опасной: по ней я
// собирался сдвигать святилище на 201 м.
//
// УРОВЕНЬ ЗЕМЛИ 1.1 ВЫБРАН ЗАМЕРОМ ВОКРУГ МЕДИАНЫ, а не перебором от нуля.
// Медиана по габариту настоящей планировки 1.13, диапазон шёл от -0.87 до 3.13, и
// минимум суммы «срез плюс засыпка» выпал на 1.1 при сумме 381.0. Урок ткацки:
// перебор, у которого весь массив по одну сторону от диапазона, оптимума не
// находит.
//
// РАДИУС 56, И МЕНЬШЕГО НЕ ХВАТАЛО. Полудиагональ комплекса 25.5 м: он уходит и
// вперёд (терраса со ступенями), и назад (двор на 16 м), и сторона назад
// длиннее. При радиусе 48 ровная часть 26.4 м, то есть запас 0.9 м — площадка
// почти вровень с углом комплекса, и такой запас уже не держит: у ткацки запас
// 1.1 м дал перепад 0.187 м. При 52 запас 3.1 м, и этого достаточно. Взято 56 с
// запасом 5.3 м.
//
// ПОЧЕМУ ТЕРРАСА ПОДНЯТА НА 1.2 М, А НЕ ЛЕЖИТ НА ЗЕМЛЕ. Это выяснил замер, и
// вывод был противоположен ожидаемому. Уровень площадки выбран по медиане, то
// есть земля ВОКРУГ террасы выровнена до 1.1 м на расстоянии 30.8 м, и склон
// начинается только за этим радиусом. Первая сборка строила подпорную стенку
// высотой 2.6 м и четыре ступени вниз, и обе конструкции были враньём:
//
//   * ступени спускались с края террасы (локальный z = 11.4) в РОВНУЮ землю:
//     замер показал 1.10 м на всей дистанции до z = 27, то есть спуска вниз
//     не было, и ступени вели в пустоту;
//   * подпорная стенка уходила с уровня террасы на 2.6 м в ту же ровную землю:
//     держать ей было нечего, и на виду оставался только её верх.
//
// Теперь терраса и здание ПОДНЯТЫ над ровной землёй площадки на 1.2 м, и
// подпорная стенка держит именно этот подиум. Это и есть то, что выбрал
// владелец 07.10.2026, — терраса с подпорной стенкой, — но теперь стенка
// работает. Ступени три по 0.4 м ведут с подиума вниз на ровную землю, и спуск
// настоящий: это видно и в цифрах замера, и на деле.
//
// СВЯЩЕННОСТЬ. Зороастрийское святилище огня на возвышенности верно по канону:
// огонь ставят на сухом месте повыше. Подиум в 1.2 м этому отвечает.
//
// ДАЛЕКО ЛИ ОТ СОСЕДЕЙ. До гробницы 283 м, до ханзы 447 м, до города 1697 м.
// Круги смешивания не пересекаются.
export const SHRINE = { x: 1200, z: 1200, radius: 56, level: 1.1 };

/**
 * Подъём террасы над землёй площадки.
 *
 * 1.2 М, И ЭТО ЧИСЛО ИЗ ЗАМЕРА. Столько нужно, чтобы подиум читался как уступ:
 * ниже метра — цоколь, выше полутора — крепость. Три ступени по 0.4 м ровно
 * сходят с него на землю, и число ступеней выведено из этого же числа.
 *
 * ОТДЕЛЬНО ОТ УРОВНЯ ПЛОЩАДКИ. SHRINE.level — это ровная земля вокруг, терраса
 * стоит на SHRINE.level плюс этот подъём. Мешать их нельзя: если поднять уровень
 * площадки, то земля вокруг тоже поднимется, и подиума снова не будет.
 */
export const СВЯТИЛИЩЕ_ПОДЪЁМ = 1.2;

// ── Габариты святилища ───────────────────────────────────────────
//
// Всё в МЕТРАХ и в МЕСТНЫХ координатах группы. Начало — линия двери, как у
// таможни и ткацкой: в данных (1200, 1200) это сама дверь, а выход на четыре
// метра дальше по плюс z.
//
// ЧЕМ ОТЛИЧАЕТСЯ ОТ ТАМОЖНИ И ТКАЦКОЙ. Таможня — застава, ткацкая — мастерская.
// Святилище — руина на уступе, и это меняет всё: стены стоят обломками, пролом
// шире двери, крыши нет, огонь виден снаружи. Зороастрийское святилище нельзя
// построить «ровным»: необработанный камень и есть его вид.
export const SHRINE_GEO = {
  /** Зал руинного двора: 22 x 16. Ширина 22 — это ROOM_W в interiors. */
  зал: { w: 22, d: 16 },
  /** Стена: толщина 1.4. Ниша должна читаться нишей, а не щелью. */
  wall: { t: 1.4 },
  /** Дверной проём: 2.8 м. */
  door: { w: 2.8, h: 3.2 },
  /** Пролом в дальней стене: 9 м. Шире двери в три с лишним раза. */
  gap: { w: 9.0 },
  /**
   * Терраса перед дверью.
   *
   * Ширина РАВНА ШИРИНЕ ЗАЛА, а не шире. Первая сборка взяла 26 при зале 22, и
   * между боковой стеной зала и подпорной стенкой террасы осталась щель в два
   * метра: игрок мог зайти туда сбоку, и это было мусорное место в руине.
   *
   * Глубина 10. Терраса должна быть шире двери, чтобы перед дверью было где
   * стоять, и не такой, чтобы двор совпал с залом.
   */
  terrace: { w: 22, d: 10 },
  /** Ступени вниз с подветренного края, в плюс z. */
  ступени: { число: 3, ширина: 5.0, подъём: 0.4, шаг: 1.5 },
  /** Парапет террасы над её уровнем: игрок должен видеть склон. */
  parapet: { h: 0.7 },
  /** Дымовая труба над алтарём: огонь внутри, дым видно с дороги. */
  chimney: { w: 2.2, d: 2.2, h: 4.6 },
  /** Жаровня перед дверью: огонь виден издалека. */
  brazier: { r: 0.9, h: 0.7 },
} as const;

