/**
 * Толщина плиты двора и насколько она поднята над землёй.
 *
 * ПОЧЕМУ ТОЛЬКО 6 СМ, А НЕ ПОЛМЕТРА. Высота игрока берётся из groundHeight,
 * а та ничего не знает про плиту: подъём площади Исфахана пришлось вносить
 * отдельно в саму groundHeight. Плита в полметра подняла бы игрока по
 * щиколотку в земле — он стоял бы В плите. Подъём на 6 см глазом не виден, а
 * меша плиты хватает, чтобы она не сливалась с дёрном в одну поверхность.
 */
