/** Мировые координаты городских ворот (якорь навигации) */
export const GATE = (() => {
  const a = Math.atan2(-CITY.z, -CITY.x);
  return { x: CITY.x + Math.cos(a) * CITY.radius, z: CITY.z + Math.sin(a) * CITY.radius };
})();

export type Biome = 'desert' | 'forest' | 'field' | 'mountain' | 'water';

/** Цилиндрические коллайдеры построек: персонаж и камера их уважают */
export const COLLIDERS: { x: number; z: number; r: number }[] = [];

/** Динамические коллайдеры фауны: звери движутся, поэтому фауна
 *  перезаписывает этот список каждый кадр (позиции + радиусы). */
export interface FaunaCollider { x: number; z: number; r: number }
export const FAUNA_COLLIDERS: FaunaCollider[] = [];

/** Динамические коллайдеры горожан (перезаписываются каждый кадр). */
export const CIV_COLLIDERS: FaunaCollider[] = [];

function addCollider(x: number, z: number, r: number): void {
  COLLIDERS.push({ x, z, r });
}
export { addCollider };

function fract(v: number): number { return v - Math.floor(v); }

function hash2(x: number, y: number): number {
  return fract(Math.sin(x * 127.1 + y * 311.7) * 43758.5453);
}

function smoothstep(t: number): number { return t * t * (3 - 2 * t); }

function clamp01(v: number): number { return Math.min(1, Math.max(0, v)); }

/** Гладкий value-noise */
function vnoise(x: number, y: number): number {
  const xi = Math.floor(x), yi = Math.floor(y);
  const xf = x - xi, yf = y - yi;
  const a = hash2(xi, yi), b = hash2(xi + 1, yi);
  const c = hash2(xi, yi + 1), d = hash2(xi + 1, yi + 1);
  const u = smoothstep(xf), v = smoothstep(yf);
  return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v;
}

function fbm(x: number, z: number): number {
  return 0.5 * vnoise(x / 96, z / 96) + 0.3 * vnoise(x / 38, z / 38) + 0.2 * vnoise(x / 14, z / 14);
}

// ── Маски биомов и воды ──────────────────────────────────────

/** Пустыня: восток карты (плавная граница 380..560) */
export function desertMask(x: number, z: number): number {
  return clamp01((x - 380) / 180) * clamp01((900 - Math.abs(z - 60)) / 500);
}

/** Лес: северо-запад, вокруг лесной деревни. Граница ломаная шумом. *
 *
 *  СТАРАЯ МАСКА БЫЛА МЁРТВОЙ, И ЭТО ИЗМЕРЕНО. Максимум forestMask на всём
 *  мире равнялся 0.078, а порог биома в biomeAt - 0.4. Лес не был слабым,
 *  его не было: диск радиусом 360 вокруг (-460,-330) лежит в z от -690 до
 *  30, а отсечка clamp01((z+120)/200) равна нулю при z <= -120 и растёт
 *  только после. Окна почти не пересекались, и произведение достигало
 *  максимума 0.078 при z = -45: (30-z)(z+120)/72000 на максимуме даёт
 *  5625/72000 = 0.0781. Ни биома, ни зелёного пятна на земле, ни лесной
 *  фауны, ни плотности деревьев 0.9 - ничего.
 *
 *  Радиус 700 взят под измеренную цель: фауна набирает 6 лесных зверей из
 *  900 случайных проб по всему миру, и при меньшем лесе шестеро не
 *  набираются никогда. Порог 0.4 проходится на расстоянии 420 - это
 *  около 1.4% мира, двенадцать проб из девятисот.
 *
 *  Центр уведён в (-620,-430): от прежнего центра столица в 608 единицах,
 *  и круг радиусом 700 дотянулся бы до Исфахана - земля вокруг столицы
 *  пошла бы зеленеть. От нового центра столица в 800 единицах, маска
 *  там строго ноль.
 */
export function forestMask(x: number, z: number): number {
  // Бугры подмешиваются к расстоянию, а не к самой маске: так граница
  // уезжает то туда, то сюда, а середина леса остаётся настоящим лесом.
  const бугры = (fbm(x / 150 + 21, z / 150 - 13) - 0.5) * 2;
  return clamp01(1 - (Math.hypot(x + 620, z + 430) + бугры * 130) / 700);
}
/** Рельеф новой земли: массивы, гряды и котловины. Вне старого мира. *
 *
 *  Внутри старого мира (|x|,|z| <= 1200) возвращает ровно ноль. Там всё
 *  расставлено руками: города, дороги, лесная деревня, форт. Правка идёт
 *  после базового шума и до края мира, хребта, дюн, площадок городов и
 *  дна водоёмов - иначе рельеф поднял бы берег залива выше уровня моря
 *  и высунул холмы сквозь воду.
 */
export function landformRelief(x: number, z: number): number {
  const d = Math.max(Math.abs(x), Math.abs(z)) - СТАРЫЙ_МИР;
  const т = clamp01(d / 700);
  if (т <= 0) return 0;
  // Две частоты: массивы на 640 единиц и гряды на 230. Одна частота дала бы
  // либо ровные холмы, либо шум - а нужны и широкие массивы, и гребни.
  const массивы = (vnoise(x / 640 + 5.5, z / 640 - 2.5) - 0.5) * 2;
  const гряды = (vnoise(x / 230 - 11.5, z / 230 + 7.5) - 0.5) * 2;
  return т * (массивы * 24 + гряды * 7);
}
/** Северный хребет (внутренний, кроме краевого) */
function ridgeMask(x: number, z: number): number {
  return smoothstep(clamp01((-z - 430) / 220)) * clamp01(1 - desertMask(x, z) * 0.8);
}



/** Уровень поверхности воды в точке или null, если суша.
 *  Озеро и реки — на уровне LAKE, пруд — на своём. */
export function waterSurfaceY(x: number, z: number): number | null {
  // Море проверяется первым: его уровень ниже, чем у озера и пруда, и
  // подстановка общей LAKE.level утащила бы гладь на полметра вверх.
  //
  // Порог 0.45 - тот же, что у biomeAt для биома 'water'. Пока маска
  // меньше половины, точка считается берегом: на прибрежной полосе маска
  // ещё мала, а земля уже выше уровня воды, и объявлять такую точку водой
  // значило бы отдавать отрицательную глубину (пленка воды над склоном).
  if (seaMask(x, z) > 0.45) return SEA.level;
  // Прибрежная полоса залива: маска моря ещё есть, но воды по признаку
  // поверхности тут нет. Возвращать уровень озера здесь нельзя - точка у
  // залива не в озере, и такая подмена отдавала бы берегу высоту чужой
  // воды (замерено: surf = -2.0 при ground = -0.2, то есть вода выше
  // земли наоборот).
  if (seaMask(x, z) > 0.05) return null;
  if (waterMask(x, z) <= 0.05) return null;
  return Math.hypot(x - POND.x, z - POND.z) < POND.r ? POND.level : LAKE.level;
}

function flatten(h: number, x: number, z: number, cx: number, cz: number, r: number, level: number): number {
  const d = Math.hypot(x - cx, z - cz);
  const t = smoothstep(clamp01((d - r * 0.55) / (r * 0.45)));
  return level + (h - level) * t;
}

/** Высота ландшафта в мировых координатах (форма меша) */
export function terrainHeight(x: number, z: number): number {
  let h = (fbm(x, z) - 0.5) * 16;
  h += landformRelief(x, z);
  // Рельеф новой земли. Идёт первым, чтобы край мира, хребет, дюны,
  // площадки городов и дно водоёмов легли поверх него, а не под ним.
  // Дальний хребет по краям мира
  const edge = Math.max(Math.abs(x), Math.abs(z)) / WORLD_HALF;
  h += smoothstep(clamp01((edge - 0.72) / 0.28)) * 55;
  // Северный хребет со скалистыми пиками
  const ridge = ridgeMask(x, z);
  // ГЛУШИМ ХРЕБЕТ В ЗАЛИВЕ, и это вынужденная мера. ridgeMask даёт полную
  // гору при z < -650, то есть юг мира был стеной высотой до 55 м. Море
  // в такую стену упиралось: вода не доходила до берега, а на пологом
  // склоне висела плёнкой в 20 метрах над землёй. Залив - это вода по
  // смыслу, и хребет обязан уступить ему место.
  const вЗамире = clamp01((-520 - z) / 140);
  h += ridge * (26 + fbm(x / 150 + 9, z / 150 - 4) * 34) * (1 - вЗамире);
  // Дюны пустыни
  const dm = desertMask(x, z);
  h = h * (1 - dm * 0.55) + dm * 0.55 * (1.5 + Math.sin(x * 0.021 + fbm(x / 60, z / 60) * 4) * 2.6 + (fbm(x / 25, z / 25) - 0.5) * 3);
  // Плоские площадки: город, возрождение, лагерь, поселения
  h = flatten(h, x, z, CITY.x, CITY.z, 150, 0.4); // плато накрывает кольцо стены (r=116)
  h = flatten(h, x, z, 0, 0, 26, 0.4); // уровень = базе города: иначе у ворот земля ниже и город «висит»
  h = flatten(h, x, z, CAMP.x, CAMP.z, 22, h * 0.35 + 0.3);
  h = flatten(h, x, z, PORT.x, PORT.z, PORT.radius, PORT.level);
  h = flatten(h, x, z, CARAVANSERAI.x, CARAVANSERAI.z, CARAVANSERAI.radius, CARAVANSERAI.level);
  h = flatten(h, x, z, VILLAGE.x, VILLAGE.z, VILLAGE.radius, VILLAGE.level);
  h = flatten(h, x, z, FORT.x, FORT.z, FORT.radius, FORT.level);
  // Площадки городов регионов. Радиус вдвое больше городского не из вкуса:
  // flatten() держит ровную землю только в центральных 55% своего радиуса,
  // а дома стоят на 86% городского. Без запаса они попали бы в зону
  // смешивания, где земля идёт в гору, и дома стояли бы на разной высоте.
  for (const t of REGION_TOWNS) h = flatten(h, x, z, t.x, t.z, t.radius * 2, t.level);
  // Низменность залива. Суша в заливе должна быть выше уровня моря
  // (SEA.level = -3.2), иначе после заливки половина берега окажется под
  // водой. Уровень +3.5 даёт суше 6.7 м над гладью - достаточно, чтобы
  // берег читался берегом.
  h = flatten(h, x, z, 0, -820, 900, 3.5);
  // ПОСЛЕДНЯЯ ИЗ РОВНЯЛОК, И ЭТО НЕ ПРИЧЬ — ПОРЯДОК. Ровнялка залива выше
  // стоит с центром (0, -820) и радиусом 900, то есть ровная часть её
  // (495 м) накрывает полкарты, а дворец в 810 м от центра попадает в зону
  // смешивания и подтягивается к уровню 3.5. Дворец был поставлен выше неё и
  // молча получал не свой уровень, а 2.37 вместо 2.2: дверь и игрок у стены
  // расходились на 17 см, и это выглядело бы как «дворец немного перекошен».
  //
  // Что из этого следует на будущее: НОВУЮ ПЛОЩАДКУ СТАВИТЬ ТОЛЬКО СЮДА.
  // Строка выше залива — место, где площадка проигрывает молча.
  h = flatten(h, x, z, PALACE.x, PALACE.z, PALACE.radius, PALACE.level);
  // Таможенный двор. ПОСЛЕ залива — см. правило выше. Уровень 0.2 и радиус 46
  // выбраны замером: медиана высот по габариту и перебор радиусов против
  // полудиагонали. Подробности у самого объявления CUSTOMS.
  h = flatten(h, x, z, CUSTOMS.x, CUSTOMS.z, CUSTOMS.radius, CUSTOMS.level);
  // Ткацкая. ПОСЛЕ залива — см. правило выше. Уровень -0.7 и радиус 46
  // выбраны замером: медиана высот по габариту и перебор радиусов против
  // полудиагонали. В 204 м от дворца, круги смешивания не пересекаются.
  h = flatten(h, x, z, WEAVER.x, WEAVER.z, WEAVER.radius, WEAVER.level);
  // Святилище. ПОСЛЕ залива — см. правило выше. Уровень 1.1 выбран замером
  // ВОКРУГ МЕДИАНЫ (1.13 по габариту настоящей планировки), а не перебором
  // от нуля: у ткацки перебор от нуля выдал границу диапазона.
  // Радиус 56: полудиагональ комплекса со стенкой и ступенями 27.1 м, при 48
  // он был БОЛЬШЕ комплекса, а при 52 запас 1.5 м был мал.
  h = flatten(h, x, z, SHRINE.x, SHRINE.z, SHRINE.radius, SHRINE.level);
  // Ханза. ПОСЛЕ залива — см. правило выше. Уровень -8.4 выбран замером
  // ВОКРУГ МЕДИАНЫ (-8.38 по габариту 775 точек), а не перебором от нуля.
  // Радиус 52: полудиагональ комплекса 25.6 м, при 48 запас 0.8 м.
  h = flatten(h, x, z, HANZA.x, HANZA.z, HANZA.radius, HANZA.level);
  // Гробница. ПОСЛЕ залива — см. правило выше. Уровень -2.5 выбран замером
  // ВОКРУГ МЕДИАНЫ (-2.49), а не перебором от нуля. Радиус 50: полудиагональ
  // комплекса 24.8 м, при 48 запас 1.6 м.
  h = flatten(h, x, z, TOMB.x, TOMB.z, TOMB.radius, TOMB.level);
  // Катакомбы. Уровень 1.2 вокруг медианы 1.23, радиус 60: полудиагональ 29.1,
  // при 48 запас был -2.7 м.
  h = flatten(h, x, z, CATACOMBS.x, CATACOMBS.z, CATACOMBS.radius, CATACOMBS.level);
  // Дворцовый данж. Уровень 2.7 вокруг медианы 2.71, радиус 60: полудиагональ
  // 29.1 м, при 48 запас был -2.7 м.
  h = flatten(h, x, z, PALACE_DUNGEON.x, PALACE_DUNGEON.z, PALACE_DUNGEON.radius, PALACE_DUNGEON.level);
  // Хорасанские пещеры. Уровень 3.9 вокруг медианы 3.91, радиус 60: полудиагональ
  // 29.1 м, при 48 запас был -2.7 м.
  h = flatten(h, x, z, KHORASAN_CAVES.x, KHORASAN_CAVES.z, KHORASAN_CAVES.radius, KHORASAN_CAVES.level);
  // Кавказский форпост. Уровень -2.4 вокруг медианы -2.40, радиус 60: полудиагональ
  // 29.1 м, при 48 запас был -2.7 м.
  h = flatten(h, x, z, CAUCASUS_FORT.x, CAUCASUS_FORT.z, CAUCASUS_FORT.radius, CAUCASUS_FORT.level);
  // Русла и озёра: русло углубляется до дна (в хребте это даёт ущелье и водопад)
  const w = waterMask(x, z);
  if (w > 0) {
    // Дно моря отдельное и глубокое: с тем же дном, что у озера, гладь
    // была бы по щиколотку, и плавание (глубже 1.2 м) не наступало бы.
    const sm = seaMask(x, z);
    const bed = sm >= w ? SEA.bed : LAKE.level - 3.2;
    h = h * (1 - w) + bed * w;
    // ПОДРЕЗКА ПО УРОВНЮ МОРЯ. Линейное смешивание с дном оставляет
    // приборжную полосу, где маска ещё мала, а земля выше уровня воды:
    // гладь висит плёнкой в метрах над склоном, и swimNeeded считает
    // глубину отрицательной. Там, где маска моря уже ненулевая, рельеф
    // опускается к уровню воды - получается пляж, а не плёнка.
    if (sm > 0.02 && h > SEA.level) {
      const подрезка = clamp01((sm - 0.02) / 0.15);
      h = h * (1 - подрезка) + Math.min(h, SEA.level + 0.5) * подрезка;
    }
  }
  return h;
}

// Сегментов вдоль стороны. Клетка = (WORLD_HALF * 2) / TERRAIN_SEG.
// 6350 / 450 = 14.1 единицы - ровно как было при 170 на старом мире.
//
// Цена измерена на собранном модуле, а не прикинута. Замеры в мс:
//   SEG 170 - 66 мс, 29241 вершина, 57800 треугольников
//   SEG 300 - 194 мс, 90601 вершина, 180000 треугольников
//   SEG 380 - 323 мс, 145161 вершина, 288800 треугольников
//   SEG 450 - 450 мс, 203401 вершина, 405000 треугольников
//   SEG 520 - 605 мс, 271441 вершина, 540800 треугольников
//
// При новом мире замер дал 488 мс и те же 203401 вершину: предсказание
// совпало с точностью до того, что край мира стал длиннее.
//
// Подробности и оговорки - в комментарии к WORLD_HALF выше.
const TERRAIN_SEG = 450;

/**
 * Высота видимого меша рельефа в точке: билинейная интерполяция вершин.
 * Без городской плиты — используется для постановки построек города.
 */
export function meshHeight(x: number, z: number): number {
  const half = WORLD_HALF;
  const step = (WORLD_HALF * 2) / TERRAIN_SEG;
  const fx = clamp01((x + half) / (WORLD_HALF * 2)) * TERRAIN_SEG;
  const fz = clamp01((z + half) / (WORLD_HALF * 2)) * TERRAIN_SEG;
  const i = Math.min(TERRAIN_SEG - 1, Math.floor(fx));
  const j = Math.min(TERRAIN_SEG - 1, Math.floor(fz));
  const lx = fx - i, lz = fz - j;
  const x0 = -half + i * step, x1 = x0 + step;
  const z0 = -half + j * step, z1 = z0 + step;
  const h00 = terrainHeight(x0, z0), h10 = terrainHeight(x1, z0);
  const h01 = terrainHeight(x0, z1), h11 = terrainHeight(x1, z1);
  return (h00 * (1 - lx) + h10 * lx) * (1 - lz) + (h01 * (1 - lx) + h11 * lx) * lz;
}

/**
 * Высота для сущностей: меш рельефа + плита городской площади.
 * Именно её должны использовать персонажи, NPC и животные — иначе
 * проваливаются между вершинами.
 */
export function groundHeight(x: number, z: number): number {
  let h = meshHeight(x, z);

  // Плита площади Исфахана стоит над землёй — сущности стоят на ней
  const dCity = Math.hypot(x - CITY.x, z - CITY.z);
  if (dCity < CITY.radius * 0.98) {
    const plazaTop = terrainHeight(CITY.x, CITY.z) + 0.3;
    const t = smoothstep(clamp01((CITY.radius * 0.98 - dCity) / 2.5));
    h = Math.max(h, h * (1 - t) + plazaTop * t);
  }
  return h;
}

/** Биом точки (для флоры, фауны и раскраски) */
export function biomeAt(x: number, z: number): Biome {
  if (waterMask(x, z) > 0.45) return 'water';
  const h = terrainHeight(x, z);
  if (h > 20 || ridgeMask(x, z) > 0.5) return 'mountain';
  if (desertMask(x, z) > 0.45) return 'desert';
  if (forestMask(x, z) > 0.4) return 'forest';
  return 'field';
}

export function isRoad(x: number, z: number): boolean {
  const seg = (ax: number, az: number, bx: number, bz: number, w: number) => {
    const dx = bx - ax, dz = bz - az;
    const len2 = dx * dx + dz * dz;
    const t = clamp01(((x - ax) * dx + (z - az) * dz) / len2);
    const px = ax + dx * t, pz = az + dz * t;
    return Math.hypot(x - px, z - pz) < w;
  };
  return seg(CITY.x, CITY.z, 0, 0, 3.2) || seg(0, 0, CAMP.x, CAMP.z, 2.6) ||
    seg(CITY.x, CITY.z, PORT.x, PORT.z, 2.4) || seg(CITY.x, CITY.z, CARAVANSERAI.x, CARAVANSERAI.z, 2.2) ||
    Math.hypot(x - CITY.x, z - CITY.z) < CITY.radius * 0.8;
}

// ── Материалы (с процедурными текстурами) ────────────────────
const MAT = {
  sand: new THREE.MeshStandardMaterial({ color: 0xbfae8a, roughness: 1, map: sandTexture(48) }),
  stone: new THREE.MeshStandardMaterial({ color: 0x9a958c, roughness: 0.95, map: stoneTexture(4) }),
  sandstone: new THREE.MeshStandardMaterial({ color: 0xd8c298, roughness: 0.9, map: plasterTexture('#c9ab7c', 2) }),
  sandstoneDark: new THREE.MeshStandardMaterial({ color: 0xb09468, roughness: 0.9, map: stoneTexture(6) }),
  tealDome: new THREE.MeshStandardMaterial({ color: 0x35a0a0, roughness: 0.45, metalness: 0.2, map: mosaicTexture(4) }),
  gold: new THREE.MeshStandardMaterial({ color: 0xc9a84c, roughness: 0.35, metalness: 0.7 }),
  wood: new THREE.MeshStandardMaterial({ color: 0x8a6a42, roughness: 1, map: woodTexture(1) }),
  foliage: new THREE.MeshStandardMaterial({ color: 0x4a6a38, roughness: 1 }),
  foliageDark: new THREE.MeshStandardMaterial({ color: 0x2f4a28, roughness: 1 }),
  foliageLight: new THREE.MeshStandardMaterial({ color: 0x5d7a3c, roughness: 1 }),
  brush: new THREE.MeshStandardMaterial({ color: 0x6a6a3c, roughness: 1 }),
  trunk: new THREE.MeshStandardMaterial({ color: 0x5a4630, roughness: 1 }),
  palmTrunk: new THREE.MeshStandardMaterial({ color: 0x7a6244, roughness: 1 }),
  palmLeaf: new THREE.MeshStandardMaterial({ color: 0x4f7a3a, roughness: 1, side: THREE.DoubleSide }),
  white: new THREE.MeshStandardMaterial({ color: 0xe8e0d0, roughness: 0.85 }),
  clothRed: new THREE.MeshStandardMaterial({ color: 0x8b1a1a, roughness: 1 }),
  clothTeal: new THREE.MeshStandardMaterial({ color: 0x2e8b8b, roughness: 1 }),
  clothPurple: new THREE.MeshStandardMaterial({ color: 0x7a5fd0, roughness: 1 }),
  dark: new THREE.MeshStandardMaterial({ color: 0x2a2a30, roughness: 1 }),
  water: new THREE.MeshStandardMaterial({
    color: 0x2f6f96, roughness: 0.12, metalness: 0.5, transparent: true, opacity: 0.82,
    map: waterTexture(6),
  }),
  waterfall: new THREE.MeshBasicMaterial({
    color: 0xdff0f8, transparent: true, opacity: 0.75, side: THREE.DoubleSide, map: waterfallTexture(2),
  }),
  snow: new THREE.MeshStandardMaterial({ color: 0xeef2f6, roughness: 1 }),
  flower: new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 1 }),
};

// ── Рельеф ───────────────────────────────────────────────────
export function buildTerrain(scene: THREE.Scene): THREE.Mesh {
  const SIZE = WORLD_HALF * 2;
  const SEG = TERRAIN_SEG;
  const geo = new THREE.PlaneGeometry(SIZE, SIZE, SEG, SEG);
  geo.rotateX(-Math.PI / 2);
  const pos = geo.attributes.position as THREE.BufferAttribute;
  const colors = new Float32Array(pos.count * 3);
  const cSand = new THREE.Color(0x9c8a66);
  const cDesert = new THREE.Color(0xc9a96e);
  const cGrass = new THREE.Color(0x5d7345);
  const cForest = new THREE.Color(0x3d5230);
  const cRock = new THREE.Color(0x7d828e);
  const cSnow = new THREE.Color(0xe8ecf2);
  const cRoad = new THREE.Color(0xb59d72);
  const cBed = new THREE.Color(0x8a7a58);
  const tmp = new THREE.Color();

  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i), z = pos.getZ(i);
    const h = terrainHeight(x, z);
    pos.setY(i, h);

    // Биомная раскраска
    const dm = desertMask(x, z);
    const fm = forestMask(x, z);
    const g = clamp01(fbm(x + 700, z - 300) * 1.6 - 0.55) * clamp01((h + 2) / 5);
    tmp.copy(cSand).lerp(cGrass, g * 0.85);
    tmp.lerp(cForest, fm * 0.8);
    tmp.lerp(cDesert, dm * 0.9);
    if (h > 16) tmp.lerp(cRock, clamp01((h - 16) / 14));
    if (h > 44) tmp.lerp(cSnow, clamp01((h - 44) / 12));
    if (waterMask(x, z) > 0.35) tmp.lerp(cBed, 0.85);
    if (isRoad(x, z)) tmp.lerp(cRoad, 0.75);
    // Лёгкая пестрота
    const n = 0.92 + hash2(x * 3.1, z * 2.7) * 0.16;
    colors[i * 3] = tmp.r * n; colors[i * 3 + 1] = tmp.g * n; colors[i * 3 + 2] = tmp.b * n;
  }
  geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  geo.computeVertexNormals();

  const mesh = new THREE.Mesh(geo, new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 1 }));
  mesh.receiveShadow = true;
  scene.add(mesh);
  return mesh;
}

// ── Вода: озеро, пруд, река, водопад ─────────────────────────
export function buildWater(scene: THREE.Scene): void {
  const water = new THREE.Group();
  const discGeo = new THREE.CircleGeometry(1, 28);
  discGeo.rotateX(-Math.PI / 2);

  const lake = new THREE.Mesh(discGeo, MAT.water);
  lake.scale.set(LAKE.r, 1, LAKE.r);
  lake.position.set(LAKE.x, LAKE.level, LAKE.z);
  water.add(lake);

  const pond = new THREE.Mesh(discGeo, MAT.water);
  pond.scale.set(POND.r, 1, POND.r);
  pond.position.set(POND.x, POND.level, POND.z);
  water.add(pond);

  // Море. Одна большая плоскость вместо сетки по маске: острова и берег
  // выше уровня воды, поэтому рельеф сам выступает из глади, и резать
  // геометрию по береговой линии не нужно.
  //
  // Границы посчитаны, а не подобраны на глаз: северный край - там, где
  // берег может зайти севернее всего (SEA.coast + SEA.jitter), южный -
  // край мира. Первая версия обрывала плоскость на 40 м южнее и оставляла
  // полосу воды без поверхности там, где шум уводил берег на север.
  const seaNorth = SEA.coast + SEA.jitter;
  const seaDepth = seaNorth - (-WORLD_HALF);
  const seaGeo = new THREE.PlaneGeometry(WORLD_HALF * 2, seaDepth, 1, 1);
  seaGeo.rotateX(-Math.PI / 2);
  const sea = new THREE.Mesh(seaGeo, MAT.water);
  sea.position.set(0, SEA.level, seaNorth - seaDepth / 2);
  sea.name = 'sea';
  water.add(sea);

  // Река — перекрывающиеся диски вдоль русла. Каждая река отдельным
  // циклом: склейка [RIVER_A, ...RIVER_B] добавляла между ними фантомный
  // сегмент, и его диски уходили на 17 м вне берега озера, где рельеф ниже
  // плоскости (-2.78 при воде -2.0), а isWater по близко этой точки считает
  // сушей: вода рисовалась прямо на траве.
  for (const river of [RIVER_A, RIVER_B]) {
    for (let i = 0; i < river.length - 1; i++) {
      const a = river[i], b = river[i + 1];
      const len = Math.hypot(b.x - a.x, b.z - a.z);
      const steps = Math.ceil(len / 9);
      for (let s = 0; s <= steps; s++) {
        const t = s / steps;
        const disc = new THREE.Mesh(discGeo, MAT.water);
        disc.scale.set(8.5, 1, 8.5);
        disc.position.set(a.x + (b.x - a.x) * t, LAKE.level, a.z + (b.z - a.z) * t);
        water.add(disc);
      }
    }
  }

  // Водопад: стена воды в ущелье хребта + пена у подножия + валуны
  const wf = new THREE.Mesh(new THREE.PlaneGeometry(WATERFALL.width, WATERFALL.height), MAT.waterfall);
  wf.position.set(WATERFALL.x, terrainHeight(WATERFALL.x, WATERFALL.z) + WATERFALL.height / 2 - 1, WATERFALL.z + 6);
  wf.name = 'waterfall';
  const foam = new THREE.Mesh(discGeo, new THREE.MeshStandardMaterial({ color: 0xeef6fa, transparent: true, opacity: 0.5, roughness: 0.3 }));
  foam.scale.set(9, 1, 7);
  foam.position.set(WATERFALL.x, terrainHeight(WATERFALL.x, WATERFALL.z - 14) + 0.2, WATERFALL.z - 8);
  water.add(wf, foam);
  for (const [rx, rz, rk] of [[-362, -560, 1.6], [-342, -556, 2.1], [-356, -548, 1.2]] as const) {
    const boulder = new THREE.Mesh(new THREE.IcosahedronGeometry(rk, 0), MAT.stone);
    boulder.position.set(rx, terrainHeight(rx, rz) + rk * 0.3, rz);
    boulder.castShadow = true;
    water.add(boulder);
  }

  scene.add(water);
}

// ── Растительность по биомам (InstancedMesh) ─────────────────
export function buildScatter(scene: THREE.Scene): void {
  const rng = (() => { let s = 42; return () => (s = (s * 16807) % 2147483647) / 2147483647; })();
  const spots: { x: number; z: number; h: number; biome: Biome }[] = [];
  for (let i = 0; i < 7000 && spots.length < 2600; i++) {
    const x = (rng() * 2 - 1) * (WORLD_HALF - 60);
    const z = (rng() * 2 - 1) * (WORLD_HALF - 60);
    const dCity = Math.hypot(x - CITY.x, z - CITY.z);
    const dSpawn = Math.hypot(x, z);
    // Отступ от стены — до НАРУЖНОЙ грани кладки, а не от её оси.
//
// Раньше здесь стояло `CITY.radius + 6`, и это было верно только пока толщина
// стены равнялась нулю: ось совпадала с поверхностью, и шесть метров запаса
// держали растительность снаружи. Теперь ось проходит в середине массива
// (107.39…124.62 м), и отступ в шесть метров от неё попадает ВНУТРЬ кладки —
// трава росла из камня на полосе шириной 2.6 м вдоль всего периметра.
if (dCity < СТЕНА_НАРУЖНАЯ || dSpawn < 14) continue;
    if (isRoad(x, z)) continue;
    const biome = biomeAt(x, z);
    if (biome === 'water') continue;
    if (waterMask(x, z) > 0.06) continue;
    spots.push({ x, z, h: groundHeight(x, z), biome });
  }

  const m = new THREE.Matrix4();
  const q = new THREE.Quaternion();
  const v = new THREE.Vector3();
  const sc = new THREE.Vector3();
  const color = new THREE.Color();
  const flowerColors = [0xe85a6a, 0xe8c94a, 0xd07ae8, 0xf0f0e0, 0xe88a4a];
  const put = (mesh: THREE.InstancedMesh, idx: number, x: number, y: number, z: number, k: number, rotY = 0, sy = k) => {
    m.compose(v.set(x, y, z), q.setFromEuler(new THREE.Euler(0, rotY, 0)), sc.set(k, sy, k));
    mesh.setMatrixAt(idx, m);
  };

  // Списки по биомам
  const trees = spots.filter(s => (s.biome === 'forest' ? rng() < 0.9 : s.biome === 'field' ? rng() < 0.12 : s.biome === 'mountain' ? rng() < 0.1 : rng() < 0.006));
  const rocks = spots.filter(s => (s.biome === 'mountain' ? rng() < 0.5 : s.biome === 'desert' ? rng() < 0.22 : rng() < 0.06));
  const tufts = spots.filter(s => (s.biome === 'field' ? rng() < 0.6 : s.biome === 'forest' ? rng() < 0.25 : rng() < 0.05));
  const flowers = spots.filter(s => s.biome === 'field' && rng() < 0.45);
  const brushes = spots.filter(s => s.biome === 'desert' && rng() < 0.3);
  const pines = spots.filter(s => s.biome === 'mountain' && s.h < 40 && rng() < 0.5);

  // Стволы + кроны (платан/кипарис по случаю)
  const trunkGeo = new THREE.CylinderGeometry(0.22, 0.34, 3.2, 6);
  const trunks = new THREE.InstancedMesh(trunkGeo, MAT.trunk, trees.length);
  trunks.castShadow = true;
  const crownGeo = new THREE.ConeGeometry(1.7, 3.4, 7);
  const crowns = new THREE.InstancedMesh(crownGeo, MAT.foliage, trees.length);
  crowns.castShadow = true;
  const crown2Geo = new THREE.SphereGeometry(1.9, 8, 6);
  const crowns2 = new THREE.InstancedMesh(crown2Geo, MAT.foliageLight, trees.length);
  crowns2.castShadow = true;
  trees.forEach((s, idx) => {
    const k = 0.8 + rng() * 1.2;
    put(trunks, idx, s.x, s.h + 1.6 * k, s.z, k);
    const cypress = s.biome !== 'field' && rng() < 0.7 || rng() < 0.4;
    if (cypress) {
      put(crowns, idx, s.x, s.h + 3.9 * k, s.z, k * 0.8, rng() * Math.PI, k * 1.25);
      put(crowns2, idx, s.x, -9999, s.z, 0.001);
    } else {
      put(crowns, idx, s.x, -9999, s.z, 0.001);
      put(crowns2, idx, s.x, s.h + 3.7 * k, s.z, k * 1.05, 0, k);
    }
  });
  trunks.count = trees.length; crowns.count = trees.length; crowns2.count = trees.length;

  // Коллайдеры деревьев (стволы)
  for (const s of trees) {
    addCollider(s.x, s.z, 0.5);
  }

  // Камни
  const rockGeo = new THREE.IcosahedronGeometry(1, 0);
  const rocksMesh = new THREE.InstancedMesh(rockGeo, MAT.stone, rocks.length);
  rocksMesh.castShadow = true; rocksMesh.receiveShadow = true;
  rocks.forEach((s, idx) => {
    const k = 0.6 + rng() * (s.biome === 'mountain' ? 2.6 : 1.6);
    m.compose(v.set(s.x, s.h + k * 0.25, s.z), q.setFromEuler(new THREE.Euler(rng() * 0.4, rng() * Math.PI, 0)), sc.set(k, k * 0.75, k));
    rocksMesh.setMatrixAt(idx, m);
  });
  rocksMesh.count = rocks.length;
  // Коллайдеры камней: по размеру (мелочь не мешает, валуны держат)
  for (const s of rocks) {
    const big = s.biome === 'mountain';
    addCollider(s.x, s.z, big ? 1.4 : 0.9);
  }

  // Трава
  const tuftGeo = new THREE.ConeGeometry(0.5, 1.1, 5);
  const tuftsMesh = new THREE.InstancedMesh(tuftGeo, MAT.foliageLight, tufts.length);
  tufts.forEach((s, idx) => {
    const k = 0.7 + rng() * 0.9;
    put(tuftsMesh, idx, s.x, s.h + 0.4 * k, s.z, k);
  });
  tuftsMesh.count = tufts.length;

  // Цветы (только поля)
  const flowerGeo = new THREE.SphereGeometry(0.12, 5, 4);
  const flowersMesh = new THREE.InstancedMesh(flowerGeo, MAT.flower, flowers.length);
  const stemGeo = new THREE.CylinderGeometry(0.02, 0.02, 0.5, 4);
  const stemsMesh = new THREE.InstancedMesh(stemGeo, MAT.foliageLight, flowers.length);
  flowers.forEach((s, idx) => {
    const k = 0.8 + rng() * 0.7;
    put(stemsMesh, idx, s.x, s.h + 0.25 * k, s.z, k);
    put(flowersMesh, idx, s.x, s.h + 0.55 * k, s.z, k);
    color.setHex(flowerColors[Math.floor(rng() * flowerColors.length)]);
    flowersMesh.setColorAt(idx, color);
  });
  flowersMesh.count = flowers.length; stemsMesh.count = flowers.length;
  if (flowersMesh.instanceColor) flowersMesh.instanceColor.needsUpdate = true;

  // Пустынный кустарник (саксаул): короткий ствол + оливковый шар
  const brushTrunkGeo = new THREE.CylinderGeometry(0.08, 0.14, 0.9, 5);
  const brushTrunks = new THREE.InstancedMesh(brushTrunkGeo, MAT.trunk, brushes.length);
  const brushGeo = new THREE.SphereGeometry(0.8, 7, 5);
  const brushesMesh = new THREE.InstancedMesh(brushGeo, MAT.brush, brushes.length);
  brushes.forEach((s, idx) => {
    const k = 0.7 + rng() * 1.1;
    put(brushTrunks, idx, s.x, s.h + 0.45 * k, s.z, k);
    put(brushesMesh, idx, s.x, s.h + 1.1 * k, s.z, k, 0, k * 0.8);
  });
  brushTrunks.count = brushes.length; brushesMesh.count = brushes.length;

  // Горная хвоя: тёмные узкие конусы
  const pineGeo = new THREE.ConeGeometry(1.2, 4.4, 6);
  const pinesMesh = new THREE.InstancedMesh(pineGeo, MAT.foliageDark, pines.length);
  const pineTrunkGeo = new THREE.CylinderGeometry(0.14, 0.2, 1.4, 5);
  const pineTrunks = new THREE.InstancedMesh(pineTrunkGeo, MAT.trunk, pines.length);
  pines.forEach((s, idx) => {
    const k = 0.9 + rng() * 0.9;
    put(pineTrunks, idx, s.x, s.h + 0.7 * k, s.z, k);
    put(pinesMesh, idx, s.x, s.h + 3.1 * k, s.z, k);
  });
  pinesMesh.count = pines.length; pineTrunks.count = pines.length;
  // Коллайдеры горной хвои (стволы)
  for (const s of pines) {
    addCollider(s.x, s.z, 0.5);
  }

  // Пальмы-оазисы: берега озера/пруда
  const oasis = spots.filter(s => {
    const wm = waterMask(s.x, s.z);
    return wm > 0.005 && wm < 0.09 && (s.biome === 'desert' || rng() < 0.5);
  }).slice(0, 46);

  scene.add(trunks, crowns, crowns2, rocksMesh, tuftsMesh, flowersMesh, stemsMesh,
    brushTrunks, brushesMesh, pinesMesh, pineTrunks);

  // Пальмы строятся группами (не инстансами — их немного)
  for (const s of oasis) addPalm(scene, s.x, s.z, 0.8 + rng() * 0.6);
}

// ── Дороги: грунтовые и каменные + караванные пути ─────────
/**
 * Материал полотна дороги: утоптанная земля, а не однотонная заливка.
 *
 * ТУТ БЫЛА ПЛОСКАЯ ЗАЛИВКА ЦВЕТОМ, И ЭТО ТОТ САМЫЙ «НЕКРАСИВЫЙ» ВИД. Ровная
 * полоса одного тона поверх земли читается как покрашенная, а не как
 * дорога. Добавлены три вещи, которые делают её похожей на грунт:
 *
 * 1. Светлый центр и потемнение к обочинам — настоящая дорога темнее там,
 *    где её топтали, и светлее посередине, где проезжают повозки.
 * 2. Мелкий щебень и колеи, повторяющиеся текстурой вдоль полотна.
 * 3. Прозрачные кромки. Раньше по краям стояли отдельные бордюры высотой
 *    40 см, и именно они давали ту самую жёсткую тёмную кромку, из-за
 *    которой дорога выглядела наклеенной. Теперь край просто растворяется
 *    в земле, и границы видно только тем, что земля под ними чуть светлее.
 *
 * alphaTest, а не blending: полотно лежит вплотную к земле, и при обычной
 * полупрозрачности сортировка давала бы мерцание, когда игрок вплотную
 * подходит к дороге.
 */
function roadMaterial(stone: boolean): THREE.MeshStandardMaterial {
  const c = document.createElement('canvas');
  c.width = 128; c.height = 128;
  const g = c.getContext('2d')!;

  // Основа: поперёк полотна светлее к центру, темнее к обочинам
  const base = g.createLinearGradient(0, 0, 128, 0);
  const light = stone ? '#a8a294' : '#d9b87e';
  const dark = stone ? '#6f6a5e' : '#a5824f';
  base.addColorStop(0, dark);
  base.addColorStop(0.5, light);
  base.addColorStop(1, dark);
  g.fillStyle = base;
  g.fillRect(0, 0, 128, 128);

  // Щебень и колеи
  for (let i = 0; i < 700; i++) {
    const x = Math.random() * 128;
    const y = Math.random() * 128;
    const s = 1 + Math.random() * 2.2;
    const shade = Math.random() < 0.5 ? 0 : 255;
    g.fillStyle = `rgba(${shade},${shade},${shade},${0.04 + Math.random() * 0.09})`;
    g.fillRect(x, y, s, s);
  }
  for (const lane of [0.32, 0.68]) {
    g.fillStyle = 'rgba(0,0,0,0.10)';
    g.fillRect(Math.round(128 * lane) - 2, 0, 4, 128);
  }

  // Растворяем кромки в землю
  g.globalCompositeOperation = 'destination-out';
  for (const [x0, x1] of [[0, 22], [128, 106]] as const) {
    const grad = g.createLinearGradient(x0, 0, x1, 0);
    grad.addColorStop(0, 'rgba(0,0,0,1)');
    grad.addColorStop(1, 'rgba(0,0,0,0)');
    g.fillStyle = grad;
    g.fillRect(Math.min(x0, x1), 0, Math.abs(x1 - x0), 128);
  }
  g.globalCompositeOperation = 'source-over';

  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.RepeatWrapping;
  tex.anisotropy = 4;
  return new THREE.MeshStandardMaterial({
    map: tex,
    roughness: 0.95,
    metalness: 0.0,
    alphaTest: 0.5,
  });
}

/**
 * Дороги между settlements — общие данные для полотна и для движения.
 *
 * Вынесены наружу, потому что по этим же линиям теперь ходят караваны и
 * путники (см. roadTraffic.ts). Раньше список жил внутри buildRoads, и караваны
 * были зашиты в него же тремя статичными верблюдами на фиксированных точках:
 * стоят навечно, не идут, и привязаны к ИНДЕКСУ roads[3]. Стоило добавить
 * пятую дорогу в список — и караваны уехали бы на другую.
 */
export const ROAD_PATHS: {
  from: { x: number; z: number };
  to: { x: number; z: number };
  w: number;
  stone: boolean;
}[] = [
  { from: { x: CITY.x, z: CITY.z }, to: { x: 0, z: 0 }, w: 4.0, stone: true },
  { from: { x: 0, z: 0 }, to: { x: CAMP.x, z: CAMP.z }, w: 3.5, stone: false },
  { from: { x: CITY.x, z: CITY.z }, to: { x: PORT.x, z: PORT.z }, w: 3.0, stone: false },
  { from: { x: CITY.x, z: CITY.z }, to: { x: CARAVANSERAI.x, z: CARAVANSERAI.z }, w: 3.0, stone: false },
];

export function buildRoads(scene: THREE.Scene): void {
  const roads = ROAD_PATHS;

  const roadMat = roadMaterial(false);
  const stoneRoadMat = roadMaterial(true);

  // Вспомогательная функция: строит одну дорогу как единый BufferGeometry
  function buildSingleRoad(
    scene: THREE.Scene,
    from: { x: number; z: number },
    to: { x: number; z: number },
    width: number,
    mat: THREE.Material,
  ): void {
    const dx = to.x - from.x, dz = to.z - from.z;
    const totalLen = Math.hypot(dx, dz);
    // ТУТ БЫЛО ДЕЛИМУЮ 2, И ШАГ ПОЛУЧАЛСЯ СЛИШКОМ КРУПНЫМ. Дорога шла
    // двумяметровыми кусками, а рельеф между ними проваливался: полотно
    // провисало или, наоборот, торчало из земли клином. Метр — мельче
    // любой неровности, которую тут можно поймать.
    const segCount = Math.max(8, Math.ceil(totalLen / 1));

    // Нормаль и перпендикуляр
    const angle = Math.atan2(dx, dz);
    const sinA = Math.sin(angle), cosA = Math.cos(angle);
    const px = sinA, pz = cosA;

    // Положим все данные в отдельные массивы
    const posArr: number[] = [];
    const uvArr: number[] = [];
    const idxArr: number[] = [];

    for (let si = 0; si <= segCount; si++) {
      const tt = si / segCount;
      const cx = from.x + dx * tt;
      const cz = from.z + dz * tt;
      // ТУТ БЫЛА ГЛАВНАЯ ОШИБКА ПОЛОТНА. Высота бралась ОДИН РАЗ, в
      // центре полосы, и обе крайние точки ставились на неё же. Но земля
      // по краям дороги лежит на другой высоте, и на любом уклоне или
      // бугорке полотно с одной стороны уходило в землю, а с другой
      // висело над ней. На снимках это читалось как светлая лента, которая
      // то тонет в земле, то повисает в воздухе.
      //
      // Теперь высота снимается в каждой крайней точке, и поднимается над
      // более высокой из них — так полотно никогда не провалится.
      const lx = cx - px * width / 2, lz = cz - pz * width / 2;
      const rx = cx + px * width / 2, rz = cz + pz * width / 2;
      const ly = groundHeight(lx, lz);
      const ry = groundHeight(rx, rz);
      const y = Math.max(ly, ry) + 0.07;
      posArr.push(lx, y, lz, rx, y, rz);
      uvArr.push(0, tt, 1, tt);
    }
    for (let si = 0; si < segCount; si++) {
      const a = si * 2, b = si * 2 + 1, c = (si + 1) * 2, d = (si + 1) * 2 + 1;
      idxArr.push(a, c, b, b, c, d);
    }

    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(posArr, 3));
    geo.setAttribute('uv', new THREE.Float32BufferAttribute(uvArr, 2));
    geo.setIndex(idxArr);
    geo.computeVertexNormals();
    const mesh = new THREE.Mesh(geo, mat);
    mesh.receiveShadow = true;
    // ТУТ БЫЛ ЧЁРНЫЙ КОСОЙ ШТРИХ ПО ЗЕМЛЕ. Дорога — это полость, лежащая
    // на земле, и она ставила castShadow. Тень от полосы, поднятой на 5 см,
    // ложилась рядом с ней тёмной чертой — на ровной пустыне это и было те
    // чёрные диагонали на снимке. Принимать тень полотно должно (чтобы
    // всадники и деревья клали на дорогу свою тень), а отбрасывать — нет:
    // земля под дорогой и так в тени.
    mesh.castShadow = false;
    scene.add(mesh);
  }

  for (const r of roads) {
    buildSingleRoad(scene, r.from, r.to, r.w, r.stone ? stoneRoadMat : roadMat);
  }

  // Караваны уехали в roadTraffic.ts.
  //
  // ТУТ СТОЯЛИ ТРИ СТАТИЧНЫХ ВЕРБЛЮДА. Они не двигались никогда: стояли в
  // точках 0.2, 0.45 и 0.7 пути и ждали. Поле было пустым не потому, что
  // движения не было, а потому, что его и не существовало — просто три
  // деревянных ящика на обочине. Теперь по дорогам идут настоящие караваны,
  // а заодно и случайные путники с квестами.

  // ── Мосты ──
  // Коробочный мост заменён моделью: medieval-bridge, арочный пролёт.
  // Модель натягивается вдоль оси на длину моста и вширь настолько же
  // (sx = length / BRIDGE_SPAN), а ВВЫСЬ НЕ ТРОГАЕТСЯ: поэтому столбы
  // остаются натуральной высоты на любом пролёте, а дуга поднимается ровно
  // на BRIDGE_ARCH_RISE - столько же, сколько считает bridgeDeckY, - и
  // игрок идёт ПО настилу, а не над ним и не в нём. Посадка: модель
  // садится на BRIDGE_DECK_END ниже уровня концов, чтобы концы настила
  // легли на берег. Крен по берегам (slope) - тем же поворотом модели.
  for (const b of BRIDGES) {
    const sx = b.length / BRIDGE_SPAN;
    const yaw = Math.atan2(-b.dz, b.dx);
    const roll = Math.atan(b.slope);
    void loadDecorModel('decor/medieval-bridge.glb').then((модель) => {
      if (!модель) return;
      const мост = модель.clone();
      мост.position.set(b.x, b.height - BRIDGE_DECK_END, b.z);
      // Порядок YXZ: крен идёт ПЕРВЫМ - в системе самой модели, и наклоняет
      // пролёт по направлению оси; yaw потом ставит локальный X на (dx,dz).
      мост.rotation.set(0, yaw, roll, 'YXZ');
      мост.scale.set(sx, 1, sx);
      мост.traverse((o) => {
        const m = o as THREE.Mesh;
        if (!m.isMesh) return;
        m.castShadow = true;
        m.receiveShadow = true;
      });
      scene.add(мост);
    });

    // Коллайдеры по краям моста (чтобы не свалиться в воду сбоку)
    const perpX = -b.dz, perpZ = b.dx;
    for (let along = -b.length / 2 + 2; along <= b.length / 2 - 2; along += 4) {
      for (let side = -1; side <= 1; side += 2) {
        const cx = b.x + b.dx * along + perpX * side * (b.width / 2 - 0.5);
        const cz = b.z + b.dz * along + perpZ * side * (b.width / 2 - 0.5);
        COLLIDERS.push({ x: cx, z: cz, r: 0.4 });
      }
    }
  }
}

/** Пальма: изогнутый ствол + веер листьев */
function addPalm(parent: THREE.Object3D, x: number, z: number, k = 1, cityLocal = false): void {
  const palm = new THREE.Group();
  const lean = (Math.random() - 0.5) * 0.28;
  const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.16 * k, 0.26 * k, 5.4 * k, 6), MAT.palmTrunk);
  trunk.position.y = 2.7 * k;
  trunk.rotation.z = lean;
  trunk.castShadow = true;
  palm.add(trunk);
  const topX = -Math.sin(lean) * 5.4 * k, topY = Math.cos(lean) * 5.4 * k;
  for (let i = 0; i < 7; i++) {
    const a = (i / 7) * Math.PI * 2;
    const leaf = new THREE.Mesh(new THREE.ConeGeometry(0.34 * k, 2.6 * k, 4), MAT.palmLeaf);
    leaf.position.set(topX + Math.cos(a) * 1.0 * k, topY + 0.15 * k, Math.sin(a) * 1.0 * k);
    leaf.rotation.set(Math.sin(a) * 1.25, 0, -Math.cos(a) * 1.25 - lean * 2);
    leaf.castShadow = true;
    palm.add(leaf);
  }
  for (let i = 0; i < 3; i++) {
    const nut = new THREE.Mesh(new THREE.SphereGeometry(0.12 * k, 6, 5), MAT.trunk);
    nut.position.set(topX + (Math.random() - 0.5) * 0.4 * k, topY - 0.25 * k, (Math.random() - 0.5) * 0.4 * k);
    palm.add(nut);
  }
  palm.position.set(x, groundHeight(x, z), z);
  parent.add(palm);
  if (cityLocal) addCollider(CITY.x + x, CITY.z + z, 0.55);
  else addCollider(x, z, 0.55);
}

// ── Город Исфахан ────────────────────────────────────────────
// Табличка квартала
function quarterSign(text: string): THREE.Mesh {
  const c = document.createElement('canvas');
  c.width = 256; c.height = 64;
  const g = c.getContext('2d')!;
  g.fillStyle = '#2a2018';
  g.fillRect(0, 0, 256, 64);
  g.strokeStyle = '#c9a84c';
  g.lineWidth = 4;
  g.strokeRect(3, 3, 250, 58);
  g.fillStyle = '#f5f0e8';
  g.font = 'bold 26px sans-serif';
  g.textAlign = 'center';
  g.textBaseline = 'middle';
  g.fillText(text, 128, 34);
  return new THREE.Mesh(
    new THREE.PlaneGeometry(4.2, 1.05),
    new THREE.MeshBasicMaterial({ map: new THREE.CanvasTexture(c) }),
  );
}

// Кварталы расширенного города: базар, ремесла, жилые дома, сады.
// Позиции зарезервированы в placed[] выше — процедурные дома их обходят.
function buildQuarters(
  city: THREE.Group,
  canopies: THREE.MeshStandardMaterial[],
  lights: { x: number; z: number; y?: number }[],
): void {
  const streetMat = new THREE.MeshStandardMaterial({ color: 0x9a8a68, roughness: 1 });
  const QUARTERS = [
    { x: 84, z: 0, name: 'Базар' },
    { x: 11.7, z: -83.2, name: 'Ремесла' },
    { x: 59.4, z: 59.4, name: 'Жилой' },
    { x: -31.5, z: 77.9, name: 'Сады' },
  ];

  // Улицы-проспекты от центра к кварталам
  for (const q of QUARTERS) {
    const len = Math.hypot(q.x, q.z);
    // Проспект только по внешнему кольцу (r=30..len-14): центр занят
    // площадью, мечетью и рынком — дорога их не пересекает.
    const r0 = 30, r1 = len - 14;
    const ave = new THREE.Mesh(new THREE.BoxGeometry(5, 0.12, r1 - r0), streetMat);
    ave.position.set(q.x / len * ((r0 + r1) / 2), 0.42, q.z / len * ((r0 + r1) / 2));
    ave.rotation.y = Math.atan2(q.x, q.z);
    ave.receiveShadow = true;
    city.add(ave);
    const nx = -q.x / len, nz = -q.z / len;
    const sign = quarterSign(q.name);
    sign.position.set(q.x + nx * 13, 3.2, q.z + nz * 13);
    sign.rotation.y = Math.atan2(nx, nz);
    city.add(sign);
    const post = new THREE.Mesh(new THREE.BoxGeometry(0.25, 3.2, 0.25), MAT.wood);
    post.position.set(q.x + nx * 13, 1.6, q.z + nz * 13);
    city.add(post);
    addCollider(CITY.x + q.x + nx * 13, CITY.z + q.z + nz * 13, 0.5);
  }

  // Базар: два ряда лавок
  const stallKinds = [0, 1, 2, 0, 1, 2] as const;
  const stallSpots: [number, number][] = [[78, -5], [78, 5], [84, -5], [84, 5], [90, -4], [90, 5]];
  stallSpots.forEach(([sx, sz], i) => {
    const stall = buildStall(stallKinds[i], canopies);
    stall.position.set(sx, 0.3, sz);
    stall.rotation.y = (i % 2 ? -0.12 : 0.12);
    city.add(stall);
    addCollider(CITY.x + sx, CITY.z + sz, 2.4);
  });

  // Ремесла: три кузни с горнами
  for (const [hx, hz] of [[8, -80], [16, -86], [6, -88]] as const) {
    const hut = new THREE.Group();
    const hb = new THREE.Mesh(new THREE.BoxGeometry(4.5, 3, 4), MAT.sandstoneDark);
    hb.position.y = 1.5; hb.castShadow = true;
    const chim = new THREE.Mesh(new THREE.BoxGeometry(0.8, 2.4, 0.8), MAT.dark);
    chim.position.set(1.2, 4.0, -0.8);
    const anvil = new THREE.Mesh(new THREE.BoxGeometry(1.4, 0.5, 0.6), MAT.dark);
    anvil.position.set(-3.2, 0.65, 1.2);
    const fire = new THREE.Mesh(
      new THREE.BoxGeometry(0.9, 0.7, 0.9),
      new THREE.MeshStandardMaterial({ color: 0xff8c30, emissive: 0xff6a10, emissiveIntensity: 1.6 }),
    );
    fire.position.set(-3.2, 1.2, 1.2);
    const barrel = new THREE.Mesh(new THREE.CylinderGeometry(0.8, 0.9, 1.5, 9), MAT.wood);
    barrel.position.set(3.0, 0.75, 1.4);
    barrel.castShadow = true;
    hut.add(hb, chim, anvil, fire, barrel);
    hut.position.set(hx, 0.3, hz);
    hut.rotation.y = hx * 0.05;
    city.add(hut);
    addCollider(CITY.x + hx, CITY.z + hz, 3.4);
  }

  // Жилой квартал: семь домов кольцом
  // Радиус коллайдера берётся по диагонали дома (w×0.9), зазор между домами ≥ 2.2 м.
  // Координаты пересчитаны: минимальное расстояние между центрами должно быть
  // > houseR_i + houseR_j + 2.2, иначе дома визуально слипаются.
  const homeOffsets: [number, number, number][] = [
    [-14, -7, 5],   // дом 1 — дальше от дома 4
    [0, -13, 6],    // дом 2
    [14, -7, 4.5],  // дом 3 — дальше от дома 1
    [-14, 3, 5.5],  // дом 4 — дальше от дома 1
    [14, 3, 4.5],   // дом 5
    [-6, 12, 5],    // дом 6
    [6, 12, 6],     // дом 7
  ];
  homeOffsets.forEach(([ox, oz, w], i) => {
    const hx = 59.4 + ox, hz = 59.4 + oz;
    const r = Math.max(2.4, Math.hypot(w, w * 0.9) / 2);
    brickHouse(city, hx, hz, w, 3.6, { balcony: i % 2 === 0, badgirH: i % 3 === 0 ? 1.8 : undefined });
    addCollider(CITY.x + hx, CITY.z + hz, r);
  });

  // Сады: кипарисы, пруд, скамейки
  for (let i = 0; i < 10; i++) {
    const a = (i / 10) * Math.PI * 2;
    cypress(city, -31.5 + Math.cos(a) * 11, 77.9 + Math.sin(a) * 11, 0.3, 0.9 + (i % 3) * 0.2);
  }
  const pond = new THREE.Mesh(new THREE.CircleGeometry(5.5, 24), MAT.water);
  pond.rotation.x = -Math.PI / 2;
  pond.position.set(-31.5, 0.5, 77.9);
  city.add(pond);
  addCollider(CITY.x - 31.5, CITY.z + 77.9, 6);
  for (const [bx, bz, ry] of [[-38, 77.9, 0.3], [-25, 77.9, -0.3], [-31.5, 71, 0], [-31.5, 84.8, Math.PI]] as const) {
    const bench = new THREE.Mesh(new THREE.BoxGeometry(2.2, 0.45, 0.6), MAT.wood);
    bench.position.set(bx, 0.65, bz);
    bench.rotation.y = ry;
    bench.castShadow = true;
    city.add(bench);
    addCollider(CITY.x + bx, CITY.z + bz, 1.3);
  }
  // По фонарю на квартал (ночная подсветка через общий механизм lights)
  for (const [lx, lz] of [[84, 8], [11.7, -75.2], [59.4, 51.4], [-31.5, 69.9]] as const) {
    const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.14, 0.2, 4.4, 6), MAT.dark);
    pole.position.set(lx, 2.4, lz);
    const bowl = new THREE.Mesh(new THREE.CylinderGeometry(0.55, 0.3, 0.5, 8), MAT.gold);
    bowl.position.set(lx, 4.8, lz);
    city.add(pole, bowl);
    lights.push({ x: CITY.x + lx, z: CITY.z + lz });
    addCollider(CITY.x + lx, CITY.z + lz, 0.5);
  }
}

export function buildCity(scene: THREE.Scene): THREE.Group {
  const city = new THREE.Group();
  // База города — сам меш: бугор плиты учитывается отдельно в groundHeight,
  // иначе весь город (стены/ворота) висит над землёй
  const baseY = meshHeight(CITY.x, CITY.z);
  city.position.set(CITY.x, baseY, CITY.z);

  /**
   * Высота земли в локальных координатах группы города.
   *
   * Группа стоит на высоте ЦЕНТРА, а стены и башни — на радиусе 116, где
   * земля уже на другой высоте. Из-за этого всё, что стояло на жёстко
   * зашитой высоте, висело в воздухе: на снимке под башней было видно землю,
   * а по стене шла щель с тенью на песке.
   */
  const localY = (worldX: number, worldZ: number): number =>
    meshHeight(worldX, worldZ) - baseY;
  const landscapeCount = COLLIDERS.length;
  // Копируем коллайдеры ландшафта (деревья/камни), сохранённые до обнуления
  const landscapeCopy: typeof COLLIDERS = [];
  for (let i = 0; i < landscapeCount; i++) landscapeCopy.push(COLLIDERS[i]);
  (city as any).__landscapeColliders = landscapeCopy;
  COLLIDERS.length = 0; // город строится один раз за сессию мира

  const gateAngle = Math.atan2(-CITY.z, -CITY.x); // направление к точке возрождения (0,0)
  const lights: { x: number; z: number; y?: number }[] = []; // фонари (свет — в world3d)

  // Площадь (плитка с узором)
  const plaza = new THREE.Mesh(
    new THREE.CylinderGeometry(CITY.radius * 0.92, CITY.radius, 0.5, 36),
    new THREE.MeshStandardMaterial({ color: 0xc8b48a, roughness: 0.95, map: plazaTexture(10) }),
  );
  plaza.position.y = 0.05;
  plaza.receiveShadow = true;
  city.add(plaza);

  // Фонтан в центре площади
  const fountain = new THREE.Group();
  const basin = new THREE.Mesh(new THREE.CylinderGeometry(3.4, 3.8, 1.1, 12), MAT.sandstoneDark);
  basin.position.y = 0.55;
  basin.castShadow = true; basin.receiveShadow = true;
  const water = new THREE.Mesh(new THREE.CylinderGeometry(3.05, 3.05, 0.16, 12), MAT.water);
  water.position.y = 1.02;
  const column = new THREE.Mesh(new THREE.CylinderGeometry(0.5, 0.8, 2.4, 8), MAT.sandstone);
  column.position.y = 1.9;
  column.castShadow = true;
  const bowl = new THREE.Mesh(new THREE.CylinderGeometry(1.5, 1.1, 0.35, 10), MAT.tealDome);
  bowl.position.y = 3.1;
  const jet = new THREE.Mesh(new THREE.ConeGeometry(0.24, 1.5, 6), MAT.water);
  jet.position.y = 4.1;
  jet.rotation.x = Math.PI;
  fountain.add(basin, water, column, bowl, jet);
  fountain.position.set(6, 0.3, 6);
  city.add(fountain);
  addCollider(CITY.x + 6, CITY.z + 6, 4.2);

  // Городские ворота: обзорные башни по бокам, арка, створки и зубцы
  {
    const gx = Math.cos(gateAngle) * CITY.radius, gz = Math.sin(gateAngle) * CITY.radius;
    const dirX = Math.cos(gateAngle + Math.PI / 2), dirZ = Math.sin(gateAngle + Math.PI / 2);
    const inward = (k: number) => ({ x: gx - Math.cos(gateAngle) * k, z: gz - Math.sin(gateAngle) * k });
    for (const side of [-1, 1]) {
      // Привратные башни — СНАРУЖИ стены, по бокам прохода: иначе сливаются с торцами
      const tx = gx + dirX * side * 9 + Math.cos(gateAngle) * 3;
      const tz = gz + dirZ * side * 9 + Math.sin(gateAngle) * 3;
      // Корпус обзорной башни. ТУТ БЫЛО ЗАШИТО 7.5: башня стоит у ворот, а
      // земля там ниже центра города, и башня висела в воздухе.
      const base = localY(CITY.x + tx, CITY.z + tz);
      const tower = new THREE.Mesh(new THREE.CylinderGeometry(2.6, 3.4, 15, 10), MAT.sandstoneDark);
      tower.position.set(tx, base + 7.5, tz);
      tower.castShadow = true;
      // Площадка с перилами и зубцами по кругу
      const deck = new THREE.Mesh(new THREE.CylinderGeometry(3.4, 3.0, 0.7, 10), MAT.sandstone);
      deck.position.set(tx, base + 15.2, tz);
      deck.castShadow = true;
      const railing = new THREE.Mesh(new THREE.TorusGeometry(3.2, 0.14, 6, 12), MAT.wood);
      railing.position.set(tx, base + 16.1, tz);
      railing.rotation.x = Math.PI / 2;
      city.add(deck, railing);
      // Стойки перил: без них кольцо висело в воздухе
      for (let p = 0; p < 6; p++) {
        const pa = (p / 6) * Math.PI * 2;
        const post = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.07, 0.7, 6), MAT.wood);
        post.position.set(tx + Math.cos(pa) * 3.2, 15.9, tz + Math.sin(pa) * 3.2);
        city.add(post);
      }
      for (let m = 0; m < 8; m++) {
        const ma = (m / 8) * Math.PI * 2;
        const merlon = new THREE.Mesh(new THREE.BoxGeometry(1.0, 0.8, 0.5), MAT.sandstoneDark);
        merlon.position.set(tx + Math.cos(ma) * 3.2, 16.0, tz + Math.sin(ma) * 3.2);
        merlon.rotation.y = -ma;
        merlon.castShadow = true;
        city.add(merlon);
      }
      // Чаша огня на площадке (открытая обзорная площадка — шатра нет,
      // иначе крыша парила бы над настилом, а чаша пряталась внутри конуса)
      const brazier = new THREE.Mesh(new THREE.CylinderGeometry(0.5, 0.3, 0.5, 8), MAT.gold);
      brazier.position.set(tx, 15.8, tz);
      const fire = new THREE.Mesh(new THREE.ConeGeometry(0.35, 1, 6), new THREE.MeshStandardMaterial({ color: 0xff8c30, emissive: 0xff6a10, emissiveIntensity: 1.8 }));
      fire.position.set(tx, 16.5, tz);
      city.add(tower, brazier, fire);
      addCollider(CITY.x + tx, CITY.z + tz, 3.4);
      lights.push({ x: CITY.x + tx, z: CITY.z + tz, y: baseY + 16.2 });
    }
    // Арка с зубцами. Балка идёт ВДОЛЬ стены (по касательной):
    // rotation.y = -gateAngle кладёт ось X радиально — был разворот на 90°.
    const tangentRot = -gateAngle - Math.PI / 2;
    const lintel = new THREE.Mesh(new THREE.BoxGeometry(11.6, 1.8, 2.6), MAT.sandstone);
    lintel.position.set(gx, 10.5, gz);
    lintel.rotation.y = tangentRot;
    lintel.castShadow = true;
    // Шахский герб — плакетка на внешней грани балки (по центру, вместо зубца)
    const keystone = new THREE.Mesh(new THREE.BoxGeometry(1.4, 1.6, 0.4), MAT.tealDome);
    keystone.position.set(gx + Math.cos(gateAngle) * 1.5, 10.9, gz + Math.sin(gateAngle) * 1.5);
    keystone.rotation.y = tangentRot;
    keystone.castShadow = true;
    city.add(lintel, keystone);
    for (let m = -2; m <= 2; m++) {
      if (m === 0) continue; // место под шахский герб
      const merlon = new THREE.Mesh(new THREE.BoxGeometry(1.2, 0.7, 0.5), MAT.sandstoneDark);
      merlon.position.set(gx + dirX * m * 2.4, 11.8, gz + dirZ * m * 2.4);
      merlon.rotation.y = tangentRot;
      merlon.castShadow = true;
      city.add(merlon);
    }
    // Створки ворот: тёмное дерево, приоткрыты для прохода по центру.
    // Широкая грань — тоже вдоль стены; высота дотянута до балки (9.6), иначе щель.
    for (const side of [-1, 1]) {
      const inner = inward(0.4);
      const door = new THREE.Mesh(new THREE.BoxGeometry(3.4, 9.6, 0.4), MAT.wood);
      door.position.set(inner.x + dirX * side * 2.6, 4.8, inner.z + dirZ * side * 2.6);
      door.rotation.y = tangentRot + side * 0.22;
      door.castShadow = true;
      // оковка створок
      for (let b = 0; b < 3; b++) {
        const band = new THREE.Mesh(new THREE.BoxGeometry(3.5, 0.18, 0.5), MAT.dark);
        band.position.set(0, -3.2 + b * 3.0, 0.05);
        door.add(band);
      }
      city.add(door);
    }
    // Крылья стен от дверей к башням: закрывают боковые щели.
    // Отрезок A->B вдоль касательной: поворот кладёт локальный +X на (B-A).
    for (const sgn of [-1, 1]) {
      const ax = gx + dirX * sgn * 4.3, az = gz + dirZ * sgn * 4.3;
      const bx = gx + dirX * sgn * 9.2, bz = gz + dirZ * sgn * 9.2;
      const segLen = Math.hypot(bx - ax, bz - az);
      const wing = new THREE.Mesh(new THREE.BoxGeometry(segLen, 5, 1.2), MAT.sandstoneDark);
      wing.position.set((ax + bx) / 2, 2.5, (az + bz) / 2);
      wing.rotation.y = Math.atan2(-(bz - az), bx - ax);
      wing.castShadow = true; wing.receiveShadow = true;
      city.add(wing);
      addCollider(CITY.x + (ax + bx) / 2, CITY.z + (az + bz) / 2, segLen / 2 + 0.6);
    }
    // фонарь над проходом — висит на стержне под балкой (низ балки 9.6)
    const gateRod = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.06, 0.6, 6), MAT.dark);
    gateRod.position.set(gx, 9.75, gz);
    const gateLamp = new THREE.Mesh(new THREE.BoxGeometry(0.9, 0.9, 0.9), new THREE.MeshStandardMaterial({ color: 0xffd980, emissive: 0xffa530, emissiveIntensity: 1.3 }));
    gateLamp.position.set(gx, 9.1, gz);
    city.add(gateRod, gateLamp);
    lights.push({ x: CITY.x + gx, z: CITY.z + gz, y: baseY + 9.4 });
  }

  // Базарная аркада
  {
    const streetDir = gateAngle;
    for (let i = 1; i <= 5; i++) {
      const t = -i * 7.5;
      const ax = Math.cos(streetDir) * t * 0.4;
      const az = Math.sin(streetDir) * t * 0.4 + 26;
      for (const side of [-1, 1]) {
        const pillar = new THREE.Mesh(new THREE.BoxGeometry(1.1, 4.4, 1.1), MAT.sandstone);
        pillar.position.set(ax + Math.cos(streetDir + Math.PI / 2) * 3.1 * side, 2.2, az + Math.sin(streetDir + Math.PI / 2) * 3.1 * side);
        pillar.castShadow = true;
        city.add(pillar);
        addCollider(CITY.x + pillar.position.x, CITY.z + pillar.position.z, 0.9);
      }
      const top = new THREE.Mesh(new THREE.BoxGeometry(8.4, 0.7, 1.6), MAT.sandstoneDark);
      top.position.set(ax, 4.7, az);
      top.rotation.y = -streetDir;
      top.castShadow = true;
      city.add(top);
      const awning = new THREE.Mesh(new THREE.BoxGeometry(7.6, 0.08, 2.6), i % 2 ? MAT.clothTeal : MAT.clothRed);
      awning.position.set(ax, 4.1, az);
      awning.rotation.y = -streetDir;
      awning.rotation.x = 0.05;
      city.add(awning);
    }
  }

  // Стены: дуга по кругу с проёмом ровно под ворота.
  //
  // ВЫСОТА И РАЗМЕРЫ УДВОЕНЫ ПО РЕШЕНИЮ ВЛАДЕЛЬЦА (08.10.2026).
  // Раньше стена была оболочкой нулевой толщины высотой 6 м с 168 кубами
  // зубцов. Теперь это каменная кладка из настоящей модели: толщина 13.06 м,
  // ширина сегмента 33.30 м, 22 сегмента, зубцы 84 шт по 3.2 × 1.6 × 1.2 м.
  // Сами числа живут на верхнем уровне модуля (WALL_TOP, СТЕНА_ГЛУБИНА и
  // соседи), потому что навигатор меряет город до внутренней грани.
  const OPEN = 9.5 / CITY.radius; // половина угла проёма ворот (рад)

  // Высота стены отсчитывается от земли ПОД КАЖДЫМ СЕГМЕНТОМ (земляПод),
  // а не от одной общей отметки. Группа города стоит на высоте ЦЕНТРА, а дуга
  // идёт по радиусу 116, где рельеф меняется на метры: усреднение или одна
  // точка уводили половину окружности в грунт, а вторую оставляли висеть над
  // землёй с тенью на песке. Именно с этой поломкой стена когда-то и жила.

  // Сколько сегментов влезает в дугу без щелей.
  //
  // Берётся МИНИМАЛЬНОЕ число, при котором соседние сегменты НАХЛЁСТЫВАЮТСЯ.
  // Прямые отрезки на окружности дают две ошибки: при нехватке сегментов
  // между ними щели, при избытке они взаимопроникают. Щель видна сразу —
  // сквозь неё видно город, — а нахлёст не виден вовсе, потому что кладка
  // одного куска ложится на кладку другого.
  const дуга = CITY.radius * (Math.PI * 2 - OPEN * 2);
  let СТЕНА_ЧИСЛО = Math.ceil(дуга / СТЕНА_ШИРИНА);
  while (
    СТЕНА_ЧИСЛО < 400
    && 2 * CITY.radius * Math.sin((Math.PI * 2 - OPEN * 2) / СТЕНА_ЧИСЛО / 2) > СТЕНА_ШИРИНА
  ) СТЕНА_ЧИСЛО++;
  const СТЕНА_ШАГ = (Math.PI * 2 - OPEN * 2) / СТЕНА_ЧИСЛО;
  const СТЕНА_ХОРДА = 2 * CITY.radius * Math.sin(СТЕНА_ШАГ / 2);
  // Нахлёст обязан быть не меньше нуля: отрицательный означал бы щель,
  // сквозь которую видно город. Это единственное место, где такое возможно,
  // поэтому проверяется прямо здесь, а не в тесте.
  if (СТЕНА_ШИРИНА < СТЕНА_ХОРДА) {
    throw new Error(`стена рассыпается: сегмент ${СТЕНА_ШИРИНА.toFixed(2)} м уже хорды ${СТЕНА_ХОРДА.toFixed(2)} м`);
  }
  // Коллайдеры ставятся по ВНУТРЕННЕЙ грани стены, а не по осевой.
  // Раньше толщина была нулевой, поэтому «ось» и «внутренняя грань»
  // совпадали и игрок упирался в стену с расстояния 2.2 м. Теперь ось
  // проходит в середине каменного массива, и коллайдер на оси оставил бы
  // 6.5 м прохода ВНУТРИ стены — игрок заходил бы в кладку по пояс.
  const СТЕНА_ВНУТРЕННИЙ_РАДИУС = CITY_INNER;

  // Зубцы: кубы, как и раньше, но вдвое крупнее и вдвое реже — иначе они
  // слиплись бы в сплошной парапет. Шаг по дуге удваивается вместе со всей
  // стеной, поэтому числа 168 -> 84 и 1.6 -> 3.2 связаны между собой.
  const ЗУБЕЦ_ШИРИНА = 3.2, ЗУБЕЦ_ВЫСОТА = 1.6, ЗУБЕЦ_ГЛУБИНА = 1.2;
  const merlonCount = 84;

  /**
   * Земля под точкой стены, в локальных координатах города.
   *
   * Стены теперь двадцать две штуки и стоят каждая по-своему: дуга идёт по
   * окружности 116, где рельеф меняется на метры. Общая отметка оставила бы
   * часть сегментов висящими или утонувшими — ровно та поломка, из-за
   * которой стена когда-то уходила в землю на половине окружности.
   */
  const земляПод = (phi: number): number =>
    localY(CITY.x + Math.cos(phi) * CITY.radius, CITY.z + Math.sin(phi) * CITY.radius);

  // Зубцы по гребню стены.
  //
  // Стоят на гребне каждого сегмента, а не на общей высоте: гребень кладки
  // идёт по земле, и общая отметка оставила бы зубец висящим над отдельным
  // сегментом в низине рельефа.
  const merlonGeo = new THREE.BoxGeometry(ЗУБЕЦ_ШИРИНА, ЗУБЕЦ_ВЫСОТА, ЗУБЕЦ_ГЛУБИНА);
  const merlons = new THREE.InstancedMesh(merlonGeo, MAT.sandstoneDark, merlonCount);
  merlons.castShadow = true;
  {
    const mq = new THREE.Quaternion();
    const mv = new THREE.Vector3();
    const ms = new THREE.Vector3(1, 1, 1);
    const mm = new THREE.Matrix4();
    const stepA = (Math.PI * 2 - OPEN * 2) / merlonCount;
    for (let m = 0; m < merlonCount; m++) {
      const phi = gateAngle + OPEN + stepA * (m + 0.5);
      // По осевой линии стены и на её гребне: под этим углом стоит сегмент,
      // и зубец садится ровно на его кладку.
      const на = земляПод(phi) + WALL_TOP + ЗУБЕЦ_ВЫСОТА / 2;
      mv.set(Math.cos(phi) * CITY.radius, на, Math.sin(phi) * CITY.radius);
      mq.setFromEuler(new THREE.Euler(0, -phi, 0));
      mm.compose(mv, mq, ms);
      merlons.setMatrixAt(m, mm);
    }
  }
  city.add(merlons);

// СЕГМЕНТЫ СТЕНЫ
  //
  // ТРИ НАХОДКИ ПО ЖАЛОБАМ ИГРОКА: «стена полупрозрачная», «все равно есть
  // дыры», «внутренности до сих пор не заполнены». Это ОДНА причина и ОДНА
  // вторая, и обе теперь понятны.
  //
  // ПРИЧИНА ПЕРВАЯ — ПРОЗРАЧНОСТЬ, и она была в конвертере, не в игре.
  // Модель выходила с `"alphaMode": "BLEND"`. В three.js BLEND включает
  // `material.transparent = true`, и стена уезжала в прозрачный проход: задние
  // грани смешивались с передними, и сквозь камень было видно всё — полости,
  // стыки и собственную изнанку. При этом прозрачности в модели НОЛЬ: альфа у
  // всех трёх текстур равна единице в каждом пикселе. То есть материал был
  // объявлен прозрачным без единой причины, и в пакете укреплений альфа была
  // связана с текстурой, хотя отдельную альфа-карту конвертер отбросил.
  // Конвертер теперь снимает такую связь — но по данным, а не всегда: если хоть
  // один пиксель прозрачный, BLEND остаётся (листва, вода, решётки).
  //
  // ПОЧЕМУ ЭТО ЗАКРЫВАЕТ ПОЛОСТЬ БЕЗ ЗАГЛУШКИ. В модели стоит
  // `"doubleSided": true`, то есть оболочка и так двусторонняя. Пока материал
  // был прозрачным, полость была видна насквозь. Как только материал стал
  // непрозрачным, луч изнутри полости упирается в изнанку оболочки — а это
  // камень. Снаружи луч упирается в наружную кладку. Полости не видно ни с
  // какой стороны, и заполнять её геометрией не требуется.
  //
  // ПРО ЗАГЛУШКУ, КОТОРАЯ БЫЛА И НЕ РАБОТАЛА. Стояла уменьшенная на 3% копия
  // модели с обратной стороной. Но это ТА ЖЕ полая оболочка, только меньше:
  // закрывать ею полость нечем, а прозрачный материал делал её невидимой вовсе,
  // то есть «замуровывать» было нечем. Задачу решала прозрачность, а заглушка
  // только добавляла 19 копий и риск просветов. Снята.
  //
  // ПРИЧИНА ВТОРАЯ — НАСТОЯЩИЕ ДЫРЫ В СТЫКАХ, и их геометрия не зависит ни от
  // чего выше. Два прямоугольных сегмента, повёрнутых друг к другу на 18
  // градусов, ВСЕГДА оставляют V-образный вырез с внутренней и с наружной
  // стороны. Нахлёст в 1.05 м его не убирает — он лишь сдвигает: вырез
  // перемещается, но остаётся, и сквозь него видно улицу.
  //
  // Чем вырез закрывается. В стык ставится ещё одно тело, повёрнутое по
  // биссектрисе угла между соседями. Оно входит в вырез целиком, и стена
  // становится непрерывной. В пакете укреплений для этого есть
  // `Wall-Type01CornerPiece`, но он вдвое выше стены (39 м по высоте при
  // 15-метровой стене) и превратил бы стену в частокол башен. Заполнитель из
  // того же сегмента сохраняет вид стены и закрывает вырез.
  const поставитьСегмент = (модель: THREE.Object3D, phi: number): void => {
    модель.position.set(
      Math.cos(phi) * CITY.radius,
      земляПод(phi) - WALL_SUNK,
      Math.sin(phi) * CITY.radius,
    );
    модель.scale.setScalar(СТЕНА_МАСШТАБ);
    // Модель лежит вдоль оси X, а стена идёт по касательной окружности, то
    // есть по вектору (−sin φ, 0, cos φ). Разворот считается именно от него:
    // сегмент, повёрнутый по φ вместо этого, встал бы на радиус, а не вдоль
    // стены, и рядом вырастала бы гора из кладки.
    модель.rotation.y = Math.atan2(-Math.cos(phi), -Math.sin(phi));
    модель.traverse((o) => {
      const m = o as THREE.Mesh;
      if (!m.isMesh) return;
      m.castShadow = true;
      m.receiveShadow = true;
    });
    city.add(модель);
    // Полость внутри стены: заполняем цельным камнем, иначе через щели виден свет неба.
    const fillTop = земляПод(phi) + WALL_TOP;
    const fillBottom = земляПод(phi) - WALL_SUNK;
    const fillHeight = fillTop - fillBottom;
    const fillBox = new THREE.Mesh(
      new THREE.BoxGeometry(СТЕНА_ШИРИНА - 1.2, fillHeight - 0.04, СТЕНА_ГЛУБИНА),
      MAT.sandstoneDark,
    );
    fillBox.position.set(
      Math.cos(phi) * CITY.radius,
      fillBottom + (fillHeight - 0.04) / 2,
      Math.sin(phi) * CITY.radius,
    );
    fillBox.rotation.y = модель.rotation.y;
    fillBox.castShadow = true;
    fillBox.receiveShadow = true;
    city.add(fillBox);
  };

  void loadDecorModel(СТЕНА_МОДЕЛЬ).then((модель) => {
    if (!модель) return;
    // Основные сегменты: по одному на шаг, центрами между стыками.
    for (let i = 0; i < СТЕНА_ЧИСЛО; i++) {
      поставитьСегмент(модель.clone(), gateAngle + OPEN + СТЕНА_ШАГ * (i + 0.5));
    }
    // Заполнители стыков: по одному на стык, ровно на угле между соседями,
    // то есть по биссектрисе. Их СТЕНА_ЧИСЛО − 1, а не СТЕНА_ЧИСЛО: последний
    // стык упирается в начало дуги, и там проём ворот — заполнять нечего.
    for (let j = 1; j < СТЕНА_ЧИСЛО; j++) {
      поставитьСегмент(модель.clone(), gateAngle + OPEN + СТЕНА_ШАГ * j);
    }
  });
  // Коллайдеры вдоль ВНУТРЕННЕЙ грани стены.
  //
  // ШАГ ТЕПЕРЬ 4 М, А НЕ 5. При шаге 5 и радиусе 2.2 между соседними
  // кругами оставалась щель 0.6 м: кольцо коллайдеров было не кольцом, а
  // гирляндой из кружков. Игрок радиусом 1.0 м в такую щель не проходит, но
  // камера радиусом 0.35 м — проходит, и вместе с ней пролезает всё, что
  // двигается по сдвигу камеры.
  //
  // При шаге 4 радиус 2.2 даёт ПЕРЕКРЫТИЕ 0.4 м: круги смыкаются с запасом,
  // и кольцо становится непрерывным. Коллайдеров становится 178 вместо 142 —
  // на 36 больше, что для списка из циркулей ничего не стоит.
  const ШАГ_КОЛЛАЙДЕРА = 4;
  const КОЛЛАЙДЕР_РАДИУС = 2.2;
  for (let phi = gateAngle + OPEN; phi < gateAngle + Math.PI * 2 - OPEN; phi += ШАГ_КОЛЛАЙДЕРА / CITY.radius) {
    addCollider(
      CITY.x + Math.cos(phi) * СТЕНА_ВНУТРЕННИЙ_РАДИУС,
      CITY.z + Math.sin(phi) * СТЕНА_ВНУТРЕННИЙ_РАДИУС,
      КОЛЛАЙДЕР_РАДИУС,
    );
  }
  // Башни по углам
  //
  // ЧТО БЫЛО. Восемь цилиндров с конусными шляпами: CylinderGeometry(3, 3.6,
  // 9) и ConeGeometry(3.6, 2.6). Это читалось как «город окружён трубами с
  // колпаками», и при выходе к воротам было видно в упор.
  //
  // ЧТО СТАЛО. Настоящая модель `onion-dome-tower.glb` — та же, что уже стоит
  // к востоку от мечети (§54). Она уже в игре: сжата Draco, лежит в
  // манифесте, текстуры на месте. Сеть одна: loadDecorModel кэширует по пути,
  // так что восемь башен — это одна загрузка и восемь копий.
  //
  // МАСШТАБ СЧИТАН, А НЕ ВЫБРАН. Модель в натуральном виде 8.972 × 25.504 ×
  // 10.36 м, начало координат в основании по центру. Прежняя цель была 11 м:
  //   11 / 25.504 = 0.4313.
  // Теперь цель 22 м (см. ниже), масштаб 22 / 25.504 = 0.8626, след башни
  // 10.36 × 0.8626 = 8.94 м. След почти вдвое больше прежнего, потому что
  // высота выросла вдвое: модель стройная, и при 11 м башня была тоньше стены.
  //
  // РАДИУС КОЛЛАЙДЕРА ИДЁТ ОТ СЛЕДА, А НЕ ВЫПИСАН. Прежний r = 4.1 брался от
  // примитива с радиусом 3.6 плюс запас; настоящая модель следом не обладает,
  // значит число надо считать. Сейчас r = 8.94 / 2 + 0.4 = 4.87.
  //
  // БАШНЯ ВЫШЕ СТЕНЫ, И ЭТО ТЕПЕРЬ СЧИТАЕТСЯ, А НЕ УТВЕРЖДАЕТСЯ.
  //
  // Башня стоит на осевой линии стены, то есть внутри её каменного массива
  // толщиной 13.06 м, и должна торчать над гребнем с зубцами. Гребень 12 м,
  // зубец 1.6 м — итого 13.6 м. Прежние 11 м были выше стены в 6 м; после
  // удвоения стены те же 11 м оказались НИЖЕ гребня, и башня утонула бы в
  // кладке по самый купол. Цель считается от стены, поэтому если её
  // поменяют, башня поедет вместе с ней.
  const БАШНЯ_МОДЕЛЬ = 'decor/onion-dome-tower.glb';
  const БАШНЯ_ВЫСОТА = 25.504;   // высота модели в натуральном виде, м
  const БАШНЯ_ЦЕЛЬ = WALL_TOP + ЗУБЕЦ_ВЫСОТА + 8.4; // 22 м: на 8.4 м над зубцами
  const БАШНЯ_МАСШТАБ = БАШНЯ_ЦЕЛЬ / БАШНЯ_ВЫСОТА;
  const БАШНЯ_СЛЕД = 10.36 * БАШНЯ_МАСШТАБ;
  const БАШНЯ_РАДИУС = БАШНЯ_СЛЕД / 2 + 0.4;
  const БАШНЯ_ТОЧКИ: { x: number; z: number }[] = [];
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * Math.PI * 2;
    const wx = CITY.x + Math.cos(a) * CITY.radius;
    const wz = CITY.z + Math.sin(a) * CITY.radius;
    БАШНЯ_ТОЧКИ.push({ x: wx, z: wz });
    addCollider(wx, wz, БАШНЯ_РАДИУС);
  }
  void loadDecorModel(БАШНЯ_МОДЕЛЬ).then((модель) => {
    if (!модель) return;
    for (const т of БАШНЯ_ТОЧКИ) {
      const башня = модель.clone();
      // База по земле под каждой точкой: стена идёт по окружности 116, где
      // рельеф меняется, и общая высота оставила бы одну из восьми башен
      // висящей или утонувшей.
      башня.position.set(
        т.x - CITY.x,
        localY(т.x, т.z),
        т.z - CITY.z,
      );
      башня.scale.setScalar(БАШНЯ_МАСШТАБ);
      // Модель нарисована лицом в одну сторону; башня круглая в плане, но
      // с приставками и лестницей, и одинаковый разворот на всех восьми
      // читается как «их штампавали». Разводим по кругу.
      башня.rotation.y = (т.x * 0.7 + т.z * 1.3) % (Math.PI * 2);
      башня.traverse((o) => {
        const m = o as THREE.Mesh;
        if (!m.isMesh) return;
        m.castShadow = true;
        m.receiveShadow = true;
      });
      city.add(башня);
    }
  });

  // ── Мечеть в центре ──
  const mosque = new THREE.Group();
  const base = new THREE.Mesh(new THREE.BoxGeometry(24, 8, 18), MAT.sandstone);
  base.position.y = 4; base.castShadow = true; base.receiveShadow = true;
  mosque.add(base);
  const portal = new THREE.Mesh(new THREE.BoxGeometry(7, 12, 2), MAT.sandstoneDark);
  portal.position.set(0, 6, 9.4);
  const arch = new THREE.Mesh(new THREE.BoxGeometry(3.4, 6, 0.8), MAT.dark);
  arch.position.set(0, 3, 10.5);
  mosque.add(portal, arch);
  const dome = new THREE.Mesh(new THREE.SphereGeometry(7.5, 18, 14), MAT.tealDome);
  dome.scale.set(1, 1.15, 1);
  dome.position.y = 12.5;
  const domeSpike = new THREE.Mesh(new THREE.ConeGeometry(0.7, 3, 8), MAT.gold);
  domeSpike.position.y = 21.6;
  mosque.add(dome, domeSpike);
  for (const side of [-1, 1]) {
    const shaft = new THREE.Mesh(new THREE.CylinderGeometry(1.1, 1.4, 22, 10), MAT.sandstoneDark);
    shaft.position.set(side * 15, 11, 6);
    const balcony = new THREE.Mesh(new THREE.CylinderGeometry(1.9, 1.9, 0.9, 10), MAT.gold);
    balcony.position.set(side * 15, 17, 6);
    const top = new THREE.Mesh(new THREE.ConeGeometry(1.5, 4, 10), MAT.tealDome);
    top.position.set(side * 15, 24, 6);
    const finial = new THREE.Mesh(new THREE.SphereGeometry(0.5, 8, 8), MAT.gold);
    finial.position.set(side * 15, 26.4, 6);
    shaft.castShadow = true;
    mosque.add(shaft, balcony, top, finial);
  }
  mosque.position.set(0, 0.3, -8);
  city.add(mosque);
  // Минареты — отдельные коллайдеры (база мечети уже накрыта сеткой выше)
  for (const side of [-1, 1]) {
    addCollider(CITY.x + side * 15, CITY.z - 8 + 6, 1.6);
  }

  // Жилые дома: купольные одно- и двухэтажные, с балконами
  const rng = (() => { let s = 7; return () => (s = (s * 16807) % 2147483647) / 2147483647; })();
  const canopies = [MAT.clothRed, MAT.clothTeal, MAT.clothPurple];
  // Занятые места площади: мечеть, фонтан, прилавки, аркада, NPC —
  // дома ставятся только с учётом дистанции до них (см. проверку ниже)
  // научный центр): их позиции — в client/.../game3d/interiors.ts (SPOTS),
  // дублируются здесь числом, чтобы не создавать циклический импорт
  // terrain<->interiors (он роняет загрузку мира: CITY ещё в TDZ).
  // При переносе домов править ОБА места!
  const placed: { x: number; z: number; r: number }[] = [
    { x: 0, z: -8, r: 13.5 }, // мечеть
    { x: 6, z: 6, r: 5.5 },   // фонтан
    { x: -18.6, z: -69.5, r: 8 }, // конюшня
    { x: 36.0, z: -62.4, r: 8 },  // казарма
    { x: 67.7, z: -24.6, r: 8 },  // мастерская
    { x: 67.7, z: 24.6, r: 8 },   // таверна
    { x: 24.6, z: 67.7, r: 8 },   // обсерватория
    { x: -65.2, z: 30.4, r: 8 },  // научный центр
    { x: 84, z: 0, r: 13 },       // базарный квартал
    { x: 11.7, z: -83.2, r: 13 }, // ремесленный квартал
    { x: 59.4, z: 59.4, r: 15 },  // жилой квартал
    // Семь кольцевых домов квартала (см. homeOffsets выше): выступают за r=15,
    // каждый резервируем отдельно, иначе процедурные дома встают впритык (1+1=2)
    ...[[-14, -7, 5], [0, -13, 6], [14, -7, 4.5], [-14, 3, 5.5], [14, 3, 4.5], [-6, 12, 5], [6, 12, 6]]
      .map(([ox, oz, w]) => ({ x: 59.4 + ox, z: 59.4 + oz, r: Math.hypot(w, w * 0.9) / 2 })),
    { x: -31.5, z: 77.9, r: 15 }, // сады
    ...[0, 1, 2, 3, 4, 5, 6].map((i) => {
      const a = Math.PI * 0.6 + (i / 7) * Math.PI * 0.8;
      return { x: Math.cos(a) * 20, z: -8 + Math.sin(a) * 20, r: 2.6 };
    }),
    ...[1, 2, 3, 4, 5].map((i) => {
      const t = -i * 7.5;
      return { x: Math.cos(gateAngle) * t * 0.4, z: Math.sin(gateAngle) * t * 0.4 + 26, r: 5 };
    }),
    ...[[-8, 10], [20, 16], [-24, -6], [12, -2], [16, -10], [-14, -14], [-4, 22], [6, -20], [26, 6], [2, -26]]
      .map(([x, z]) => ({ x, z, r: 2 })), // NPC Исфахана (npc.ts)
  ];
  // Corridor reservations for quarter avenues (r=30..70): procedural houses must avoid roads.
  for (const q of [{ x: 84, z: 0 }, { x: 11.7, z: -83.2 }, { x: 59.4, z: 59.4 }, { x: -31.5, z: 77.9 }]) {
    const len = Math.hypot(q.x, q.z);
    const steps = Math.ceil((len - 30) / 8);
    for (let i = 0; i <= steps; i++) {
      const t = 30 + (i / Math.max(1, steps)) * (len - 30);
      placed.push({ x: (q.x / len) * t, z: (q.z / len) * t, r: 4 });
    }
  }
  for (let i = 0; i < 44; i++) {
    const a = rng() * Math.PI * 2;
    const r = 18 + rng() * 78;
    const x = Math.cos(a) * r, z = Math.sin(a) * r;
    const w = 4 + rng() * 4, h = 3 + rng() * 2.5;
    // Занятые места: мечеть, фонтан, прилавки, аркада, NPC (npc.ts).
    // Дома не должны прилипать друг к другу и к постройкам.
    const houseR = Math.max(2.4, Math.hypot(w, w * 0.9) / 2); // коллайдер по диагонали (дома вращаются случайно)
    if (placed.some(p => Math.hypot(p.x - x, p.z - z) < p.r + houseR + 3.0)) continue;
    placed.push({ x, z, r: houseR });
    const house = new THREE.Group();
    const twoStory = rng() < 0.35;
    const body = new THREE.Mesh(new THREE.BoxGeometry(w, h, w * 0.9), MAT.sandstone);
    body.position.y = h / 2; body.castShadow = true; body.receiveShadow = true;
    house.add(body);
    if (twoStory) {
      const upper = new THREE.Mesh(new THREE.BoxGeometry(w * 0.8, h * 0.7, w * 0.75), MAT.sandstoneDark);
      upper.position.y = h + h * 0.35; upper.castShadow = true; upper.receiveShadow = true;
      const balcony = new THREE.Mesh(new THREE.BoxGeometry(w * 0.55, 0.14, 1.1), MAT.wood);
      balcony.position.set(0, h - 0.1, w * 0.45);
      const rail = new THREE.Mesh(new THREE.BoxGeometry(w * 0.55, 0.5, 0.08), MAT.wood);
      rail.position.set(0, h + 0.18, w * 0.45 + 0.5);
      house.add(upper, balcony, rail);
    }
    const domeR = Math.min(w, h * 1.4) * 0.55;
    const domeY = twoStory ? h + h * 0.7 : h;
    const hd = new THREE.Mesh(new THREE.SphereGeometry(domeR, 10, 8), rng() > 0.55 ? MAT.tealDome : MAT.sandstoneDark);
    hd.scale.y = 0.72;
    hd.position.y = domeY;
    house.add(hd);
    const window1 = new THREE.Mesh(new THREE.BoxGeometry(0.7, 1.1, 0.1), MAT.dark);
    window1.position.set(0, h * 0.55, w * 0.45 + 0.02);
    house.add(window1);
    // Восточный колорит столицы: бадгиры и балконы на части домов
    if (rng() < 0.45) badgir(house, w * 0.26, -w * 0.2, h, 1.8 + rng() * 1.2);
    if (rng() < 0.4) {
      const slab = new THREE.Mesh(new THREE.BoxGeometry(w * 0.5, 0.12, 0.9), MAT.wood);
      slab.position.set(0, h * 0.6, w * 0.45 + 0.35);
      const rail = new THREE.Mesh(new THREE.BoxGeometry(w * 0.5, 0.42, 0.07), MAT.wood);
      rail.position.set(0, h * 0.6 + 0.27, w * 0.45 + 0.75);
      house.add(slab, rail);
    }
    house.position.set(x, 0.25, z);
    house.rotation.y = rng() * Math.PI;
    city.add(house);
    addCollider(CITY.x + x, CITY.z + z, Math.max(2.4, Math.hypot(w, w * 0.9) / 2));
  }

  // ── Конюшня: длинное стойло с крышей и лошадью ──
  {
    const sx = -18.6, sz = -69.5;
    const stable = new THREE.Group();
    // Пол и основание
    const sfloor = new THREE.Mesh(new THREE.BoxGeometry(9, 0.2, 6), MAT.sandstoneDark);
    sfloor.position.set(0, 0.1, 0);
    stable.add(sfloor);
    // Задняя и боковые стены (перед открыт для прохода)
    const backWall = new THREE.Mesh(new THREE.BoxGeometry(9, 3.6, 0.5), MAT.sandstone);
    backWall.position.set(0, 1.8, -2.75);
    backWall.castShadow = true;
    const leftWall = new THREE.Mesh(new THREE.BoxGeometry(0.5, 3.6, 6), MAT.sandstone);
    leftWall.position.set(-4.25, 1.8, 0);
    leftWall.castShadow = true;
    const rightWall = leftWall.clone(); rightWall.position.x = 4.25;
    stable.add(backWall, leftWall, rightWall);
    // Двускатная крыша (соломенная текстура — тёмно-жёлтая)
    const roofShape = new THREE.Shape();
    roofShape.moveTo(-4.8, 0);
    roofShape.lineTo(0, 2.6);
    roofShape.lineTo(4.8, 0);
    roofShape.lineTo(-4.8, 0);
    const roofGeo = new THREE.ExtrudeGeometry(roofShape, { depth: 6.8, bevelEnabled: false });
    const roofMat = new THREE.MeshStandardMaterial({ color: 0x9a7a30, roughness: 1 });
    const roof = new THREE.Mesh(roofGeo, roofMat);
    roof.position.set(0, 3.6, -3.4);
    roof.castShadow = true; roof.receiveShadow = true;
    stable.add(roof);
    // Столбики-разделители стойл
    for (const px of [-2, 0, 2]) {
      const pillar = new THREE.Mesh(new THREE.BoxGeometry(0.3, 2.8, 0.3), MAT.trunk);
      pillar.position.set(px, 1.4, 1.5);
      stable.add(pillar);
    }
    // Лошадь — простая модель из примитивов
    const horseMat = new THREE.MeshStandardMaterial({ color: 0x7a4a2a, roughness: 1 });
    const horse = new THREE.Group();
    const hBody = new THREE.Mesh(new THREE.BoxGeometry(1.0, 1.2, 2.2), horseMat);
    hBody.position.y = 1.5;
    const hNeck = new THREE.Mesh(new THREE.BoxGeometry(0.5, 1.0, 0.5), horseMat);
    hNeck.position.set(0, 2.2, 1.0); hNeck.rotation.x = -0.4;
    const hHead = new THREE.Mesh(new THREE.BoxGeometry(0.4, 0.4, 0.9), horseMat);
    hHead.position.set(0, 2.7, 1.3);
    const hTail = new THREE.Mesh(new THREE.ConeGeometry(0.12, 0.9, 4), horseMat);
    hTail.position.set(0, 1.9, -1.3); hTail.rotation.x = 0.4;
    // Ноги
    for (const [lx, lz] of [[-0.35, 0.7], [0.35, 0.7], [-0.35, -0.7], [0.35, -0.7]] as const) {
      const leg = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.12, 1.0, 5), horseMat);
      leg.position.set(lx, 0.5, lz);
      horse.add(leg);
    }
    horse.add(hBody, hNeck, hHead, hTail);
    horse.position.set(0, 0.2, 0);
    horse.rotation.y = -Math.PI / 2;
    stable.add(horse);
    stable.position.set(sx, 0.2, sz);
    city.add(stable);
    addCollider(CITY.x + sx, CITY.z + sz, 5.0);
  }

  // Базарные прилавки с товаром у мечети
  for (let i = 0; i < 7; i++) {
    const a = Math.PI * 0.6 + (i / 7) * Math.PI * 0.8;
    const x = Math.cos(a) * 20, z = -8 + Math.sin(a) * 20;
    const stall = buildStall(i % 3, canopies);
    stall.position.set(x, 0.3, z);
    stall.rotation.y = -a + Math.PI / 2;
    city.add(stall);
    addCollider(CITY.x + x, CITY.z + z, 2.6);
  }

  // Пальмы у базара и вдоль улицы к воротам
  // Кварталы расширенного города: базар, ремесла, жилые дома, сады + улицы
  buildQuarters(city, canopies, lights);

  addPalm(city, 24, -14, 1, true);
  addPalm(city, -22, 12, 0.9, true);
  addPalm(city, -2, 30, 1.05, true);
  addPalm(city, 12, 26, 0.85, true);
  addPalm(city, -12, 24, 0.95, true);

  // Городские фонари-чаши
  for (let i = 0; i < 5; i++) {
    const a = (i / 5) * Math.PI * 2 + 0.4;
    const x = Math.cos(a) * CITY.radius * 0.55, z = Math.sin(a) * CITY.radius * 0.55;
    const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.14, 0.2, 4.4, 6), MAT.dark);
    pole.position.set(x, 2.4, z);
    const bowl = new THREE.Mesh(new THREE.CylinderGeometry(0.55, 0.3, 0.5, 8), MAT.gold);
    bowl.position.set(x, 4.8, z);
    city.add(pole, bowl);
    lights.push({ x: CITY.x + x, z: CITY.z + z });
    addCollider(CITY.x + x, CITY.z + z, 0.5);
  }

  // Коллайдер мечети — строго по корпусу здания (24×18 в локальных -8):
  // ряды внутри контура, ничего не торчит за стену (иначе «невидимая
  // стена» сзади мечети, где стоят Хафиз и Мевлана)
  for (const mx of [-9, -3, 3, 9]) {
    for (const mz of [-5, 0, 5]) {
      addCollider(CITY.x + mx, CITY.z - 8 + mz, 4.4);
    }
  }
  // Портал-арка: коллайдеры по бокам арки (по 1.2), чтобы персонаж
  // мог свободно пройти под аркой в мечеть
  addCollider(CITY.x - 2.2, CITY.z + 9.4, 1.2);
  addCollider(CITY.x + 2.2, CITY.z + 9.4, 1.2);

  city.userData.lights = lights;
  scene.add(city);
  // Возвращаем сохранённые коллайдеры ландшафта (деревья, камни) ПОСЛЕ города,
  // чтобы игрок не проходил сквозь них
  const saved = (city as any).__landscapeColliders;
  if (saved) for (const c of saved) COLLIDERS.push(c);
  return city;
}

/** Прилавок с товаром (кувшины / ящики / рулоны) */
function buildStall(kind: number, canopies: THREE.MeshStandardMaterial[]): THREE.Group {
  const stall = new THREE.Group();
  const table = new THREE.Mesh(new THREE.BoxGeometry(3, 1, 1.6), MAT.wood);
  table.position.y = 0.8; table.castShadow = true;
  const roof = new THREE.Mesh(new THREE.BoxGeometry(3.4, 0.2, 2.4), canopies[kind % 3]);
  roof.position.y = 2.6; roof.rotation.x = 0.16;
  const p1 = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.07, 2.6, 5), MAT.wood);
  p1.position.set(-1.4, 1.3, -0.8);
  const p2 = p1.clone(); p2.position.x = 1.4;
  stall.add(table, roof, p1, p2);
  if (kind === 0) {
    for (let j = 0; j < 4; j++) {
      const jar = new THREE.Mesh(new THREE.CylinderGeometry(0.14, 0.2, 0.42, 7), MAT.sandstoneDark);
      jar.position.set(-1 + j * 0.65, 1.5, (j % 2 ? 0.25 : -0.25));
      stall.add(jar);
    }
  } else if (kind === 1) {
    const crate = new THREE.Mesh(new THREE.BoxGeometry(0.9, 0.55, 0.7), MAT.wood);
    crate.position.set(0.4, 1.55, 0);
    crate.rotation.y = 0.3;
    const crate2 = new THREE.Mesh(new THREE.BoxGeometry(0.7, 0.45, 0.6), MAT.wood);
    crate2.position.set(-0.7, 1.5, 0.1);
    stall.add(crate, crate2);
  } else {
    for (let j = 0; j < 3; j++) {
      const roll = new THREE.Mesh(new THREE.CylinderGeometry(0.16, 0.16, 1.1, 8), canopies[(kind + j) % 3]);
      roll.rotation.z = Math.PI / 2;
      roll.position.set(-0.7 + j * 0.7, 1.42, 0.2);
      stall.add(roll);
    }
  }
  return stall;
}

// ── Лагерь разбойников ───────────────────────────────────────
// ── Восточный набор: бадгир, айван, кирпичный дом, кипарис ──
// Единый стиль для всех поселений, у каждого — своя палитра/композиция.

/** Бадгир (ветроуловитель): башня с прорезями и шляпкой. */
function badgir(parent: THREE.Group, x: number, z: number, baseY: number, h: number): void {
  const shaft = new THREE.Mesh(new THREE.BoxGeometry(1.3, h, 1.3), MAT.sandstone);
  shaft.position.set(x, baseY + h / 2, z);
  shaft.castShadow = true;
  parent.add(shaft);
  for (const [ox, oz, w, d] of [[0, 0.66, 0.7, 0.06], [0, -0.66, 0.7, 0.06], [0.66, 0, 0.06, 0.7], [-0.66, 0, 0.06, 0.7]] as const) {
    const slot = new THREE.Mesh(new THREE.BoxGeometry(w, h * 0.55, d), MAT.dark);
    slot.position.set(x + ox, baseY + h * 0.62, z + oz);
    parent.add(slot);
  }
  const cap = new THREE.Mesh(new THREE.BoxGeometry(1.7, 0.35, 1.7), MAT.sandstoneDark);
  cap.position.set(x, baseY + h + 0.17, z);
  cap.castShadow = true;
  parent.add(cap);
}

/** Айван: портал с пилонами, аркой и бирюзовой полосой. */
function tiledIwan(parent: THREE.Group, x: number, z: number, w: number, h: number, ry: number): void {
  const g = new THREE.Group();
  const pw = w * 0.22;
  for (const s of [-1, 1]) {
    const pylon = new THREE.Mesh(new THREE.BoxGeometry(pw, h, 1.6), MAT.sandstone);
    pylon.position.set(s * (w / 2 - pw / 2), h / 2, 0);
    pylon.castShadow = true; pylon.receiveShadow = true;
    g.add(pylon);
    const band = new THREE.Mesh(new THREE.BoxGeometry(pw + 0.1, h * 0.3, 1.7), MAT.tealDome);
    band.position.set(s * (w / 2 - pw / 2), h * 0.72, 0);
    g.add(band);
  }
  const beam = new THREE.Mesh(new THREE.BoxGeometry(w, h * 0.2, 1.6), MAT.sandstoneDark);
  beam.position.set(0, h * 0.9, 0);
  beam.castShadow = true;
  const arch = new THREE.Mesh(new THREE.BoxGeometry(w * 0.5, h * 0.72, 0.5), MAT.dark);
  arch.position.set(0, h * 0.36, 0.4);
  g.add(beam, arch);
  g.position.set(x, 0, z);
  g.rotation.y = ry;
  parent.add(g);
}

/** Кирпичный дом с куполом, балконом и окнами. Возвращает высоту для коллайдера. */
function brickHouse(
  parent: THREE.Group, x: number, z: number, w: number, h: number,
  opts: { dome?: boolean; balcony?: boolean; badgirH?: number; plaster?: THREE.Material } = {},
): number {
  const wallMat = opts.plaster ?? MAT.sandstone;
  const body = new THREE.Mesh(new THREE.BoxGeometry(w, h, w * 0.9), wallMat);
  body.position.set(x, h / 2, z);
  body.castShadow = true; body.receiveShadow = true;
  parent.add(body);
  if (opts.dome !== false) {
    const dome = new THREE.Mesh(new THREE.SphereGeometry(w * 0.32, 10, 8), MAT.tealDome);
    dome.scale.y = 0.72;
    dome.position.set(x, h + 0.1, z);
    dome.castShadow = true;
    parent.add(dome);
  }
  if (opts.balcony) {
    const slab = new THREE.Mesh(new THREE.BoxGeometry(w * 0.6, 0.14, 1.1), MAT.wood);
    slab.position.set(x, h * 0.62, z + w * 0.45 + 0.4);
    const rail = new THREE.Mesh(new THREE.BoxGeometry(w * 0.6, 0.5, 0.08), MAT.wood);
    rail.position.set(x, h * 0.62 + 0.32, z + w * 0.45 + 0.9);
    parent.add(slab, rail);
  }
  const win = new THREE.Mesh(new THREE.BoxGeometry(0.7, 1.0, 0.12), MAT.dark);
  win.position.set(x - w * 0.22, h * 0.55, z + w * 0.45 + 0.02);
  const win2 = win.clone();
  win2.position.x = x + w * 0.22;
  parent.add(win, win2);
  if (opts.badgirH) badgir(parent, x + w * 0.28, z - w * 0.2, h, opts.badgirH);
  return Math.max(Math.hypot(w, w * 0.9) / 2, 2.4);
}

/** Кипарис для садов и дворов. */
function cypress(parent: THREE.Group, x: number, z: number, baseY: number, s: number): void {
  const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.14, 0.18, 0.7, 6), MAT.trunk);
  trunk.position.set(x, baseY + 0.35, z);
  const crown = new THREE.Mesh(new THREE.ConeGeometry(0.85 * s, 3.6 * s, 7), MAT.foliageDark);
  crown.position.set(x, baseY + 0.7 + 1.8 * s, z);
  crown.castShadow = true;
  parent.add(trunk, crown);
  addCollider(CITY.x + x, CITY.z + z, 0.55);
}

export function buildCamp(scene: THREE.Scene): void {
  const camp = new THREE.Group();
  const baseY = groundHeight(CAMP.x, CAMP.z);
  camp.position.set(CAMP.x, baseY, CAMP.z);
  for (let i = 0; i < 4; i++) {
    const a = (i / 4) * Math.PI * 2 + 0.5;
    const tent = new THREE.Mesh(new THREE.ConeGeometry(2.6, 3.4, 7), i % 2 ? MAT.clothRed : MAT.dark);
    const x = Math.cos(a) * 10, z = Math.sin(a) * 10;
    tent.position.set(x, 1.7, z);
    tent.castShadow = true;
    const flag = new THREE.Mesh(new THREE.BoxGeometry(0.06, 1.4, 0.9), MAT.clothRed);
    flag.position.set(x, 4.2, z);
    camp.add(tent, flag);
    addCollider(CAMP.x + x, CAMP.z + z, 2.5);
  }
  // Частокол кольцом (с юга — проход) и большой шатёр вождя
  for (let i = 0; i < 26; i++) {
    const a = (i / 26) * Math.PI * 2;
    if (Math.abs(a - Math.PI / 2) < 0.28) continue;
    const px = Math.cos(a) * 15, pz = Math.sin(a) * 15;
    const stake = new THREE.Mesh(new THREE.BoxGeometry(0.35, 2.6, 0.35), MAT.trunk);
    stake.position.set(px, 1.3, pz);
    stake.rotation.z = i % 2 ? 0.04 : -0.04;
    stake.castShadow = true;
    camp.add(stake);
  }
  addCollider(CAMP.x + 15, CAMP.z, 1.6);
  addCollider(CAMP.x - 15, CAMP.z, 1.6);
  addCollider(CAMP.x, CAMP.z - 15, 1.6);
  addCollider(CAMP.x, CAMP.z + 15, 1.6);
  const bigTent = new THREE.Mesh(new THREE.ConeGeometry(3.6, 4.6, 8), MAT.clothPurple);
  bigTent.position.set(0, 2.3, -6.5);
  bigTent.castShadow = true;
  const bigFlag = new THREE.Mesh(new THREE.BoxGeometry(0.07, 1.6, 1.1), MAT.gold);
  bigFlag.position.set(0, 5.6, -6.5);
  camp.add(bigTent, bigFlag);
  addCollider(CAMP.x, CAMP.z - 6.5, 3.4);
  const fire = new THREE.Mesh(new THREE.CylinderGeometry(1, 1.2, 0.4, 9), MAT.dark);
  fire.position.set(0, 0.2, 0);
  addCollider(CAMP.x, CAMP.z, 1.4);
  const flame = new THREE.Mesh(new THREE.ConeGeometry(0.5, 1.4, 7), new THREE.MeshStandardMaterial({ color: 0xff8c30, emissive: 0xff6a10, emissiveIntensity: 1.6 }));
  flame.position.set(0, 1, 0);
  flame.name = 'campfire-flame';
  camp.add(fire, flame);
  camp.userData.flame = flame;
  scene.add(camp);
}

// ── Поселения: порт, караван-сарай, деревня, форт ────────────
export function buildSettlements(scene: THREE.Scene): void {
  const rng = (() => { let s = 99; return () => (s = (s * 16807) % 2147483647) / 2147483647; })();

  // Приозёрный порт: пирс с лодками, домики, бочки
  {
    const g = new THREE.Group();
    g.position.set(PORT.x, groundHeight(PORT.x, PORT.z), PORT.z);
    for (let i = 0; i < 3; i++) {
      const house = new THREE.Group();
      const w = 4 + rng() * 2, h = 3 + rng();
      // Белёные стены + синий купол — приморский стиль
      const body = new THREE.Mesh(new THREE.BoxGeometry(w, h, w * 0.9), MAT.white);
      body.position.y = h / 2; body.castShadow = true; body.receiveShadow = true;
      const roof = new THREE.Mesh(new THREE.ConeGeometry(w * 0.8, 1.6, 4), MAT.clothTeal);
      roof.position.y = h + 0.8; roof.rotation.y = Math.PI / 4;
      house.add(body, roof);
      if (i === 0) {
        const dome = new THREE.Mesh(new THREE.SphereGeometry(1.1, 10, 8), MAT.tealDome);
        dome.scale.y = 0.75;
        dome.position.set(w * 0.2, h + 0.4, 0);
        house.add(dome);
      }
      const a = -0.8 + i * 0.9;
      house.position.set(Math.cos(a) * 9, 0.2, Math.sin(a) * 9);
      house.rotation.y = -a + Math.PI;
      g.add(house);
      addCollider(PORT.x + house.position.x, PORT.z + house.position.z, w * 0.6);
    }
    // пирс к воде (в сторону озера)
    const toLake = Math.atan2(LAKE.x - PORT.x, LAKE.z - PORT.z);
    const pier = new THREE.Group();
    for (let i = 0; i < 6; i++) {
      const plank = new THREE.Mesh(new THREE.BoxGeometry(2.4, 0.18, 1.6), MAT.wood);
      plank.position.set(0, 0.55, -i * 1.9);
      plank.castShadow = true;
      pier.add(plank);
      const leg1 = new THREE.Mesh(new THREE.CylinderGeometry(0.09, 0.09, 1.4, 5), MAT.trunk);
      leg1.position.set(-1, -0.2, -i * 1.9);
      const leg2 = leg1.clone(); leg2.position.x = 1;
      pier.add(leg1, leg2);
    }
    // лодка у пирса
    const boat = new THREE.Group();
    const hull = new THREE.Mesh(new THREE.CylinderGeometry(0.9, 0.5, 3.4, 7), MAT.wood);
    hull.rotation.x = Math.PI / 2; hull.scale.y = 0.45;
    const mast = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.06, 2.6, 5), MAT.trunk);
    mast.position.y = 1.4;
    const sail = new THREE.Mesh(new THREE.BoxGeometry(1.5, 1.3, 0.05), MAT.clothTeal);
    sail.position.set(0, 1.5, 0.1);
    boat.add(hull, mast, sail);
    boat.position.set(1.8, LAKE.level + 0.35, -13);
    pier.add(boat);
    pier.position.set(Math.sin(toLake) * 12, 0, Math.cos(toLake) * 12);
    pier.rotation.y = toLake;
    g.add(pier);

    // Торговые столы у причала (рядом с домиками)
    const tablePositions = [
      { x: -2, z: -3 },   // стол у рыбака
      { x: 3, z: -5 },    // стол у торговца
      { x: -5, z: -6 },   // стол у кок-Салима
    ];
    for (const tp of tablePositions) {
      const table = new THREE.Mesh(new THREE.BoxGeometry(1.8, 0.9, 1.0), MAT.wood);
      table.position.set(tp.x, 0.45, tp.z);
      table.castShadow = true;
      g.add(table);
      // Ножки стола
      for (const [lx, lz] of [[-0.7, -0.35], [0.7, -0.35], [-0.7, 0.35], [0.7, 0.35]] as const) {
        const leg = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.06, 0.9, 5), MAT.wood);
        leg.position.set(tp.x + lx, 0, tp.z + lz);
        g.add(leg);
      }
      addCollider(PORT.x + tp.x, PORT.z + tp.z, 1.1);
    }

    // Доска объявлений у входа в порт
    {
      const boardX = 8, boardZ = 8;
      const post1 = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.07, 2.2, 5), MAT.wood);
      post1.position.set(boardX - 0.6, 1.1, boardZ);
      const post2 = post1.clone(); post2.position.x = boardX + 0.6;
      const board = new THREE.Mesh(new THREE.BoxGeometry(1.4, 0.9, 0.08), MAT.wood);
      board.position.set(boardX, 1.7, boardZ);
      board.castShadow = true;
      g.add(post1, post2, board);
      addCollider(PORT.x + boardX, PORT.z + boardZ, 0.7);
    }

    // бочки — каждая бочка с коллайдером
    const barrelPositions: { x: number; z: number }[] = [];
    for (let i = 0; i < 4; i++) {
      const bx = -8 + rng() * 4;
      const bz = 4 + rng() * 6;
      const barrel = new THREE.Mesh(new THREE.CylinderGeometry(0.35, 0.35, 0.7, 8), MAT.wood);
      barrel.position.set(bx, 0.55, bz);
      barrel.castShadow = true;
      g.add(barrel);
      barrelPositions.push({ x: bx, z: bz });
    }
    for (const bp of barrelPositions) {
      addCollider(PORT.x + bp.x, PORT.z + bp.z, 0.8);
    }

    // маячок-фонарь
    const lampPost = new THREE.Mesh(new THREE.CylinderGeometry(0.16, 0.24, 5.2, 6), MAT.dark);
    lampPost.position.set(-10, 2.8, -4);
    const lamp = new THREE.Mesh(new THREE.SphereGeometry(0.5, 8, 6), new THREE.MeshStandardMaterial({ color: 0xffd980, emissive: 0xffa530, emissiveIntensity: 1.2 }));
    lamp.position.set(-10, 5.6, -4);
    g.add(lampPost, lamp);
    addCollider(PORT.x - 10, PORT.z - 4, 0.6);

    // Маяк на конце пирса + склады у берега
    const lightTower = new THREE.Mesh(new THREE.CylinderGeometry(1.0, 1.5, 9, 10), MAT.white);
    lightTower.position.set(-2.2, 4.5, -12.5);
    lightTower.castShadow = true;
    const lampRoom = new THREE.Mesh(new THREE.CylinderGeometry(0.8, 0.8, 1.2, 8), MAT.dark);
    lampRoom.position.set(-2.2, 9.6, -12.5);
    const lampGlow = new THREE.Mesh(
      new THREE.SphereGeometry(0.55, 8, 6),
      new THREE.MeshStandardMaterial({ color: 0xffd980, emissive: 0xffa530, emissiveIntensity: 1.6 }),
    );
    lampGlow.position.set(-2.2, 9.6, -12.5);
    const lightCap = new THREE.Mesh(new THREE.ConeGeometry(1.1, 0.9, 8), MAT.clothRed);
    lightCap.position.set(-2.2, 10.6, -12.5);
    g.add(lightTower, lampRoom, lampGlow, lightCap);
    addCollider(PORT.x - 2.2, PORT.z - 12.5, 1.6);
    for (const [wx, wz, ww] of [[-14, 6, 7], [-15, -2, 5.5]] as const) {
      const store = new THREE.Mesh(new THREE.BoxGeometry(ww, 3.2, 5), MAT.sandstoneDark);
      store.position.set(wx, 1.6, wz);
      store.castShadow = true; store.receiveShadow = true;
      const awn = new THREE.Mesh(new THREE.BoxGeometry(ww + 0.6, 0.15, 2.2), MAT.clothRed);
      awn.position.set(wx, 3.0, wz + 3.2);
      awn.rotation.x = 0.18;
      g.add(store, awn);
      addCollider(PORT.x + wx, PORT.z + wz, ww * 0.62);
    }

    scene.add(g);
  }

  // Караван-сарай в пустыне: двор со стенами, шатры, колодец, верблюжьи стойла
  {
    const g = new THREE.Group();
    g.position.set(CARAVANSERAI.x, groundHeight(CARAVANSERAI.x, CARAVANSERAI.z), CARAVANSERAI.z);
    const wall = new THREE.BoxGeometry(30, 3.2, 1.6);
    for (const [rx, rz, ry] of [[0, -14, 0], [0, 14, 0], [-14, 0, Math.PI / 2]] as const) {
      const w = new THREE.Mesh(wall, MAT.sandstoneDark);
      w.position.set(rx, 1.6, rz);
      w.rotation.y = ry;
      w.castShadow = true; w.receiveShadow = true;
      g.add(w);
    }
    // Коллайдеры стен двора (частые точки вдоль каждой стены)
    for (let wx = -14; wx <= 14; wx += 4) {
      addCollider(CARAVANSERAI.x + wx, CARAVANSERAI.z - 14, 2.0);
      if (Math.abs(wx) > 10) addCollider(CARAVANSERAI.x + wx, CARAVANSERAI.z + 14, 2.0);
    }
    for (let wz = -14; wz <= 14; wz += 4) {
      addCollider(CARAVANSERAI.x - 14, CARAVANSERAI.z + wz, 2.0);
    }
    const gateL = new THREE.Mesh(new THREE.BoxGeometry(1.6, 4.6, 1.6), MAT.sandstoneDark);
    gateL.position.set(-11, 2.3, 14);
    const gateR = gateL.clone(); gateR.position.x = 11;
    g.add(gateL, gateR);
    addCollider(CARAVANSERAI.x - 11, CARAVANSERAI.z + 14, 1.4);
    addCollider(CARAVANSERAI.x + 11, CARAVANSERAI.z + 14, 1.4);
    // Угловые башни крепости
    for (const [tx, tz] of [[-14, -14], [14, -14], [-14, 14], [14, 14]] as const) {
      const tower = new THREE.Mesh(new THREE.CylinderGeometry(1.8, 2.2, 6.5, 9), MAT.sandstone);
      tower.position.set(tx, 3.25, tz);
      tower.castShadow = true;
      const tooth = new THREE.Mesh(new THREE.CylinderGeometry(2.2, 2.2, 0.7, 9), MAT.sandstoneDark);
      tooth.position.set(tx, 6.8, tz);
      g.add(tower, tooth);
      addCollider(CARAVANSERAI.x + tx, CARAVANSERAI.z + tz, 2.5);
    }
    // Бирюзовый айван над воротами
    tiledIwan(g, 0, 14, 9, 6.5, 0);
    // Коллайдер в середине ворот УБРАН. Он стоял здесь же и затыкал проём:
    // подойти к воротам можно было, войти - нет. Айван построен НАД проёмом,
    // а коллайдеры в игре двумерные, и затыкать им вход нечего.
    //
    // Дверь стоит ровно там, куда указывают данные: локальные (0, 14) - это мировые
    // (505, 69), и caravanseraiInterior.test.ts сверяет именно эту точку.
    const vorota = new THREE.Mesh(new THREE.BoxGeometry(5.0, 3.4, 0.3), MAT.wood);
    vorota.position.set(0, 1.7, 14);
    vorota.userData = {
      doorBuilding: 'caravanserai',
      doorAction: 'enter',
      doorName: t('buildings.caravanserai'),
    };
    g.add(vorota);
    // Стела у ворот, снаружи: игрок подходит с юга и читает её на пути к двери.
    const nadpisKarav = inscriptionFor('caravanserai');
    const mestoKarav = GATE_STELES.caravanserai;
    if (nadpisKarav && mestoKarav) {
      const steleKarav = steleMesh(nadpisKarav);
      steleKarav.position.set(mestoKarav.x, 0, mestoKarav.z);
      steleKarav.rotation.y = mestoKarav.ry;
      g.add(steleKarav);
    }
    // Внутренняя аркада вдоль северной стены
    for (let ax = -10; ax <= 10; ax += 5) {
      const pillar = new THREE.Mesh(new THREE.BoxGeometry(0.7, 3.4, 0.7), MAT.sandstone);
      pillar.position.set(ax, 1.7, -11.5);
      pillar.castShadow = true;
      g.add(pillar);
    }
    const arcadeBeam = new THREE.Mesh(new THREE.BoxGeometry(21, 0.5, 0.9), MAT.wood);
    arcadeBeam.position.set(0, 3.6, -11.5);
    g.add(arcadeBeam);
    for (let i = 0; i < 5; i++) {
      const tent = new THREE.Mesh(new THREE.ConeGeometry(2.4, 3, 7), i % 2 ? MAT.clothPurple : MAT.clothRed);
      tent.position.set(-9 + (i % 3) * 9, 1.5, -8 + Math.floor(i / 3) * 7);
      tent.castShadow = true;
      g.add(tent);
      addCollider(CARAVANSERAI.x + tent.position.x, CARAVANSERAI.z + tent.position.z, 2.3);
    }
    // колодец
    const well = new THREE.Mesh(new THREE.CylinderGeometry(1.3, 1.5, 1, 10), MAT.stone);
    well.position.set(6, 0.5, 4);
    const wellRoof = new THREE.Mesh(new THREE.ConeGeometry(1.8, 1, 8), MAT.clothTeal);
    wellRoof.position.set(6, 2.4, 4);
    const wellPost = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.08, 2.6, 5), MAT.wood);
    wellPost.position.set(6, 1.8, 4);
    g.add(well, wellRoof, wellPost);
    addCollider(CARAVANSERAI.x + 6, CARAVANSERAI.z + 4, 1.8);
    // тюки с товаром
    for (let i = 0; i < 6; i++) {
      const bale = new THREE.Mesh(new THREE.BoxGeometry(1, 0.7, 0.8), MAT.clothTeal);
      bale.position.set(-4 + rng() * 10, 0.4, -12 + rng() * 6);
      bale.rotation.y = rng() * Math.PI;
      bale.castShadow = true;
      g.add(bale);
      addCollider(CARAVANSERAI.x + bale.position.x, CARAVANSERAI.z + bale.position.z, 0.8);
    }
    // Верблюды во дворе: 2 отдыхающих (статичные, на коленях) + место
    // для ходячих из фауны (их дом — центр двора, стены держат коллайдеры)
    for (const [restX, restZ, restRy] of [[-6, 2, 0.6], [9, -2, -0.9]] as const) {
      const rest = new THREE.Group();
      const camelMat = new THREE.MeshStandardMaterial({ color: 0xc8a15a, roughness: 1 });
      const camelDark = new THREE.MeshStandardMaterial({ color: 0xa8823f, roughness: 1 });
      const rbody = new THREE.Mesh(new THREE.BoxGeometry(1.1, 0.7, 1.9), camelMat);
      rbody.position.y = 0.55;
      const hump = new THREE.Mesh(new THREE.SphereGeometry(0.42, 7, 6), camelDark);
      hump.position.set(0, 1.05, -0.2);
      const hump2 = hump.clone(); hump2.position.z = 0.45;
      const neck = new THREE.Mesh(new THREE.BoxGeometry(0.32, 0.9, 0.32), camelMat);
      neck.position.set(0, 0.9, 1.05);
      neck.rotation.x = 0.5;
      const head = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.32, 0.7), camelMat);
      head.position.set(0, 1.3, 1.4);
      rest.add(rbody, hump, hump2, neck, head);
      rest.position.set(restX, 0.2, restZ);
      rest.rotation.y = restRy;
      rest.traverse(o => { if (o instanceof THREE.Mesh) o.castShadow = true; });
      g.add(rest);
      addCollider(CARAVANSERAI.x + restX, CARAVANSERAI.z + restZ, 1.4);
    }
    scene.add(g);
  }

  // Лесная деревня: бревенчатые дома, поленница, стог
  {
    const g = new THREE.Group();
    g.position.set(VILLAGE.x, groundHeight(VILLAGE.x, VILLAGE.z), VILLAGE.z);
    for (let i = 0; i < 4; i++) {
      const house = new THREE.Group();
      const w = 4.4 + rng() * 1.5, h = 3 + rng();
      const body = new THREE.Mesh(new THREE.BoxGeometry(w, h, w * 0.85), MAT.wood);
      body.position.y = h / 2; body.castShadow = true; body.receiveShadow = true;
      const roof = new THREE.Mesh(new THREE.ConeGeometry(w * 0.85, 2, 4), MAT.trunk);
      roof.position.y = h + 1; roof.rotation.y = Math.PI / 4;
      house.add(body, roof);
      // Бадгиры над двумя домами — сельский силуэт
      if (i % 2 === 0) badgir(house, w * 0.28, -w * 0.2, h, 1.6);
      const a = (i / 4) * Math.PI * 2 + 0.4;
      house.position.set(Math.cos(a) * 10, 0.2, Math.sin(a) * 10);
      house.rotation.y = -a + Math.PI;
      g.add(house);
      addCollider(VILLAGE.x + house.position.x, VILLAGE.z + house.position.z, w * 0.6);
    }
    // поленница
    for (let i = 0; i < 8; i++) {
      const log = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.18, 1.6, 6), MAT.trunk);
      log.rotation.z = Math.PI / 2;
      log.position.set(-6 + (i % 4) * 0.42, 0.2 + Math.floor(i / 4) * 0.36, 8);
      g.add(log);
    }
    addCollider(VILLAGE.x - 6, VILLAGE.z + 8, 1.4);
    // стог сена
    const hay = new THREE.Mesh(new THREE.ConeGeometry(1.6, 2.6, 8), new THREE.MeshStandardMaterial({ color: 0xc8a84c, roughness: 1 }));
    hay.position.set(8, 1.3, 7);
    hay.castShadow = true;
    g.add(hay);
    addCollider(VILLAGE.x + 8, VILLAGE.z + 7, 1.7);
    // Поля: вспаханные делянки с изгородью
    const fieldCols = [
      new THREE.MeshStandardMaterial({ color: 0x5d7a3c, roughness: 1 }),
      new THREE.MeshStandardMaterial({ color: 0x6e563a, roughness: 1 }),
    ];
    [[-14, 10, 0], [-14, 17, 1], [-6, 14, 0]].forEach(([fx, fz, fi], idx) => {
      const field = new THREE.Mesh(new THREE.BoxGeometry(7, 0.15, 5), fieldCols[(idx + fi) % 2]);
      field.position.set(fx, 0.08, fz);
      field.receiveShadow = true;
      g.add(field);
      for (let px = -3; px <= 3; px += 2) {
        const post = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.9, 0.12), MAT.trunk);
        post.position.set(fx + px, 0.45, fz - 2.6);
        g.add(post);
      }
    });
    addCollider(VILLAGE.x - 14, VILLAGE.z + 13.5, 4.5);
    scene.add(g);
  }

  // Горный форт: каменная цитадель с башнями и знамёнами
  {
    const g = new THREE.Group();
    g.position.set(FORT.x, groundHeight(FORT.x, FORT.z), FORT.z);
    const keep = new THREE.Mesh(new THREE.BoxGeometry(12, 10, 12), MAT.stone);
    keep.position.y = 5; keep.castShadow = true; keep.receiveShadow = true;
    const keepRoof = new THREE.Mesh(new THREE.ConeGeometry(9, 3.4, 4), MAT.clothRed);
    keepRoof.position.y = 11.7; keepRoof.rotation.y = Math.PI / 4;
    g.add(keep, keepRoof);
    addCollider(FORT.x, FORT.z, 7.5);
    for (const [tx, tz] of [[-9, -9], [9, -9], [-9, 9], [9, 9]] as const) {
      const tower = new THREE.Mesh(new THREE.CylinderGeometry(2, 2.4, 8, 9), MAT.stone);
      tower.position.set(tx, 4, tz);
      tower.castShadow = true;
      const cap = new THREE.Mesh(new THREE.ConeGeometry(2.5, 2, 9), MAT.snow);
      cap.position.set(tx, 9, tz);
      g.add(tower, cap);
      addCollider(FORT.x + tx, FORT.z + tz, 2.7);
    }
    // знамёна
    for (const side of [-1, 1]) {
      const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.06, 5, 5), MAT.dark);
      pole.position.set(side * 5, 13.5, 0);
      const flag = new THREE.Mesh(new THREE.BoxGeometry(0.05, 1.2, 1.8), MAT.clothRed);
      flag.position.set(side * 5, 14.6, 0.9);
      g.add(pole, flag);
    }
    // Куртины между башнями (кроме южного проёма под ворота)
    for (const [wx, wz, ww, wd] of [[0, -9, 15.5, 1.8], [-9, 0, 1.8, 15.5], [9, 0, 1.8, 15.5]] as const) {
      const wall = new THREE.Mesh(new THREE.BoxGeometry(ww, 5.5, wd), MAT.stone);
      wall.position.set(wx, 2.75, wz);
      wall.castShadow = true; wall.receiveShadow = true;
      g.add(wall);
      addCollider(FORT.x + wx, FORT.z + wz, Math.max(ww, wd) / 2);
    }
    // Айван ворот с юга
    tiledIwan(g, 0, 9, 7, 6, 0);
    // Коллайдер в воротах УБРАН: он стоял в проёме и не давал войти. Куртины
    // строятся только с трёх сторон, и южный проём - это и есть ворота.
    const vorotaFort = new THREE.Mesh(new THREE.BoxGeometry(5.0, 3.4, 0.3), MAT.wood);
    vorotaFort.position.set(0, 1.7, 9);
    vorotaFort.userData = {
      doorBuilding: 'fortress',
      doorAction: 'enter',
      doorName: t('buildings.fortress'),
    };
    g.add(vorotaFort);
    // Стела у ворот крепости, снаружи и сбоку от айвана.
    const nadpisFort = inscriptionFor('fortress');
    const mestoFort = GATE_STELES.fortress;
    if (nadpisFort && mestoFort) {
      const steleFort = steleMesh(nadpisFort);
      steleFort.position.set(mestoFort.x, 0, mestoFort.z);
      steleFort.rotation.y = mestoFort.ry;
      g.add(steleFort);
    }
  }

  // ── Дворец ──────────────────────────────────────────────────────
  //
  // Второе здание из шести, которому владелец велел достроить экстерьер.
  // Модели в Assets для дворца нет (в отличие от мечети, у которой точное
  // попадание нашлось), поэтому комплекс собирается примитивами из MAT —
  // ровно как караван-сарай и крепость.
  //
  // ЧТО ЭТО ТАКОЕ. Шахский дворец — не глухая коробка, а КОМПЛЕКС ВО ДВОРЕ:
  // стена по периметру с воротами, а за воротами открытый двор с бассейном,
  // и в глубине двора тронный зал под куполом. Игрок выходит из зала на
  // террасу, идёт через двор и выходит в ворота. Так же устроен и мечетный
  // двор, и игрок ходит по нему одинаково.
  //
  // КООРДИНАТЫ. Группа стоит в (PALACE.x, PALACE.level, PALACE.z), то есть
  // в (620, 2.2, -299), и дальше всё считается в ЛОКАЛЬНЫХ координатах.
  // Местная нулевая точка — не дверь, а центр площадки, и отсюда все смещения:
  //
  //   дверь дворца      мир (620, -300)  ->  местные (0, -1)
  //   выход наружу      мир (620, -296)  ->  местные (0, +3)
  //   передняя стена    местная z = -1
  //
  // ПОЧЕМУ ПЕРЕДНЯЯ СТЕНА ЗАЛА ИМЕННО НА z = -1. Дверь в данных одна, и
  // игрок выходит из зала ровно туда. Если поставить стену в сторону от
  // данных, игрок выйдет на террасу задом к залу и в стену.
  //
  // ПОЧЕМУ ДВЕРЬ В ПРОЁМЕ, А НЕ В СПЛОШНОЙ СТЕНЕ. Передний ряд коллайдеров
  // пропускает |местная x| < 1.6. Без этого игрок подойдёт к стене вплотную
  // и не сможет её кликнуть — то есть не сможет войти. Ровно та же причина,
  // по которой у караван-сарая убран коллайдер в середине ворот.
  //
  // КОЛЛАЙДЕРЫ — ЦЕПОЧКОЙ МЕЛКИХ КРУГОВ, ПО 2 М. Один круг на всю стену
  // держал бы игрока в десяти метрах от неё: дверь есть, а подойти нельзя.
  const {
    // Зал тронный: 26 x 18, передняя стена на z = -1.
    hall: { w: HALL_W, d: HALL_D, h: HALL_H, t: HALL_T },
    // Стена комплекса: 32 x 42, ворота посередине южной (+z) стороны.
    wall: { w: WALL_W, h: WALL_H, t: WALL_T },
    gate: { w: GATE_W, h: GATE_H },
  } = PALACE_GEO;
  {
    const g = new THREE.Group();
    g.position.set(PALACE.x, PALACE.level, PALACE.z);

    // Плита двора. Тянется от передней стены зала до ворот и лежит почти
    // вровень с землёй — см. ДВОР_ПЛИТА, почему подъём 6 см, а не полметра.
    const court = new THREE.Mesh(
      new THREE.BoxGeometry(WALL_W - WALL_T, ДВОР_ПЛИТА.t, GATE_Z - HALL_FRONT_Z),
      MAT.sand,
    );
    court.position.set(0, ДВОР_ПЛИТА.подъём - ДВОР_ПЛИТА.t / 2, (HALL_FRONT_Z + GATE_Z) / 2);
    court.receiveShadow = true;
    g.add(court);

    // ── Стена комплекса ──
    const wallZ0 = ЗАДНЯЯ_СТЕНА_Z, wallZ1 = GATE_Z;
    for (const [wx, wz, ww, wd] of [
      [-WALL_W / 2, (wallZ0 + wallZ1) / 2, WALL_T, wallZ1 - wallZ0],
      [WALL_W / 2, (wallZ0 + wallZ1) / 2, WALL_T, wallZ1 - wallZ0],
    ] as const) {
      const w = new THREE.Mesh(new THREE.BoxGeometry(ww, WALL_H, wd), MAT.sandstoneDark);
      w.position.set(wx, WALL_H / 2, wz);
      w.castShadow = true; w.receiveShadow = true;
      g.add(w);
    }
    // Южная стена — двумя полотнами, проём посередине это ворота.
    for (const s of [-1, 1] as const) {
      const seg = (WALL_W - GATE_W) / 2;
      const w = new THREE.Mesh(new THREE.BoxGeometry(seg, WALL_H, WALL_T), MAT.sandstoneDark);
      w.position.set(s * (GATE_W / 2 + seg / 2), WALL_H / 2, wallZ1);
      w.castShadow = true; w.receiveShadow = true;
      g.add(w);
    }
    // Зубцы по периметру: коробка без зубцов читается как забор, а не как
    // крепостная стена.
    for (let wx = -WALL_W / 2 + 1; wx <= WALL_W / 2 - 1; wx += 2.4) {
      for (const wz of [wallZ0, wallZ1]) {
        if (wz === wallZ1 && Math.abs(wx) < GATE_W / 2 + 0.6) continue;
        const t = new THREE.Mesh(new THREE.BoxGeometry(1.2, 0.9, WALL_T), MAT.sandstone);
        t.position.set(wx, WALL_H + 0.45, wz);
        t.castShadow = true;
        g.add(t);
      }
    }
    for (let wz = wallZ0 + 1.2; wz <= wallZ1 - 1.2; wz += 2.4) {
      for (const wx of [-WALL_W / 2, WALL_W / 2]) {
        const t = new THREE.Mesh(new THREE.BoxGeometry(WALL_T, 0.9, 1.2), MAT.sandstone);
        t.position.set(wx, WALL_H + 0.45, wz);
        t.castShadow = true;
        g.add(t);
      }
    }

    // ── Угловые башни ──
    for (const [tx, tz] of [
      [-WALL_W / 2, wallZ0], [WALL_W / 2, wallZ0],
      [-WALL_W / 2, wallZ1], [WALL_W / 2, wallZ1],
    ] as const) {
      const tower = new THREE.Mesh(new THREE.CylinderGeometry(2.6, 3.2, WALL_H + 2, 10), MAT.sandstone);
      tower.position.set(tx, (WALL_H + 2) / 2, tz);
      tower.castShadow = true; tower.receiveShadow = true;
      const cap = new THREE.Mesh(new THREE.SphereGeometry(2.6, 12, 6, 0, Math.PI * 2, 0, Math.PI / 2), MAT.tealDome);
      cap.position.set(tx, WALL_H + 2, tz);
      cap.castShadow = true;
      g.add(tower, cap);
    }

    // ── Тронный зал ──
    const hallBack = HALL_FRONT_Z - HALL_D;
    const hallBox = (cx: number, cz: number, w: number, d: number, h: number, mat: THREE.Material) => {
      const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
      m.position.set(cx, h / 2, cz);
      m.castShadow = true; m.receiveShadow = true;
      g.add(m);
      return m;
    };
    hallBox(0, hallBack + HALL_T / 2, HALL_W, HALL_T, HALL_H, MAT.sandstone);
    hallBox(-HALL_W / 2 + HALL_T / 2, hallBack + HALL_D / 2, HALL_T, HALL_D, HALL_H, MAT.sandstone);
    hallBox(HALL_W / 2 - HALL_T / 2, hallBack + HALL_D / 2, HALL_T, HALL_D, HALL_H, MAT.sandstone);
    // Передняя стена зала — тремя полотнами, среднее оставляет проём двери.
    {
      const gap = ПАЛАЦНЫЙ_ПРОЁМ;
      const seg = (HALL_W - gap) / 2;
      hallBox(-(gap / 2 + seg / 2), HALL_FRONT_Z - HALL_T / 2, seg, HALL_T, HALL_H, MAT.sandstone);
      hallBox(gap / 2 + seg / 2, HALL_FRONT_Z - HALL_T / 2, seg, HALL_T, HALL_H, MAT.sandstone);
      // Перемычка над проёмом: она и держит переплёт, и закрывает зал сверху.
      const lintel = new THREE.Mesh(
        new THREE.BoxGeometry(gap + 0.6, HALL_H - 5.0, HALL_T),
        MAT.sandstone,
      );
      lintel.position.set(0, 5.0 + (HALL_H - 5.0) / 2, HALL_FRONT_Z - HALL_T / 2);
      lintel.castShadow = true;
      g.add(lintel);
    }

    // Купол. Барабан и шар на нём: у просто шара на плоской крыше нет шеи,
    // и купол читается как мяч, приплюснутый к стене.
    //
    // РАДИУС 7.5, А НЕ 8.5, И ЭТО ПО ГАБАРИТУ. Зал 18 м в глубину, то есть
    // от оси до стены 9 м. Барабан 9.2 наполовину вылезал наружу, и купол
    // нависал над стеной, как шляпа набок. 7.5 даёт полтора метра запаса до
    // стены с каждой стороны — купол стоит НА зале, а не над ним.
    const domeR = 7.5;
    const drum = new THREE.Mesh(
      new THREE.CylinderGeometry(domeR, domeR + 0.7, 3.0, 16),
      MAT.sandstone,
    );
    drum.position.set(0, HALL_H + 1.5, hallBack + HALL_D / 2);
    drum.castShadow = true;
    const dome = new THREE.Mesh(
      new THREE.SphereGeometry(domeR, 20, 10, 0, Math.PI * 2, 0, Math.PI / 2),
      MAT.tealDome,
    );
    dome.position.set(0, HALL_H + 3.0, hallBack + HALL_D / 2);
    dome.castShadow = true;
    // Бузлуз — золотой шпиль на макушке купола: без него купол считывается
    // как капля, а с ним как купол, потому что вертикаль на вертикали.
    //
    // СТОИТ НА ВЕРШИНЕ, А НЕ ВНУТРИ. Первая версия ставила шар на высоте
    // купол минус 1.1 м, то есть он целиком тонул в оболочке и не был виден
    // вообще: вершина купола на HALL_H + 3 + domeR, а шар стоял ниже неё.
    const вершина = HALL_H + 3.0 + domeR;
    const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.22, 0.3, 2.2, 8), MAT.gold);
    shaft.position.set(0, вершина + 1.1, hallBack + HALL_D / 2);
    const finial = new THREE.Mesh(new THREE.SphereGeometry(0.85, 10, 8), MAT.gold);
    finial.position.set(0, вершина + 2.6, hallBack + HALL_D / 2);
    g.add(drum, dome, shaft, finial);

    // ── Портал (пиштак) над входом в зал ──
    // Рамка с проёмом, бирюзовая полоса и наличник. Портал стоит ПЕРЕД
    // стеной зала, то есть выступает в +z: к нему и подходит игрок.
    //
    // ПОЧЕМУ ВЫСТУП 2.2 М, А НЕ БОЛЬШЕ. Выход наружу — местные (0, +3), то
    // есть в трёх метрах от линии двери. Портал шире 3 м накрыл бы точку
    // выхода, и игрок появлялся бы внутри стены.
    const portalZ = HALL_FRONT_Z + ПИШТАК.выступ / 2;
    {
      const pw = ПИШТАК.w;
      const frame = (dx: number, w: number, h: number, y: number, mat: THREE.Material) => {
        const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, ПИШТАК.выступ), mat);
        m.position.set(dx, y, portalZ);
        m.castShadow = true; m.receiveShadow = true;
        g.add(m);
      };
      // Пилоны по бокам.
      const pil = (pw - ПАЛАЦНЫЙ_ПРОЁМ) / 2;
      frame(-(ПАЛАЦНЫЙ_ПРОЁМ / 2 + pil / 2), pil, ПИШТАК.h, ПИШТАК.h / 2, MAT.sandstone);
      frame(ПАЛАЦНЫЙ_ПРОЁМ / 2 + pil / 2, pil, ПИШТАК.h, ПИШТАК.h / 2, MAT.sandstone);
      // Перемычка над проёмом — на неё опирается свод.
      frame(0, pw, ПИШТАК.h - 5.2, 5.2 + (ПИШТАК.h - 5.2) / 2, MAT.sandstone);
      // Свод — ПОЛУКОЛЬЦОМ, А НЕ КОНУСАМИ. Первая версия ставила два усечённых
      // конуса остриями друг к другу, рассчитывая получить стрельчатую арку.
      // Трёхгранный конус с поворотом на 30° вокруг вертикали торчал из проёма
      // чёрными осколками: на рендере вместо арки стояли два лезвия. У
      // полукольца нет ни вершин, ни рёбер, которые можно развернуть не туда.
      const арка = new THREE.Mesh(
        new THREE.TorusGeometry(ПАЛАЦНЫЙ_ПРОЁМ / 2, 0.3, 8, 24, Math.PI),
        MAT.sandstoneDark,
      );
      арка.position.set(0, 5.0 - ПАЛАЦНЫЙ_ПРОЁМ / 2, portalZ + ПИШТАК.выступ / 2 - 0.2);
      арка.castShadow = true;
      g.add(арка);
      // Тёмная заглушка в проёме. Без неё сквозь дверной проём видно небо:
      // зала снаружи нет, и дверь читалась бы как дыра в стене, а не как
      // вход. Ставится в плоскости стены, позади дверного полотна.
      const заглушка = new THREE.Mesh(
        new THREE.BoxGeometry(ПАЛАЦНЫЙ_ПРОЁМ, 5.0, 0.25),
        MAT.dark,
      );
      заглушка.position.set(0, 2.5, HALL_FRONT_Z + 0.12);
      g.add(заглушка);
      // Бирюзовая керамика по пилонам — то, за что Исфахан и узнают.
      for (const s of [-1, 1] as const) {
        const band = new THREE.Mesh(new THREE.BoxGeometry(pil + 0.12, ПИШТАК.h * 0.34, ПИШТАК.выступ + 0.12), MAT.tealDome);
        band.position.set(s * (ПАЛАЦНЫЙ_ПРОЁМ / 2 + pil / 2), ПИШТАК.h * 0.68, portalZ);
        g.add(band);
      }
      // Наличник над проёмом.
      const cornice = new THREE.Mesh(new THREE.BoxGeometry(pw + 0.5, 0.5, ПИШТАК.выступ + 0.5), MAT.sandstoneDark);
      cornice.position.set(0, ПИШТАК.h - 0.25, portalZ);
      g.add(cornice);
    }

    // Дверь. Кликабельная. Её ЛИЦО стоит на выходе наружу минус полметра:
    // точка выхода — местные (0, +3), и игрок должен появиться перед дверью,
    // а не внутри её полотна.
    const дверь = new THREE.Mesh(new THREE.BoxGeometry(ПАЛАЦНЫЙ_ПРОЁМ, 4.6, 0.3), MAT.wood);
    дверь.position.set(0, 2.3, HALL_FRONT_Z + ПИШТАК.выступ);
    дверь.userData = {
      doorBuilding: 'palace',
      doorAction: 'enter',
      doorName: t('buildings.palace'),
    };
    g.add(дверь);

    // ── Ворота комплекса ──
    // Айван над проёмом и два столба по краям. Проёма в стене нет: он и есть
    // проём, собранный двумя полотнами выше.
    tiledIwan(g, 0, wallZ1, GATE_W + 2.5, GATE_H, 0);
    for (const s of [-1, 1] as const) {
      const pier = new THREE.Mesh(new THREE.BoxGeometry(1.0, GATE_H + 1.0, WALL_T + 1.2), MAT.sandstone);
      pier.position.set(s * (GATE_W / 2 + 0.5), (GATE_H + 1.0) / 2, wallZ1);
      pier.castShadow = true;
      g.add(pier);
    }
    // ПЕРЕКРЫТИЕ НАД ПРОХОДОМ, А НЕ СПЛОШНОЙ БЛОК. Первая версия поставила
    // в проём тёмный ящик 3.2 м глубиной: он закрывал обзор, но игрок входил
    // прямо в него, потому что коллайдеров в воротах нет — проём проходимый
    // по условию. Перекрытие начинается на 3.2 м, то есть выше головы, и
    // проход остаётся тёмным и проходимым.
    const перекрытие = new THREE.Mesh(
      new THREE.BoxGeometry(GATE_W, GATE_H - 3.2, 4.0),
      MAT.dark,
    );
    перекрытие.position.set(0, 3.2 + (GATE_H - 3.2) / 2, wallZ1 - 2.0);
    g.add(перекрытие);
    // Свод прохода: полукольцо по верхней кромке, как над пиштаком.
    const свод = new THREE.Mesh(
      new THREE.TorusGeometry(GATE_W / 2, 0.28, 8, 20, Math.PI),
      MAT.sandstoneDark,
    );
    свод.position.set(0, 3.2, wallZ1 + 0.1);
    g.add(свод);

    // ── Бассейн во дворе ──
    // Хауз: прямоугольник с бортиком посреди двора. Без него двор пустой, а
    // персидский двор без воды не двор.
    //
    // ПОЧЕМУ ПО ЦЕНТРУ ДВОРА, А ПРОЁМ ВОРОТ УЖЕ БАССЕЙНА. Игрок идёт от
    // пиштака к воротам и обходит бассейн сбоку: по бокам от него 11.4 м
    // чистого камня. Ставить бассейн вбок от ворот можно, но тогда он
    // перекрывает половину двора и двор перестаёт читаться симметричным.
    {
      const bw = БАССЕЙН.w, bd = БАССЕЙН.d;
      // БОРТИК — РАМОЧКОЙ, А НЕ СПЛОШНЫМ БЛОКОМ. Сплошной блок 9.2 x 0.55 x
      // 6.2 накрывал воду сверху: она стояла на отметке 0.42 при высоте блока
      // 0.55, то есть была внутри него, и бассейн выглядел каменным ящиком без
      // воды. Рамочка из четырёх брусьев оставляет воде видимую гладь.
      const БОРТ = 0.6, ВЫС = 0.62;
      for (const [bw2, bd2, bx, bz] of [
        [bw + 2 * БОРТ, БОРТ, 0, -(bd / 2 + БОРТ / 2)],
        [bw + 2 * БОРТ, БОРТ, 0, bd / 2 + БОРТ / 2],
        [БОРТ, bd, -(bw / 2 + БОРТ / 2), 0],
        [БОРТ, bd, bw / 2 + БОРТ / 2, 0],
      ] as const) {
        const b = new THREE.Mesh(new THREE.BoxGeometry(bw2, ВЫС, bd2), MAT.sandstoneDark);
        b.position.set(bx, ВЫС / 2, БАССЕЙН.z + bz);
        b.castShadow = true; b.receiveShadow = true;
        g.add(b);
      }
      // Дно бассейна и вода в нём. Гладь на 0.46 — ниже борта в 0.62, то есть
      // вода утоплена и видно, что это бассейн, а не лужа на камне.
      const bottom = new THREE.Mesh(new THREE.BoxGeometry(bw, 0.2, bd), MAT.sandstoneDark);
      bottom.position.set(0, 0.1, БАССЕЙН.z);
      const water = new THREE.Mesh(new THREE.BoxGeometry(bw, 0.12, bd), MAT.water);
      water.position.set(0, 0.46, БАССЕЙН.z);
      g.add(bottom, water);
      // Коллайдеры по бортику: игрок не должен ни упасть в воду, ни пройти
      // сквозь борт. Цепочка мелких кругов по периметру бассейна.
      for (let bx = -bw / 2; bx <= bw / 2 + 0.01; bx += 2) {
        addCollider(PALACE.x + bx, PALACE.z + БАССЕЙН.z - bd / 2 - БОРТ / 2, 0.9);
        addCollider(PALACE.x + bx, PALACE.z + БАССЕЙН.z + bd / 2 + БОРТ / 2, 0.9);
      }
      for (let bz = -bd / 2; bz <= bd / 2 + 0.01; bz += 2) {
        addCollider(PALACE.x - bw / 2 - БОРТ / 2, PALACE.z + БАССЕЙН.z + bz, 0.9);
        addCollider(PALACE.x + bw / 2 + БОРТ / 2, PALACE.z + БАССЕЙН.z + bz, 0.9);
      }
    }

    // Кипарисы вдоль стен — вертикали, без них двор читается как пустая
    // площадка. Четыре с каждой стороны, у самых стен.
    //
    // НЕ СТАВЯТСЯ НА ПУТИ К ВОРОТАМ. Ближняя пара кипарисов стоит на
    // z = 8, а бассейн занимает z от 10 до 15: проём между ними сужался до
    // полутора метров, и игрок протискивался бы между стволом и бортом.
    for (let i = 0; i < 4; i++) {
      const cz = HALL_FRONT_Z + 3 + i * 4.4;
      if (cz > wallZ1 - 3) break;
      cypress(g, -WALL_W / 2 + 2.2, cz, ДВОР_ПЛИТА.подъём, 1.0);
      cypress(g, WALL_W / 2 - 2.2, cz, ДВОР_ПЛИТА.подъём, 1.0);
    }

    // ── Коллайдеры ──
    // Стена комплекса. Проём ворот оставлен ТОЛЬКО в южной (+z) стене.
    //
    // ПОЧЕМУ ДВЕ СТРОКИ, А НЕ ОДНА С УСЛОВИЕМ. Первая версия вешала обе
    // стены в одном цикле и пропускала точки по |wx| < GATE_W/2 — то есть
    // дыру в северной стене тоже. Двор оказывался проходимым насквозь: игрок
    // выходил из зала, нырял в щель между залом и дальней стеной и выходил
    // наружу с чужой стороны. Меша там глухая, проём есть только в воротах.
    for (let wx = -WALL_W / 2; wx <= WALL_W / 2; wx += 2) {
      addCollider(PALACE.x + wx, PALACE.z + wallZ0, 1.2);
      if (Math.abs(wx) >= GATE_W / 2) addCollider(PALACE.x + wx, PALACE.z + wallZ1, 1.2);
    }
    for (let wz = wallZ0; wz <= wallZ1; wz += 2) {
      addCollider(PALACE.x - WALL_W / 2, PALACE.z + wz, 1.2);
      addCollider(PALACE.x + WALL_W / 2, PALACE.z + wz, 1.2);
    }
    // Угловые башни.
    for (const [tx, tz] of [
      [-WALL_W / 2, wallZ0], [WALL_W / 2, wallZ0],
      [-WALL_W / 2, wallZ1], [WALL_W / 2, wallZ1],
    ] as const) {
      addCollider(PALACE.x + tx, PALACE.z + tz, 3.0);
    }
    // Зал: три глухие стены сплошной цепочкой, передняя — с проёмом двери.
    const stepHall = 2;
    for (let wx = -HALL_W / 2; wx <= HALL_W / 2; wx += stepHall) {
      addCollider(PALACE.x + wx, PALACE.z + hallBack + HALL_T / 2, 1.3);
      if (Math.abs(wx) >= ПАЛАЦНЫЙ_ПРОЁМ / 2 + 1.3) {
        addCollider(PALACE.x + wx, PALACE.z + HALL_FRONT_Z - HALL_T / 2, 1.3);
      }
    }
    for (let wz = hallBack + HALL_T; wz <= HALL_FRONT_Z - HALL_T; wz += stepHall) {
      addCollider(PALACE.x - HALL_W / 2 + HALL_T / 2, PALACE.z + wz, 1.3);
      addCollider(PALACE.x + HALL_W / 2 - HALL_T / 2, PALACE.z + wz, 1.3);
    }

    scene.add(g);
  }

  // ── Таможенный двор ────────────────────────────────────────────
  //
  // Третий по счёту экстерьер по заказу «заполним здание экстерьером».
  // Мечетный двор — §63, дворец — §65.
  //
  // ЧТО ЭТО. Запись интерьера «Таможенный двор. Западнее города: проверяет
  // идущих снаружи внутрь» существовала без дома: по точке (-900, 800) не
  // стояло ничего. Собрано то, что заявлено смыслом записи:
  //
  //   стена комплекса с воротами посередине (+z) — въезд снаружи;
  //   двор за воротами — то место, где досматривают;
  //   навес на четырёх столбах и стол под ним — «стол с документами», он же
  //     предмет в интерьере таможни, и двор теперь объясняет, откуда он;
  //   будка караула у ворот;
  //   дом с дверью в глубине — вход в интерьер.
  //
  // ПОЧЕМУ ВОРОТА НА +z. Точка выхода в данных — (-900, 804), то есть на
  // четыре метра больше z двери (-900, 800). Значит игрок выходит наружу в
  // сторону плюс z, и ворота должны быть с этой стороны: иначе он появился бы
  // за глухой стеной. Начало местных координат — сама линия двери, поэтому
  // дверь стоит в нуле, двор тянется от нуля до ворот, а дом уходит в
  // минус.
  {
    const {
      wall: { w: WALL_W, h: WALL_H, t: WALL_T },
      gate: { w: GATE_W, h: GATE_H },
      house: { w: HOUSE_W, d: HOUSE_D, h: HOUSE_H, t: HOUSE_T },
      booth: { w: BOOTH_W, d: BOOTH_D, h: BOOTH_H },
    } = CUSTOMS_GEO;
    const zBack = ТАМОЖНЯ_ЗАДНЯЯ_Z;
    const zGate = ТАМОЖНЯ_ВОРОТА_Z;

    const g = new THREE.Group();
    g.position.set(CUSTOMS.x, CUSTOMS.level, CUSTOMS.z);

    // Плита двора. От линии двери до ворот, почти вровень с землёй: подъём
    // 4 см — это читается как мощение, а не как цоколь. Толщина 0.2 м.
    const court = new THREE.Mesh(
      new THREE.BoxGeometry(WALL_W - WALL_T, ТАМОЖЕННЫЙ_ДВОР.t, zGate),
      MAT.sand,
    );
    court.position.set(0, ТАМОЖЕННЫЙ_ДВОР.подъём - ТАМОЖЕННЫЙ_ДВОР.t / 2, zGate / 2);
    court.receiveShadow = true;
    g.add(court);

    // ── Стены комплекса ──
    // Боковые — сплошные, от задней стены дома до ворот.
    for (const s of [-1, 1] as const) {
      const w = new THREE.Mesh(
        new THREE.BoxGeometry(WALL_T, WALL_H, zGate - zBack),
        MAT.sandstoneDark,
      );
      w.position.set(s * (WALL_W / 2 - WALL_T / 2), WALL_H / 2, (zBack + zGate) / 2);
      w.castShadow = true;
      w.receiveShadow = true;
      g.add(w);
    }
    // Передняя стена — двумя полотнами, проём посередине это ворота.
    const seg = (WALL_W - WALL_T * 2 - GATE_W) / 2;
    for (const s of [-1, 1] as const) {
      const w = new THREE.Mesh(new THREE.BoxGeometry(seg, WALL_H, WALL_T), MAT.sandstoneDark);
      w.position.set(
        s * (GATE_W / 2 + seg / 2),
        WALL_H / 2,
        zGate - WALL_T / 2,
      );
      w.castShadow = true;
      w.receiveShadow = true;
      g.add(w);
    }
    // Перемычка над воротами — проём закрыт сверху, иначе ворота читались бы
    // как дыра в стене до самого верха.
    const lintel = new THREE.Mesh(
      new THREE.BoxGeometry(GATE_W, WALL_H - GATE_H, WALL_T),
      MAT.sandstoneDark,
    );
    lintel.position.set(0, GATE_H + (WALL_H - GATE_H) / 2, zGate - WALL_T / 2);
    lintel.castShadow = true;
    g.add(lintel);

    // ── Столбы ворот ──
    // По одному с каждой стороны проёма, на 0.4 м шире стены: они держат
    // перемычку и читаются как въезд, а не как прореха.
    for (const s of [-1, 1] as const) {
      const pier = new THREE.Mesh(
        new THREE.BoxGeometry(0.9, GATE_H + 1.2, WALL_T + 0.7),
        MAT.sandstone,
      );
      pier.position.set(s * (GATE_W / 2 + 0.45), (GATE_H + 1.2) / 2, zGate - WALL_T / 2);
      pier.castShadow = true;
      g.add(pier);
    }
    // Угловые башни — по четыре, квадратные в плане, как у городской стены.
    for (const [tx, tz] of [
      [-WALL_W / 2, zBack], [WALL_W / 2, zBack],
      [-WALL_W / 2, zGate], [WALL_W / 2, zGate],
    ] as const) {
      const t2 = new THREE.Mesh(new THREE.BoxGeometry(2.6, WALL_H + 1.8, 2.6), MAT.sandstone);
      t2.position.set(tx, (WALL_H + 1.8) / 2, tz);
      t2.castShadow = true;
      t2.receiveShadow = true;
      g.add(t2);
      // Зубцы по краю — башня должна читаться как башня.
      for (let i = 0; i < 4; i++) {
        const merlon = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.6, 0.5), MAT.sandstoneDark);
        const a = (i * Math.PI) / 2 + Math.PI / 4;
        merlon.position.set(tx + Math.cos(a) * 0.95, WALL_H + 2.1, tz + Math.sin(a) * 0.95);
        g.add(merlon);
      }
    }

    // ── Таможенный дом ──
    // Стена сплошная с трёх сторон, четвёртая — с проёмом двери. Крыша плоская
    // с бортиком: дом служебный, и башня на нём была бы враньём.
    for (const [hx, hz, hw, hd] of [
      [0, zBack + HOUSE_T / 2, HOUSE_W, HOUSE_T],
      [-HOUSE_W / 2 + HOUSE_T / 2, zBack + HOUSE_D / 2, HOUSE_T, HOUSE_D],
      [HOUSE_W / 2 - HOUSE_T / 2, zBack + HOUSE_D / 2, HOUSE_T, HOUSE_D],
    ] as const) {
      const w = new THREE.Mesh(new THREE.BoxGeometry(hw, HOUSE_H, hd), MAT.sandstone);
      w.position.set(hx, HOUSE_H / 2, hz);
      w.castShadow = true;
      w.receiveShadow = true;
      g.add(w);
    }
    // Передняя стена — двумя полотнами по бокам проёма.
    const hSeg = (HOUSE_W - ТАМОЖЕННЫЙ_ПРОЁМ) / 2;
    for (const s of [-1, 1] as const) {
      const w = new THREE.Mesh(new THREE.BoxGeometry(hSeg, HOUSE_H, HOUSE_T), MAT.sandstone);
      w.position.set(s * (ТАМОЖЕННЫЙ_ПРОЁМ / 2 + hSeg / 2), HOUSE_H / 2, HOUSE_T / 2);
      w.castShadow = true;
      w.receiveShadow = true;
      g.add(w);
    }
    // Перемычка над дверью.
    const hLintel = new THREE.Mesh(
      new THREE.BoxGeometry(ТАМОЖЕННЫЙ_ПРОЁМ, HOUSE_H - 3.4, HOUSE_T),
      MAT.sandstone,
    );
    hLintel.position.set(0, 3.4 + (HOUSE_H - 3.4) / 2, HOUSE_T / 2);
    g.add(hLintel);
    // Крыша и бортик по периметру.
    const roof = new THREE.Mesh(
      new THREE.BoxGeometry(HOUSE_W + 0.5, 0.4, HOUSE_D + 0.5),
      MAT.sandstoneDark,
    );
    roof.position.set(0, HOUSE_H + 0.2, zBack + HOUSE_D / 2);
    roof.castShadow = true;
    g.add(roof);
    for (const [bx, bz, bw, bd] of [
      [0, zBack + 0.2, HOUSE_W + 0.7, 0.4],
      [0, zBack + HOUSE_D - 0.2, HOUSE_W + 0.7, 0.4],
      [-HOUSE_W / 2 + 0.2, zBack + HOUSE_D / 2, 0.4, HOUSE_D + 0.7],
      [HOUSE_W / 2 - 0.2, zBack + HOUSE_D / 2, 0.4, HOUSE_D + 0.7],
    ] as const) {
      const par = new THREE.Mesh(new THREE.BoxGeometry(bw, 0.7, bd), MAT.sandstoneDark);
      par.position.set(bx, HOUSE_H + 0.75, bz);
      g.add(par);
    }

    // Дверь. Лицо в плоскости стены плюс половина толщины: игрок выходит
    // в (-900, 804), то есть на четыре метра впереди, и должен оказаться
    // перед дверью, а не внутри её полотна.
    const door = new THREE.Mesh(
      new THREE.BoxGeometry(ТАМОЖЕННЫЙ_ПРОЁМ, 3.4, 0.3),
      MAT.wood,
    );
    door.position.set(0, 1.7, HOUSE_T / 2 + 0.15);
    door.userData = {
      doorBuilding: 'customs',
      doorAction: 'enter',
      doorName: t('buildings.customs'),
    };
    g.add(door);
    // Тёмная заглушка в проёме. Без неё сквозь дверной проём видно небо:
    // зала снаружи нет, и дверь читалась бы как дыра в стене.
    const jamb = new THREE.Mesh(
      new THREE.BoxGeometry(ТАМОЖЕННЫЙ_ПРОЁМ, 3.4, 0.25),
      MAT.dark,
    );
    jamb.position.set(0, 1.7, -0.12);
    g.add(jamb);
    // Наличник и клин над дверью — вход виден издалека, а это дорога, мимо
    // которой едут.
    const casing = new THREE.Mesh(
      new THREE.BoxGeometry(ТАМОЖЕННЫЙ_ПРОЁМ + 0.7, 0.35, HOUSE_T + 0.35),
      MAT.sandstoneDark,
    );
    casing.position.set(0, 3.55, HOUSE_T / 2);
    g.add(casing);

    // ── Навес досмотра ──
    // Четыре столба и плоская кровля над столом. Без него двор читается как
    // пустая площадка между стеной и домом.
    //
    // ПОЗИЦИЯ ВЫБРАНА ПРОХОДОМ, А НЕ СИММЕТРИЕЙ. Навес стоит у ворот, а не
    // посередине двора: посередине он перекрыл бы проход от ворот к двери, и
    // караван встал бы под крышей вместо того, чтобы въехать. Столы стоят
    // сбоку от оси проезда, а проезд остаётся свободным.
    const CANOPY_W = 7.0;
    const CANOPY_D = 6.0;
    const CANOPY_H = 3.2;
    const canopyZ = zGate - CANOPY_D / 2 - 1.5;
    // Столы — по краям навеса, ось проезда между ними свободна.
    for (const s of [-1, 1] as const) {
      const cx = s * (CANOPY_W / 2 - 1.1);
      for (const sz of [-1, 1] as const) {
        const post = new THREE.Mesh(new THREE.BoxGeometry(0.3, CANOPY_H, 0.3), MAT.wood);
        post.position.set(
          cx + sz * (CANOPY_D / 2 - 0.4),
          CANOPY_H / 2,
          canopyZ + sz * (CANOPY_D / 2 - 0.4),
        );
        post.castShadow = true;
        g.add(post);
      }
      // Стол досмотра под навесом: длинная доска на двух чурках.
      const table = new THREE.Mesh(new THREE.BoxGeometry(1.5, 0.12, 2.6), MAT.wood);
      table.position.set(cx, 0.95, canopyZ);
      table.castShadow = true;
      g.add(table);
      for (const sz of [-1, 1] as const) {
        const leg = new THREE.Mesh(new THREE.BoxGeometry(1.3, 0.9, 0.16), MAT.wood);
        leg.position.set(cx, 0.45, canopyZ + sz * 1.0);
        g.add(leg);
      }
      // Свитки и ящик на столе — то самое, что лежит в интерьере.
      const scroll = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.3, 0.7), MAT.sand);
      scroll.position.set(cx + 0.3, 1.16, canopyZ - 0.6);
      g.add(scroll);
    }
    const canopy = new THREE.Mesh(
      new THREE.BoxGeometry(CANOPY_W, 0.18, CANOPY_D),
      MAT.wood,
    );
    canopy.position.set(0, CANOPY_H + 0.09, canopyZ);
    canopy.castShadow = true;
    g.add(canopy);
    // Черепица узкой полосой по кровле — «навес», а не «крыша».
    const tiles = new THREE.Mesh(
      new THREE.BoxGeometry(CANOPY_W + 0.4, 0.12, CANOPY_D + 0.4),
      MAT.sandstoneDark,
    );
    tiles.position.set(0, CANOPY_H + 0.24, canopyZ);
    g.add(tiles);

    // ── Будка караула ──
    // Справа от ворот, внутри. Стоит на плите двора, поэтому подъём площадки
    // и не подъём будки совпадают.
    const boothX = WALL_W / 2 - BOOTH_W / 2 - 2.2;
    const boothZ = zGate - BOOTH_D / 2 - 1.6;
    for (const [bx, bz, bw, bd] of [
      [boothX, boothZ - BOOTH_D / 2, BOOTH_W, 0.3],
      [boothX - BOOTH_W / 2, boothZ, 0.3, BOOTH_D],
      [boothX + BOOTH_W / 2, boothZ, 0.3, BOOTH_D],
    ] as const) {
      const w = new THREE.Mesh(new THREE.BoxGeometry(bw, BOOTH_H, bd), MAT.sandstone);
      w.position.set(bx, BOOTH_H / 2, bz);
      w.castShadow = true;
      w.receiveShadow = true;
      g.add(w);
    }
    const boothRoof = new THREE.Mesh(
      new THREE.BoxGeometry(BOOTH_W + 0.6, 0.22, BOOTH_D + 0.6),
      MAT.wood,
    );
    boothRoof.position.set(boothX, BOOTH_H + 0.11, boothZ);
    boothRoof.castShadow = true;
    g.add(boothRoof);

    // ── Конфискованный груз ──
    // Ящики у будки. Это причина, по которой таможня вообще нужна, и без них
    // двор читается как пустая площадка.
    const CRATES: [number, number, number][] = [
      [-8.5, zGate - 3.0, 1.0],
      [-7.2, zGate - 3.4, 0.8],
      [-8.2, zGate - 4.4, 0.9],
      [8.6, zGate - 6.2, 1.1],
      [7.2, zGate - 6.6, 0.85],
    ];
    for (const [cx, cz, cs] of CRATES) {
      const crate = new THREE.Mesh(
        new THREE.BoxGeometry(cs, cs, cs),
        MAT.wood,
      );
      crate.position.set(cx, cs / 2, cz);
      crate.castShadow = true;
      crate.receiveShadow = true;
      g.add(crate);
    }
    // Бочка у стены — круглая, чтобы силуэт читался разнообразным.
    const barrel = new THREE.Mesh(
      new THREE.CylinderGeometry(0.45, 0.45, 1.0, 12),
      MAT.wood,
    );
    barrel.position.set(-WALL_W / 2 + 1.4, 0.5, zGate - 2.2);
    barrel.castShadow = true;
    g.add(barrel);

    // ── Коллайдеры ──
    // Цепочкой мелких кругов по 2 м, а не одним кругом на стену: крупный
    // круг держал бы игрока в метрах от проёма, и войти было бы нельзя.
    // Проём оставлен ТОЛЬКО в воротах на плюс z.
    for (let wx = -WALL_W / 2; wx <= WALL_W / 2; wx += 2) {
      // Задняя стена сплошная, проём только в воротах.
      addCollider(CUSTOMS.x + wx, CUSTOMS.z + zBack, 1.2);
      if (Math.abs(wx) >= GATE_W / 2) {
        addCollider(CUSTOMS.x + wx, CUSTOMS.z + zGate - WALL_T / 2, 1.2);
      }
    }
    for (let wz = zBack; wz <= zGate; wz += 2) {
      addCollider(CUSTOMS.x - WALL_W / 2, CUSTOMS.z + wz, 1.2);
      addCollider(CUSTOMS.x + WALL_W / 2, CUSTOMS.z + wz, 1.2);
    }
    // Угловые башни — сплошные.
    for (const [tx, tz] of [
      [-WALL_W / 2, zBack], [WALL_W / 2, zBack],
      [-WALL_W / 2, zGate], [WALL_W / 2, zGate],
    ] as const) {
      addCollider(CUSTOMS.x + tx, CUSTOMS.z + tz, 2.2);
    }
    // Столбы ворот коллайдерами НЕ перекрываются, и это не упущение.
    // Столб стоит на местных от 2.1 до 3.0, то есть ровно там, где уже лежит
    // стена, и стена закрыта коллайдером на |wx| = 3. Отдельный круг радиусом
    // 1.0 заходил в проём на 0.55 м с каждой стороны и сужал свободную полосу
    // игрока с 1.6 м до 1.1 м. Геометрия столба нужна, чтобы он держал
    // перемычку; коллайдер от него только мешал.
    // Дом: три глухие стены сплошной цепочкой, передняя — с проёмом двери.
    //
    // ПОЧЕМУ ПЕРЕДНИЙ РЯД ПРОПУСКАЕТ |wx| < 1.6. Без этого игрок подойдёт к
    // стене вплотную и не сможет её кликнуть, то есть не сможет войти.
    // Ровно та же причина, по которой у караван-сарая убран коллайдер в
    // середине ворот.
    for (let wx = -HOUSE_W / 2; wx <= HOUSE_W / 2; wx += 2) {
      addCollider(CUSTOMS.x + wx, CUSTOMS.z + zBack + HOUSE_T / 2, 1.2);
      if (Math.abs(wx) >= ТАМОЖЕННЫЙ_ПРОЁМ / 2 + 1.6) {
        addCollider(CUSTOMS.x + wx, CUSTOMS.z + HOUSE_T / 2, 1.2);
      }
    }
    for (let wz = zBack + HOUSE_T; wz <= HOUSE_T; wz += 2) {
      addCollider(CUSTOMS.x - HOUSE_W / 2 + HOUSE_T / 2, CUSTOMS.z + wz, 1.2);
      addCollider(CUSTOMS.x + HOUSE_W / 2 - HOUSE_T / 2, CUSTOMS.z + wz, 1.2);
    }
    // Будка — сплошная: это глухая коробка 3.2 м, войти туда не надо.
    addCollider(CUSTOMS.x + boothX, CUSTOMS.z + boothZ, 2.4);
    // Ящики: по одному кругу на ящик, иначе игрок проходил бы сквозь груз.
    for (const [cx, cz, cs] of CRATES) {
      addCollider(CUSTOMS.x + cx, CUSTOMS.z + cz, cs * 0.8);
    }
    addCollider(CUSTOMS.x + barrel.position.x, CUSTOMS.z + barrel.position.z, 0.7);

    scene.add(g);
  }

  // ── Ткацкая с кладовой ─────────────────────────────────────────
  //
  // Четвёртый по счёту экстерьер по заказу «заполним здание экстерьером».
  // Мечетный двор — §63, дворец — §65, таможня — §68.
  //
  // ЧТО ЭТО И ЧЕМ ОТЛИЧАЕТСЯ ОТ ТАМОЖНИ. Таможня — застава: стена, ворота,
  // проезд, досмотр. Здесь застава не нужна, и забор с проёмом был бы враньём.
  // Ткацкая — мастерская, и двор объясняет то, что стоит в интерьере:
  //
  //   высокие окна в верхнем ярусе — станки стоят у дальней стены и требуют
  //     света; здание выше таможни (9 м против 6.2) именно поэтому;
  //   кладовая-пристройка у самого порога — в интерьере мешки и корзины
  //     «ближе к двери: занятого снегут первым, и видно от входа»;
  //   сушильные вешалы во дворе — оттуда свисает ткань со станков;
  //   рулоны у кладовой — в интерьере стеллаж с рулонами, и двор объясняет,
  //     откуда они берутся.
  //
  // НАЧАЛО МЕСТНЫХ КООРДИНАТ — ЛИНИЯ ДВЕРИ, как у таможни: в данных
  // (820, -260) это сама дверь, выход (820, -256) на четыре метра дальше по
  // плюс z. Мастерская уходит в минус, двор тянется в плюс.
  {
    const {
      house: { w: HOUSE_W, d: HOUSE_D, h: HOUSE_H, t: HOUSE_T },
      store: { w: STORE_W, d: STORE_D, h: STORE_H, t: STORE_T },
      door: { w: DOOR_W, h: DOOR_H },
      racks,
    } = WEAVER_GEO;
    const zBack = ТКАЦКАЯ_ЗАДНЯЯ_Z;
    const zYard = ТКАЦКАЯ_ДВОР_Z;

    const g = new THREE.Group();
    g.position.set(WEAVER.x, WEAVER.level, WEAVER.z);

    // Плита двора. От линии двери до дальней границы двора, почти вровень:
    // подъём 3 см читается как мощение.
    const court = new THREE.Mesh(
      new THREE.BoxGeometry(HOUSE_W + 8, ТКАЦКАЯ_ДВОР.t, zYard),
      MAT.sand,
    );
    court.position.set(2, ТКАЦКАЯ_ДВОР.подъём - ТКАЦКАЯ_ДВОР.t / 2, zYard / 2);
    court.receiveShadow = true;
    g.add(court);

    // ── Мастерская ──
    // Три глухие стены и передняя с проёмом двери.
    for (const [hx, hz, hw, hd] of [
      [0, zBack + HOUSE_T / 2, HOUSE_W, HOUSE_T],
      [-HOUSE_W / 2 + HOUSE_T / 2, zBack + HOUSE_D / 2, HOUSE_T, HOUSE_D],
      [HOUSE_W / 2 - HOUSE_T / 2, zBack + HOUSE_D / 2, HOUSE_T, HOUSE_D],
    ] as const) {
      const w = new THREE.Mesh(new THREE.BoxGeometry(hw, HOUSE_H, hd), MAT.sandstone);
      w.position.set(hx, HOUSE_H / 2, hz);
      w.castShadow = true;
      w.receiveShadow = true;
      g.add(w);
    }
    // Передняя стена — по бокам проёма.
    const hSeg = (HOUSE_W - DOOR_W) / 2;
    for (const s of [-1, 1] as const) {
      const w = new THREE.Mesh(new THREE.BoxGeometry(hSeg, HOUSE_H, HOUSE_T), MAT.sandstone);
      w.position.set(s * (DOOR_W / 2 + hSeg / 2), HOUSE_H / 2, HOUSE_T / 2);
      w.castShadow = true;
      w.receiveShadow = true;
      g.add(w);
    }
    const hLintel = new THREE.Mesh(
      new THREE.BoxGeometry(DOOR_W, HOUSE_H - DOOR_H, HOUSE_T),
      MAT.sandstone,
    );
    hLintel.position.set(0, DOOR_H + (HOUSE_H - DOOR_H) / 2, HOUSE_T / 2);
    g.add(hLintel);

    // Окна. Узкие и высокие, двумя ярусами — станкам нужен свет, а стена
    // глухая в девять метров читалась бы как цоколь.
    //
    // ПОЧЕМУ ПРОЁМЫ, А НЕ ТЁМНЫЕ НАКЛЕЙКИ. Настоящее отверстие в стене
    // пропускает свет и вид на двор; наклейка выглядит как окно снаружи и
    // обманывает ровно до того момента, пока игрок не подойдёт вплотную.
    // Окна второго яруса — единственный источник света в цехе, поэтому они
    // и на дальней стене тоже.
    const ОКНА_ВЕРХНИЕ = 5;
    const ОКНА_НИЖНИЕ = 3;
    const оконныйПроём = (y: number, h: number): void => {
      for (let i = 0; i < ОКНА_ВЕРХНИЕ; i++) {
        const x = -HOUSE_W / 2 + (HOUSE_W / ОКНА_ВЕРХНИЕ) * (i + 0.5);
        const win = new THREE.Mesh(new THREE.BoxGeometry(1.2, h, HOUSE_T + 0.3), MAT.dark);
        win.position.set(x, y, HOUSE_T / 2);
        g.add(win);
        // Откос — узкая рамка, окно читается как проём, а не как щель.
        const frame = new THREE.Mesh(
          new THREE.BoxGeometry(1.55, h + 0.3, HOUSE_T + 0.15),
          MAT.sandstoneDark,
        );
        frame.position.set(x, y, HOUSE_T / 2 - 0.1);
        g.add(frame);
      }
    };
    оконныйПроём(HOUSE_H - 2.0, 1.8);
    // Нижний ярус — реже и ниже: цех заслоняют станки.
    for (let i = 0; i < ОКНА_НИЖНИЕ; i++) {
      const x = -HOUSE_W / 2 + (HOUSE_W / ОКНА_НИЖНИЕ) * (i + 0.5);
      if (Math.abs(x) < DOOR_W / 2 + 1.0) continue;
      const win = new THREE.Mesh(new THREE.BoxGeometry(1.4, 1.4, HOUSE_T + 0.3), MAT.dark);
      win.position.set(x, 2.6, HOUSE_T / 2);
      g.add(win);
      const frame = new THREE.Mesh(
        new THREE.BoxGeometry(1.75, 1.75, HOUSE_T + 0.15),
        MAT.sandstoneDark,
      );
      frame.position.set(x, 2.6, HOUSE_T / 2 - 0.1);
      g.add(frame);
    }
    // Дальняя стена — окна того же верхнего яруса. Без них цех был бы тёмным
    // с обеих сторон, а свет в интерьере берётся именно оттуда.
    for (let i = 0; i < ОКНА_ВЕРХНИЕ; i++) {
      const z = zBack + (HOUSE_D / ОКНА_ВЕРХНИЕ) * (i + 0.5);
      const win = new THREE.Mesh(new THREE.BoxGeometry(HOUSE_T + 0.3, 1.8, 1.2), MAT.dark);
      win.position.set(-HOUSE_W / 2 + HOUSE_T / 2, HOUSE_H - 2.0, z);
      g.add(win);
      const frame = new THREE.Mesh(
        new THREE.BoxGeometry(HOUSE_T + 0.15, 2.1, 1.55),
        MAT.sandstoneDark,
      );
      frame.position.set(-HOUSE_W / 2 + HOUSE_T / 2 - 0.1, HOUSE_H - 2.0, z);
      g.add(frame);
    }

    // Крыша плоская с бортиком, как у служебных построек.
    const roof = new THREE.Mesh(
      new THREE.BoxGeometry(HOUSE_W + 0.5, 0.4, HOUSE_D + 0.5),
      MAT.sandstoneDark,
    );
    roof.position.set(0, HOUSE_H + 0.2, zBack + HOUSE_D / 2);
    roof.castShadow = true;
    g.add(roof);
    for (const [bx, bz, bw, bd] of [
      [0, zBack + 0.2, HOUSE_W + 0.7, 0.4],
      [0, zBack + HOUSE_D - 0.2, HOUSE_W + 0.7, 0.4],
      [-HOUSE_W / 2 + 0.2, zBack + HOUSE_D / 2, 0.4, HOUSE_D + 0.7],
      [HOUSE_W / 2 - 0.2, zBack + HOUSE_D / 2, 0.4, HOUSE_D + 0.7],
    ] as const) {
      const par = new THREE.Mesh(new THREE.BoxGeometry(bw, 0.7, bd), MAT.sandstoneDark);
      par.position.set(bx, HOUSE_H + 0.75, bz);
      g.add(par);
    }

    // ── Дверь ──
    // Лицо в плоскости стены плюс половина толщины: игрок выходит в
    // (820, -256), то есть на четыре метра впереди, и должен оказаться перед
    // дверью, а не внутри её полотна.
    const door = new THREE.Mesh(new THREE.BoxGeometry(DOOR_W, DOOR_H, 0.3), MAT.wood);
    door.position.set(0, DOOR_H / 2, HOUSE_T / 2 + 0.15);
    door.userData = {
      doorBuilding: 'weaver',
      doorAction: 'enter',
      doorName: t('buildings.weaver'),
    };
    g.add(door);
    const jamb = new THREE.Mesh(
      new THREE.BoxGeometry(ТКАЦКАЯ_ЗАГЛУШКА.w, ТКАЦКАЯ_ЗАГЛУШКА.h, ТКАЦКАЯ_ЗАГЛУШКА.t),
      MAT.dark,
    );
    jamb.position.set(0, DOOR_H / 2, -0.12);
    g.add(jamb);
    const casing = new THREE.Mesh(
      new THREE.BoxGeometry(DOOR_W + 0.7, 0.35, HOUSE_T + 0.35),
      MAT.sandstoneDark,
    );
    casing.position.set(0, DOOR_H + 0.18, HOUSE_T / 2);
    g.add(casing);

    // ── Кладовая-пристройка ──
    // Сбоку от мастерской, ближе к порогу: в интерьере мешки стоят у входа.
    const storeX = HOUSE_W / 2 + STORE_W / 2 - 0.6;
    const storeZ = zBack + STORE_D / 2 + 2.4;
    for (const [sx2, sz2, sw, sd] of [
      [storeX, storeZ - STORE_D / 2, STORE_W, STORE_T],
      [storeX - STORE_W / 2, storeZ, STORE_T, STORE_D],
      [storeX + STORE_W / 2, storeZ, STORE_T, STORE_D],
    ] as const) {
      const w = new THREE.Mesh(new THREE.BoxGeometry(sw, STORE_H, sd), MAT.sandstoneDark);
      w.position.set(sx2, STORE_H / 2, sz2);
      w.castShadow = true;
      w.receiveShadow = true;
      g.add(w);
    }
    // Передняя стена кладовой — с проёмом: мешки несут через него.
    const storeSeg = (STORE_W - 1.8) / 2;
    for (const s of [-1, 1] as const) {
      const w = new THREE.Mesh(
        new THREE.BoxGeometry(storeSeg, STORE_H, STORE_T),
        MAT.sandstoneDark,
      );
      w.position.set(
        storeX + s * (0.9 + storeSeg / 2),
        STORE_H / 2,
        storeZ + STORE_D / 2 - STORE_T / 2,
      );
      w.castShadow = true;
      g.add(w);
    }
    const storeLintel = new THREE.Mesh(
      new THREE.BoxGeometry(1.8, STORE_H - 2.6, STORE_T),
      MAT.sandstoneDark,
    );
    storeLintel.position.set(storeX, 2.6 + (STORE_H - 2.6) / 2, storeZ + STORE_D / 2 - STORE_T / 2);
    g.add(storeLintel);
    const storeRoof = new THREE.Mesh(
      new THREE.BoxGeometry(STORE_W + 0.5, 0.3, STORE_D + 0.5),
      MAT.wood,
    );
    storeRoof.position.set(storeX, STORE_H + 0.15, storeZ);
    storeRoof.castShadow = true;
    g.add(storeRoof);
    // Проём кладовой заглушен: за ней комната, а её нет снаружи.
    const storeJamb = new THREE.Mesh(new THREE.BoxGeometry(1.8, 2.6, 0.2), MAT.dark);
    storeJamb.position.set(storeX, 1.3, storeZ + STORE_D / 2 - STORE_T);
    g.add(storeJamb);

    // ── Сушильные вешалы ──
    // Два ряда столбов, между ними провисает ткань. Отсюда на станках свисает
    // готовый кусок — двор объясняет, откуда он берётся.
    //
    // РЯДЫ СТОЯТ В ДВОРЕ, А НЕ НА ПРОХОДЕ. Между рядами и дверью остаётся
    // 6.5 м: вешалы не должны перекрывать подход от выхода к двери.
    const rackZ = [zYard - racks.gap / 2 - 1.2, zYard - 1.0];
    for (const rz of rackZ) {
      for (const s of [-1, 1] as const) {
        const post = new THREE.Mesh(
          new THREE.BoxGeometry(0.22, racks.h, 0.22),
          MAT.wood,
        );
        post.position.set(s * (racks.w / 2 - 0.3), racks.h / 2, rz);
        post.castShadow = true;
        g.add(post);
      }
      // Поперечина и провисшая ткань между столбами.
      const bar = new THREE.Mesh(
        new THREE.BoxGeometry(racks.w - 0.6, 0.12, 0.12),
        MAT.wood,
      );
      bar.position.set(0, racks.h - 0.2, rz);
      g.add(bar);
      for (const [dx, ширина, высота] of [
        [-2.2, 2.6, 2.2], [0.4, 3.0, 2.6], [3.0, 1.8, 1.6],
      ] as const) {
        const cloth = new THREE.Mesh(
          new THREE.BoxGeometry(ширина, высота, 0.06),
          dx % 2 === 0 ? MAT.tealDome : MAT.sand,
        );
        cloth.position.set(dx, racks.h - 0.3 - высота / 2, rz);
        cloth.castShadow = true;
        g.add(cloth);
      }
    }

    // ── Рулоны ткани у кладовой ──
    // В интерьере стеллаж с рулонами, и двор объясняет, откуда они берутся.
    // Круглые в сечении — рулон это цилиндр.
    const РУЛОНЫ: [number, number, number][] = [
      [storeX + 0.6, storeZ + STORE_D / 2 + 1.4, 0],
      [storeX + 1.6, storeZ + STORE_D / 2 + 1.2, 1],
      [storeX + 1.1, storeZ + STORE_D / 2 + 2.4, 0],
      [storeX + 0.4, storeZ + STORE_D / 2 + 2.6, 1],
    ];
    for (const [rx, rz, лежат] of РУЛОНЫ) {
      const roll = new THREE.Mesh(
        new THREE.CylinderGeometry(0.36, 0.36, 1.9, 10),
        лежат ? MAT.gold : MAT.tealDome,
      );
      roll.rotation.z = Math.PI / 2;
      roll.position.set(rx, 0.36, rz);
      roll.castShadow = true;
      g.add(roll);
    }

    // ── Забор двора ──
    // Низкий, с проёмом у двери. Забора с воротами здесь нет: застава нет.
    const ЗАБОР_H = 1.2;
    const заборX = HOUSE_W / 2 + 8;
    for (const s of [-1, 1] as const) {
      const w = new THREE.Mesh(
        new THREE.BoxGeometry(0.3, ЗАБОР_H, zYard - 0.5),
        MAT.wood,
      );
      w.position.set(s * заборX, ЗАБОР_H / 2, (zYard - 0.5) / 2);
      w.castShadow = true;
      g.add(w);
    }
    // Передняя сторона — двумя полотнами, проём посередине шириной 4 м.
    const проём = 4.0;
    const segF = (2 * заборX - проём) / 2;
    for (const s of [-1, 1] as const) {
      const w = new THREE.Mesh(new THREE.BoxGeometry(segF, ЗАБОР_H, 0.3), MAT.wood);
      w.position.set(s * (проём / 2 + segF / 2), ЗАБОР_H / 2, zYard - 0.5);
      w.castShadow = true;
      g.add(w);
    }

    // ── Коллайдеры ──
    // Цепочкой мелких кругов по 2 м. Крупный круг на стену держал бы игрока
    // в метрах от проёма, и войти было бы нельзя.
    for (let wx = -HOUSE_W / 2; wx <= HOUSE_W / 2; wx += 2) {
      addCollider(WEAVER.x + wx, WEAVER.z + zBack + HOUSE_T / 2, 1.2);
      if (Math.abs(wx) >= DOOR_W / 2 + 1.6) {
        addCollider(WEAVER.x + wx, WEAVER.z + HOUSE_T / 2, 1.2);
      }
    }
    for (let wz = zBack + HOUSE_T; wz <= HOUSE_T; wz += 2) {
      addCollider(WEAVER.x - HOUSE_W / 2 + HOUSE_T / 2, WEAVER.z + wz, 1.2);
      addCollider(WEAVER.x + HOUSE_W / 2 - HOUSE_T / 2, WEAVER.z + wz, 1.2);
    }
    // Кладовая: три глухие стены и передняя с проёмом.
    for (let sx2 = -STORE_W / 2; sx2 <= STORE_W / 2; sx2 += 2) {
      addCollider(WEAVER.x + storeX + sx2, WEAVER.z + storeZ - STORE_D / 2, 1.1);
      if (Math.abs(sx2) >= 0.9 + 1.4) {
        addCollider(
          WEAVER.x + storeX + sx2,
          WEAVER.z + storeZ + STORE_D / 2 - STORE_T / 2,
          1.1,
        );
      }
    }
    for (let sz2 = -STORE_D / 2 + STORE_T; sz2 <= STORE_D / 2 - STORE_T; sz2 += 2) {
      addCollider(WEAVER.x + storeX - STORE_W / 2, WEAVER.z + storeZ + sz2, 1.1);
      addCollider(WEAVER.x + storeX + STORE_W / 2, WEAVER.z + storeZ + sz2, 1.1);
    }
    // Столбы вешалов — по одному кругу на столб, иначе игрок проходит сквозь
    // перекладину на высоте груди.
    for (const rz of rackZ) {
      for (const s of [-1, 1] as const) {
        addCollider(
          WEAVER.x + s * (racks.w / 2 - 0.3),
          WEAVER.z + rz,
          0.45,
        );
      }
    }
    // Рулоны лежат на земле — по кругу на каждый.
    for (const [rx, rz] of РУЛОНЫ) {
      addCollider(WEAVER.x + rx, WEAVER.z + rz, 0.6);
    }
    // Забор: проём оставлен ТОЛЬКО посередине передней стороны, иначе двор
    // проходим насквозь с любой точки.
    for (let zx = 0.5; zx <= zYard - 0.5; zx += 2) {
      addCollider(WEAVER.x - заборX, WEAVER.z + zx, 1.0);
      addCollider(WEAVER.x + заборX, WEAVER.z + zx, 1.0);
    }
    for (let fx = -заборX; fx <= заборX; fx += 2) {
      if (Math.abs(fx) >= проём / 2 + 0.6) {
        addCollider(WEAVER.x + fx, WEAVER.z + zYard - 0.5, 1.0);
      }
    }

    scene.add(g);
  }
  // ── Горное святилище ───────────────────────────────────────────
  //
  // Пятый по счёту экстерьер по заказу «заполним здание экстерьером».
  // Мечетный двор — §63, дворец — §65, таможня — §68, ткацкая — §69.
  //
  // ПЛАНИРОВКА ИЗ ИНТЕРЬЕРА, А НЕ ПРИДУМАННАЯ. Первая сборка стоила замера: я
  // поставил руинную стену между дверью и алтарём, и замер показал просвет по
  // оси -2.54 м, то есть прохода не было вовсе. В furnishShrine стена с
  // проломом стоит на cz - 10.2, а алтарь с огнём на cz - 7: стена ЗА алтарём,
  // это дальняя стена руинного двора. Теперь так и построено — дверь на
  // локальном z = 0, зал уходит в минус, терраса тянется в плюс.
  //
  // ЧТО ЭТО. Руина на уступе, и это меняет всё, что делалось раньше. Таможня
  // строилась: стена, ворота, навес. Ткацкая строилась: мастерская, кладовая.
  // Здесь стены стоят обломками, пролом шире двери, крыши нет, а огонь видно
  // снаружи. Зороастрийское святилище нельзя построить «ровным»: необработанный
  // камень и есть его вид, и ровная кладка была бы враньём.
  //
  // ЧТО ДВОР ОБЪЯСНЯЕТ, а всё из интерьера furnishShrine:
  //
  //   дальняя стена с широким проломом — внутри та же стена, и пролом там
  //     «шире ворот: войти можно, но стена всё равно читается как стена»;
  //   огонь в жаровне перед дверью — внутри алтарь с огнём в глубине, и по
  //     зороастрийскому обычаю огонь священ: его выносят наружу, чтобы паломник
  //     увидел пламя ещё от дороги;
  //   дымовая труба — огонь внутри, и дым над трубой виден издалека, то есть
  //     святилище находится с дороги, а не находится поиском по карте;
  //   ниши с фресками на боковых стенах — внутри рельефы с фресками в нишах;
  //   обломки у основания дальней стены — внутри «провалившиеся куски стены», и
  //     снаружи они лежат там же, откуда упали;
  //   заросли — внутри «трава пролзла через руины», и снаружи она лезет через
  //     ту же осыпь;
  //   уступ с подпорной стенкой — решение владельца от 07.10.2026. Святилище
  //     огня на возвышенности верно по канону: огонь ставят на сухом месте
  //     повыше.
  //
  // ТЕРРАСА ПОДНЯТА НА 1.2 М, И ЭТО ВЫЯСНИЛ ЗАМЕР, А НЕ ПРЕДПОЛОЖЕНИЕ. Уровень
  // площадки выбран по медиане, то есть земля вокруг выровнена до 1.1 м на 30.8 м,
  // и склон начинается только дальше. Первая сборка строила подпорную стенку
  // высотой 2.6 м и четыре ступени, и обе были враньём: замер показал 1.10 м на
  // всей дистанции до z = 27, то есть ступени спускались в РОВНУЮ землю и вели в
  // пустоту, а стенка уходила вниз в ту же землю и держать ей было нечего.
  // Теперь терраса и здание стоят НАД ровной землёй, и стенка держит подиум.
  //
  // НАЧАЛО МЕСТНЫХ КООРДИНАТ — ЛИНИЯ ДВЕРИ, как у таможни и ткацкой: в данных
  // (1200, 1200) это сама дверь, а выход (1200, 1204) на четыре метра дальше по
  // плюс z. Игрок выходит на террасу и стоит на ней.
  {
    const {
      зал: { w: HALL_W },
      wall: { t: WALL_T },
      door: { w: DOOR_W, h: DOOR_H },
      gap: { w: GAP_W },
      terrace: { w: TERR_W, d: TERR_D },
      ступени,
      parapet,
      chimney,
      brazier,
    } = SHRINE_GEO;
    const ПОДЪЁМ = СВЯТИЛИЩЕ_ПОДЪЁМ;
    const zЗад = СВЯТИЛИЩЕ_ЗАДНЯЯ_Z;
    const стенаZ = zЗад + WALL_T / 2;

    const g = new THREE.Group();
    // Группа стоит на УРОВНЕ ПЛОЩАДКИ плюс подъём: подиум поднимает и террасу,
    // и здание. Подпорная стенка строится в минус отсюда, до земли.
    g.position.set(SHRINE.x, SHRINE.level + ПОДЪЁМ, SHRINE.z);

    // ── Плита террасы ──
    // Подъём 4 см — мощение, а не второй цоколь поверх первого.
    const плита = new THREE.Mesh(
      new THREE.BoxGeometry(TERR_W, СВЯТИЛИЩЕ_ПЛИТА.t, TERR_D),
      MAT.stone,
    );
    плита.position.set(0, СВЯТИЛИЩЕ_ПЛИТА.подъём - СВЯТИЛИЩЕ_ПЛИТА.t / 2, TERR_D / 2);
    плита.receiveShadow = true;
    g.add(плита);

    // Плита зала: пол руинного двора. Уровень тот же, что у террасы, иначе
    // через порог был бы порог.
    const пол = new THREE.Mesh(
      new THREE.BoxGeometry(HALL_W, СВЯТИЛИЩЕ_ПЛИТА.t, -zЗад),
      MAT.sandstone,
    );
    пол.position.set(0, СВЯТИЛИЩЕ_ПЛИТА.подъём - СВЯТИЛИЩЕ_ПЛИТА.t / 2, zЗад / 2);
    пол.receiveShadow = true;
    g.add(пол);

    // ── Подпорная стенка ──
    // Идёт по всему периметру подиума и держит его над ровной землёй. В проёме
    // на подветренном краю — ступени, иначе сход с уступа был бы прыжком.
    const проёмСтупеней = ступени.ширина + 1.2;
    for (const s of [-1, 1] as const) {
      // Боковая стенка. Ширина террасы равна ширине зала, поэтому боковые стенки
      // упираются прямо в стены зала и щели между ними не остаётся.
      const бок = new THREE.Mesh(
        new THREE.BoxGeometry(WALL_T, ПОДЪЁМ, TERR_D + WALL_T),
        MAT.sandstoneDark,
      );
      бок.position.set(
        s * (TERR_W / 2 + WALL_T / 2),
        -ПОДЪЁМ / 2 - СВЯТИЛИЩЕ_ПЛИТА.подъём,
        TERR_D / 2 - WALL_T / 2,
      );
      бок.castShadow = true;
      бок.receiveShadow = true;
      g.add(бок);
      // Дальняя стенка, под стеной руинного двора.
      const зад = new THREE.Mesh(
        new THREE.BoxGeometry(TERR_W + WALL_T * 2, ПОДЪЁМ, WALL_T),
        MAT.sandstoneDark,
      );
      зад.position.set(0, -ПОДЪЁМ / 2 - СВЯТИЛИЩЕ_ПЛИТА.подъём, zЗад - WALL_T / 2);
      зад.castShadow = true;
      зад.receiveShadow = true;
      g.add(зад);
    }
    // Передняя стенка — двумя полотнами, проём под ступени посередине.
    const полотно = (TERR_W + WALL_T * 2 - проёмСтупеней) / 2;
    for (const s of [-1, 1] as const) {
      const w = new THREE.Mesh(
        new THREE.BoxGeometry(полотно, ПОДЪЁМ, WALL_T),
        MAT.sandstoneDark,
      );
      w.position.set(
        s * (проёмСтупеней / 2 + полотно / 2),
        -ПОДЪЁМ / 2 - СВЯТИЛИЩЕ_ПЛИТА.подъём,
        TERR_D + WALL_T / 2,
      );
      w.castShadow = true;
      w.receiveShadow = true;
      g.add(w);
    }

    // ── Ступени вниз с подветренного края ──
    // Три ступени по 0.4 м — ровно на подъём 1.2 м, то есть сход с подиума на
    // землю без прыжка. Ступени стоят В ПРОЁМЕ стенки, а не перед ней.
    for (let i = 0; i < ступени.число; i++) {
      const y = -(i + 1) * ступени.подъём - СВЯТИЛИЩЕ_ПЛИТА.подъём;
      const ст = new THREE.Mesh(
        new THREE.BoxGeometry(ступени.ширина, ступени.подъём + 0.2, ступени.шаг),
        MAT.stone,
      );
      ст.position.set(0, y + ступени.подъём / 2, TERR_D + WALL_T / 2 + i * ступени.шаг);
      ст.castShadow = true;
      ст.receiveShadow = true;
      g.add(ст);
    }

    // ── Парапет по краю террасы ──
    // Низкий, чтобы терраса оставалась террасой, а не крепостью: игрок должен
    // видеть склон, ради которого она и вырезана. На подветренном краю, где
    // ступени, парапета нет — иначе он перекрыл бы сход.
    for (const s of [-1, 1] as const) {
      const бок = new THREE.Mesh(
        new THREE.BoxGeometry(0.45, parapet.h, TERR_D),
        MAT.sandstone,
      );
      бок.position.set(s * (TERR_W / 2 - 0.225), parapet.h / 2, TERR_D / 2);
      бок.castShadow = true;
      g.add(бок);
      const передний = new THREE.Mesh(
        new THREE.BoxGeometry(
          (TERR_W - проёмСтупеней) / 2,
          parapet.h,
          0.45,
        ),
        MAT.sandstone,
      );
      передний.position.set(
        s * (проёмСтупеней / 2 + (TERR_W - проёмСтупеней) / 4),
        parapet.h / 2,
        TERR_D - 0.225,
      );
      передний.castShadow = true;
      g.add(передний);
    }

    // ── Боковые стены руинного двора ──
    // Низкий цоколь на всю длину, а выше обломки разной высоты с проломами:
    // руина стоит обломками, и ровные прямоугольники были бы враньём. По этому
    // же и читается руина, а не просто невысокая стена.
    for (const s of [-1, 1] as const) {
      const px = s * (HALL_W / 2 + WALL_T / 2);
      const цоколь = new THREE.Mesh(
        new THREE.BoxGeometry(WALL_T, 1.2, -zЗад + WALL_T),
        MAT.stone,
      );
      цоколь.position.set(px, 0.6, zЗад / 2);
      цоколь.castShadow = true;
      цоколь.receiveShadow = true;
      g.add(цоколь);
      const верх: [number, number, number][] = [
        [-zЗад + 2.5, 4.0, 2.6],
        [-zЗад + 8.0, 3.4, 1.4],
        [-zЗад + 13.0, 2.8, 2.2],
      ];
      for (const [vz, vlen, vh] of верх) {
        const w = new THREE.Mesh(new THREE.BoxGeometry(WALL_T, vh, vlen), MAT.sandstone);
        w.position.set(px, 1.2 + vh / 2, vz);
        w.castShadow = true;
        w.receiveShadow = true;
        g.add(w);
        // Скол верхней кромки: обломок на краю, а не ровный срез.
        const скол = new THREE.Mesh(
          new THREE.BoxGeometry(WALL_T + 0.25, 0.45, vlen * 0.4),
          MAT.sandstoneDark,
        );
        скол.position.set(px, 1.2 + vh + 0.15, vz + vlen * 0.2);
        скол.rotation.x = 0.1;
        скол.castShadow = true;
        g.add(скол);
      }
    }

    // ── Передняя стена с проёмом двери ──
    // Стена на локальном z = 0: это и есть линия двери из данных. По бокам
    // проёма два полотна, над проёмом перемычка.
    const сегмент = (HALL_W - DOOR_W) / 2;
    for (const s of [-1, 1] as const) {
      const w = new THREE.Mesh(new THREE.BoxGeometry(сегмент, 3.4, WALL_T), MAT.sandstone);
      w.position.set(s * (DOOR_W / 2 + сегмент / 2), 1.7, WALL_T / 2);
      w.castShadow = true;
      w.receiveShadow = true;
      g.add(w);
    }
    const перемычка = new THREE.Mesh(
      new THREE.BoxGeometry(DOOR_W, 1.0, WALL_T),
      MAT.sandstone,
    );
    перемычка.position.set(0, DOOR_H + 0.5, WALL_T / 2);
    перемычка.castShadow = true;
    g.add(перемычка);

    // ── Дальняя стена руинного двора с проломом ──
    // Это та стена, что в интерьере стоит на cz - 10.2, то есть ЗА алтарём.
    // Здесь она на локальном z = -16. Четыре полотна разной высоты и ширины,
    // пролом между ними: стена рушилась сверху.
    const руина: [number, number, number][] = [
      // x-центр, ширина, высота
      [-HALL_W / 2 + 2.0, 4.0, 3.4],
      [-HALL_W / 2 + 5.25, 2.5, 2.3],
      [HALL_W / 2 - 5.25, 2.5, 2.9],
      [HALL_W / 2 - 2.0, 4.0, 1.6],
    ];
    for (const [rx, rw, rh] of руина) {
      const w = new THREE.Mesh(new THREE.BoxGeometry(rw, rh, WALL_T), MAT.stone);
      w.position.set(rx, rh / 2, стенаZ);
      w.castShadow = true;
      w.receiveShadow = true;
      g.add(w);
      const скол = new THREE.Mesh(
        new THREE.BoxGeometry(rw * 0.35, 0.5, WALL_T + 0.25),
        MAT.sandstoneDark,
      );
      скол.position.set(rx + rw * 0.22, rh + 0.2, стенаZ);
      скол.rotation.z = 0.12;
      скол.castShadow = true;
      g.add(скол);
    }
    // Столбы по краям пролома: пролом вышел, а не просел.
    for (const s of [-1, 1] as const) {
      const столб = new THREE.Mesh(new THREE.BoxGeometry(0.8, 4.2, WALL_T), MAT.stone);
      // Пион по краю обвала: чуть ВНУТРИ проёма, а не в кладке. При +0.4 он
      // целиком уходил в панель стены, начинающуюся ровно с GAP_W / 2.
      столб.position.set(s * (GAP_W / 2 - 0.4), 2.1, стенаZ);
      столб.castShadow = true;
      столб.receiveShadow = true;
      g.add(столб);
    }

    // ── Ниши с фресками в боковых стенах ──
    // Внутри рельефы с фресками в нишах на боковых стенах (на cx +/- 9.9).
    // Ниша снаружи читается как проём в толще стены: тёмная ниша и светлее
    // рельеф внутри, иначе её не разглядеть.
    for (const s of [-1, 1] as const) {
      const px = s * (HALL_W / 2 + WALL_T / 2);
      const nz = zЗад + 6;
      const ниша = new THREE.Mesh(new THREE.BoxGeometry(WALL_T + 0.2, 2.4, 2.0), MAT.dark);
      ниша.position.set(px, 2.2, nz);
      g.add(ниша);
      const рельеф = new THREE.Mesh(new THREE.BoxGeometry(WALL_T + 0.1, 1.7, 1.4), MAT.gold);
      рельеф.position.set(px, 2.2, nz);
      g.add(рельеф);
    }

    // ── Дымовая труба над алтарём ──
    // Огонь внутри, в алтаре у дальней стены (в интерьере cz - 7, здесь -9).
    // Труба нужна, чтобы дым было видно с дороги: святилище должно находиться
    // издалека, а не искаться на карте.
    const труба = new THREE.Mesh(
      new THREE.BoxGeometry(chimney.w, chimney.h, chimney.d),
      MAT.sandstone,
    );
    труба.position.set(0, chimney.h / 2, zЗад + 3.5);
    труба.castShadow = true;
    g.add(труба);
    // Дым: три убывающих блока, чтобы читался столб, а не куб.
    for (let i = 0; i < 3; i++) {
      const дым = new THREE.Mesh(
        new THREE.BoxGeometry(chimney.w + i * 1.1, 1.5, chimney.d + i * 1.1),
        MAT.white,
      );
      дым.position.set(0, chimney.h + 0.9 + i * 1.7, zЗад + 3.5);
      g.add(дым);
    }

    // ── Жаровня перед дверью ──
    // Огонь священ, и по обычаю его выносят наружу: паломник должен увидеть
    // пламя ещё от дороги. Внутри алтарь в глубине — снаружи жаровня у входа.
    //
    // Жаровня бронзовая, MAT.gold. Материала iron в палитре terrain нет: он есть
    // в interiors, у которой своя палитра M. Копировать ради одной жаровни
    // незачем — бронза здесь и в каноне, и в интерьере у алтаря.
    const жаровняX = TERR_W / 2 - 4.0;
    const жаровняZ = 5.5;
    const чаша = new THREE.Mesh(
      new THREE.CylinderGeometry(brazier.r, brazier.r * 0.8, brazier.h, 8),
      MAT.gold,
    );
    чаша.position.set(жаровняX, 0.9 + brazier.h / 2, жаровняZ);
    чаша.castShadow = true;
    g.add(чаша);
    for (const s of [-1, 1] as const) {
      const нога = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.9, 0.16), MAT.gold);
      нога.position.set(жаровняX + s * 0.5, 0.45, жаровняZ);
      g.add(нога);
    }
    // Пламя: два конуса, малый в большом, как в интерьере у алтаря.
    const пламя1 = new THREE.Mesh(
      new THREE.CylinderGeometry(0.28, 0.62, 1.3, 8),
      MAT.clothRed,
    );
    пламя1.position.set(жаровняX, brazier.h + 1.5, жаровняZ);
    g.add(пламя1);
    const пламя2 = new THREE.Mesh(
      new THREE.CylinderGeometry(0.18, 0.42, 1.9, 8),
      MAT.gold,
    );
    пламя2.position.set(жаровняX, brazier.h + 1.75, жаровняZ);
    g.add(пламя2);

    // ── Дверь в передней стене ──
    // Лицо в плоскости стены плюс половина толщины: игрок выходит в (1200,
    // 1204), то есть на четыре метра впереди, и должен оказаться перед дверью,
    // а не внутри её полотна.
    const дверь = new THREE.Mesh(new THREE.BoxGeometry(DOOR_W, DOOR_H, 0.3), MAT.wood);
    дверь.position.set(0, DOOR_H / 2, WALL_T / 2 + 0.15);
    дверь.userData = {
      doorBuilding: 'shrine',
      doorAction: 'enter',
      doorName: t('buildings.shrine'),
    };
    g.add(дверь);
    const заглушка = new THREE.Mesh(
      new THREE.BoxGeometry(СВЯТИЛИЩЕ_ЗАГЛУШКА.w, СВЯТИЛИЩЕ_ЗАГЛУШКА.h, СВЯТИЛИЩЕ_ЗАГЛУШКА.t),
      MAT.dark,
    );
    заглушка.position.set(0, DOOR_H / 2, WALL_T / 2 - 0.05);
    g.add(заглушка);

    // ── Обломки у основания дальней стены ──
    // Внутри «провалившиеся куски стены». Снаружи они должны лежать там, откуда
    // упали: у основания дальней стены, а не ровным рядом вдоль террасы.
    const ОБЛОМКИ: [number, number, number][] = [
      [-HALL_W / 2 + 3.0, zЗад + WALL_T + 1.6, 0.4],
      [-HALL_W / 2 + 6.5, zЗад + WALL_T + 0.6, 1.1],
      [HALL_W / 2 - 2.6, zЗад + WALL_T + 1.4, 0.7],
      [HALL_W / 2 - 5.8, zЗад + WALL_T + 3.2, 2.1],
      [-HALL_W / 2 + 9.0, zЗад + WALL_T + 2.5, 0.2],
      [HALL_W / 2 - 1.5, zЗад + WALL_T + 2.8, 1.5],
    ];
    for (const [ox, oz, rot] of ОБЛОМКИ) {
      const обломок = new THREE.Mesh(new THREE.BoxGeometry(2.2, 0.9, 1.6), MAT.stone);
      обломок.position.set(ox, 0.45, oz);
      обломок.rotation.y = rot;
      обломок.castShadow = true;
      обломок.receiveShadow = true;
      g.add(обломок);
    }

    // ── Заросли ──
    // Внутри «трава пролзла через руины», и снаружи она лезет через ту же
    // осыпь. Ставим у обломков, а не ровным рядом: трава растёт от влаги и
    // корней, а не по линейке.
    const ЗАРОСЛИ: [number, number][] = [];
    for (const [ox, oz] of ОБЛОМКИ) {
      ЗАРОСЛИ.push([ox + 1.6, oz + 1.2], [ox - 1.4, oz - 0.8]);
    }
    ЗАРОСЛИ.push([-2.0, zЗад + WALL_T + 4.0], [3.2, zЗад + WALL_T + 3.0]);
    for (const [gx, gz] of ЗАРОСЛИ) {
      const трава = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.7, 0.5), MAT.brush);
      трава.position.set(gx, 0.35, gz);
      g.add(трава);
    }

    // ── Коллайдеры ──
    // Цепочками мелких кругов. Крупный круг на стену держал бы игрока в метрах
    // от проёма, и войти было бы нельзя.
    //
    // ОСОБОЕ ВНИМАНИЕ К ДВЕРЯМ. Проём в передней стене должен остаться
    // открытым, иначе к двери не подойти, а значит и не войти. Пролом в дальней
    // стене шире двери втрое, и он остаётся открытым по всей ширине.
    for (let hx = -HALL_W / 2; hx <= HALL_W / 2; hx += 2) {
      if (Math.abs(hx) >= DOOR_W / 2 + 1.4) {
        addCollider(SHRINE.x + hx, SHRINE.z + WALL_T / 2, 1.1);
      }
    }
    // Боковые стены: цоколь сплошной цепочкой.
    for (let hz = zЗад + WALL_T; hz <= 0; hz += 2) {
      addCollider(SHRINE.x - HALL_W / 2 - WALL_T / 2, SHRINE.z + hz, 1.1);
      addCollider(SHRINE.x + HALL_W / 2 + WALL_T / 2, SHRINE.z + hz, 1.1);
    }
    // Дальняя стена: сплошной цепочкой, кроме пролома.
    for (const [rx, rw] of руина) {
      for (let cx2 = rx - rw / 2; cx2 <= rx + rw / 2; cx2 += 2) {
        addCollider(SHRINE.x + cx2, SHRINE.z + стенаZ, 1.1);
      }
    }
    // Столбы пролома — узкие, пролом остаётся широким.
    for (const s of [-1, 1] as const) {
      addCollider(SHRINE.x + s * (GAP_W / 2 - 0.4), SHRINE.z + стенаZ, 0.9);
    }
    // Обломки: по кругу на каждый, иначе игрок проходит сквозь камень.
    for (const [ox, oz] of ОБЛОМКИ) {
      addCollider(SHRINE.x + ox, SHRINE.z + oz, 1.3);
    }
    // Труба: в стену войти нельзя.
    addCollider(SHRINE.x, SHRINE.z + zЗад + 3.5, chimney.w * 0.7);
    // Жаровня: одно кольцо, иначе игрок проходит сквозь огонь.
    addCollider(SHRINE.x + жаровняX, SHRINE.z + жаровняZ, brazier.r + 0.5);
    // Край подиума: игрок не сходит с уступа. ПО ПРОЁМУ СТУПЕНЕЙ НЕ СТАВИМ
    // НИЧЕГО, иначе сход с уступа будет перекрыт.
    for (let tx = -TERR_W / 2; tx <= TERR_W / 2; tx += 2.5) {
      // Проём под ступени оставляем: иначе сход с уступа перекрыт. Раньше
      // здесь стояла цепочка без условия, хотя комментарий выше говорил,
      // что по проёму ничего не ставится, — комментарий и код разошлись, и
      // это поймал замер: на z = 10.7 стоял коллайдер.
      if (Math.abs(tx) >= проёмСтупеней / 2 + 0.6) {
        addCollider(SHRINE.x + tx, SHRINE.z + TERR_D + WALL_T / 2, 1.1);
      }
    }
    for (let tz = zЗад; tz <= TERR_D; tz += 2.5) {
      addCollider(SHRINE.x - TERR_W / 2 - WALL_T / 2, SHRINE.z + tz, 1.1);
      addCollider(SHRINE.x + TERR_W / 2 + WALL_T / 2, SHRINE.z + tz, 1.1);
    }
    // Парапет: игрок не проходит сквозь край террасы, кроме проёма под ступени.
    for (const s of [-1, 1] as const) {
      for (let tx = 0.6; tx <= TERR_W / 2; tx += 2) {
        const sx = s * tx;
        if (sx > 0.6 && sx < TERR_W / 2 - 0.5) {
          addCollider(SHRINE.x + sx, SHRINE.z + TERR_D / 2, 0.9);
        }
      }
      addCollider(SHRINE.x + s * (TERR_W / 2 - 0.225), SHRINE.z + TERR_D / 2, 0.9);
    }
    for (const s of [-1, 1] as const) {
      const от = проёмСтупеней / 2 + 0.6;
      for (let tx = от; tx <= TERR_W / 2; tx += 2) {
        addCollider(SHRINE.x + s * tx, SHRINE.z + TERR_D - 0.225, 0.9);
      }
    }

    scene.add(g);
  }
  // ── Ханза: караванный двор ─────────────────────────────────────
  //
  // Шестой и последний экстерьер по заказу «заполним здание экстерьером».
  // Мечетный двор — §63, дворец — §65, таможня — §68, ткацкая — §69, святилище —
  // §70.
  //
  // ПЛАНИРОВКА ИЗ ИНТЕРЬЕРА. Зал 22 x 16 (ROOM_W x ROOM_D), дверь на локальном
  // z = 0, задняя стена на z = -16. Двор перед дверью — главный, 28 x 12.
  //
  // ЧЕМ ОТЛИЧАЕТСЯ ОТ ПРЕДЫДУЩИХ. Таможня — застава, ткацкая — мастерская,
  // святилище — руина на уступе. Здесь торговый двор: товарные ряды под навесом,
  // весы у въезда, надписи на столбах, мешки и короба, следы копыт к воротам.
  // Двор не защищают — сюда принимают товар.
  //
  // ДВОР ОБЪЯСНЯЕТ ИНТЕРЬЕР, а всё из furnishHanza: столы со свитками, стеллажи,
  // надписи плитами разной высоты, сломанные весы — чаша на боку, стрелка упала
  // отдельно — и следы копыт дугой к двери. Соответствие такое:
  //
  //   сломанные весы в интерьере -> целые весы у въезда: взвешивают товар;
  //   надписи плитами на стене -> надписи на столбах у въезда;
  //   стеллажи и столы со свитками -> товарные ряды под навесом: свитки и товар
  //     — одно и то же по смыслу «ханжа читает письма и письма»;
  //   следы копыт дугой к двери -> следы выезда с двора в плюс z.
  //
  // УРОВЕНЬ -8.4: ханза стоит в старой ложбине. Срез до 1.66 м в склон, засыпка
  // до 1.19 м с подветренной стороны. Стенки двора высотой 1.2 м закрывают край
  // насыпи и читаются как ограда рынка.
  //
  // НАЧАЛО МЕСТНЫХ КООРДИНАТ — ЛИНИЯ ДВЕРИ. В (1600, 1000) сама дверь, выход
  // (1600, 1004) на четыре метра дальше по плюс z.
  {
    const {
      зал: { w: HALL_W },
      wall: { t: WALL_T },
      door: { w: DOOR_W, h: DOOR_H },
      yard: { w: YARD_W, d: YARD_D },
      wallYard,
      canopy,
      rows,
      scales,
    } = HANZA_GEO;
    const zЗад = ХАНЗА_ЗАДНЯЯ_Z;
    // Граница двора — из YARD_D, константа ХАНЗА_ДВОР_Z остаётся числом в ROADMAP.

    const g = new THREE.Group();
    g.position.set(HANZA.x, HANZA.level, HANZA.z);

    // ── Плита двора ──
    const плита = new THREE.Mesh(
      new THREE.BoxGeometry(YARD_W, ХАНЗА_ПЛИТА.t, YARD_D),
      MAT.sand,
    );
    плита.position.set(0, ХАНЗА_ПЛИТА.подъём - ХАНЗА_ПЛИТА.t / 2, YARD_D / 2);
    плита.receiveShadow = true;
    g.add(плита);

    // Плита зала.
    const пол = new THREE.Mesh(
      new THREE.BoxGeometry(HALL_W, ХАНЗА_ПЛИТА.t, -zЗад),
      MAT.sandstone,
    );
    пол.position.set(0, ХАНЗА_ПЛИТА.подъём - ХАНЗА_ПЛИТА.t / 2, zЗад / 2);
    пол.receiveShadow = true;
    g.add(пол);

    // ── Стенки двора ──
    // Высота 1.2 м: ограда рынка и край насыпи в одном. Глухие с боков, с
    // проёмом у въезда спереди.
    for (const s of [-1, 1] as const) {
      const бок = new THREE.Mesh(
        new THREE.BoxGeometry(wallYard.t, wallYard.h, YARD_D + wallYard.t),
        MAT.sandstoneDark,
      );
      бок.position.set(s * (YARD_W / 2 + wallYard.t / 2), wallYard.h / 2, YARD_D / 2 - wallYard.t / 2);
      бок.castShadow = true;
      бок.receiveShadow = true;
      g.add(бок);
      // Дальняя стенка под стеной зала.
      const зад = new THREE.Mesh(
        new THREE.BoxGeometry(YARD_W + wallYard.t * 2, wallYard.h, wallYard.t),
        MAT.sandstoneDark,
      );
      зад.position.set(0, wallYard.h / 2, zЗад - wallYard.t / 2);
      зад.castShadow = true;
      зад.receiveShadow = true;
      g.add(зад);
    }
    // Передняя стенка — двумя полотнами, проём под въезд.
    const проём = DOOR_W + 2.0;
    const полотно = (YARD_W + wallYard.t * 2 - проём) / 2;
    for (const s of [-1, 1] as const) {
      const w = new THREE.Mesh(
        new THREE.BoxGeometry(полотно, wallYard.h, wallYard.t),
        MAT.sandstoneDark,
      );
      w.position.set(s * (проём / 2 + полотно / 2), wallYard.h / 2, YARD_D + wallYard.t / 2);
      w.castShadow = true;
      w.receiveShadow = true;
      g.add(w);
    }

    // ── Зал: стены ──
    // Три глухие стены и передняя с проёмом двери.
    for (const [hx, hz, hw, hd] of [
      [0, zЗад + WALL_T / 2, HALL_W, WALL_T],
      [-HALL_W / 2 + WALL_T / 2, zЗад + (HALL_W - WALL_T) / 2, WALL_T, HALL_W - WALL_T],
      [HALL_W / 2 - WALL_T / 2, zЗад + (HALL_W - WALL_T) / 2, WALL_T, HALL_W - WALL_T],
    ] as const) {
      const w = new THREE.Mesh(new THREE.BoxGeometry(hw, 4.4, hd), MAT.sandstone);
      w.position.set(hx, 2.2, hz);
      w.castShadow = true;
      w.receiveShadow = true;
      g.add(w);
    }
    // Передняя стена с проёмом.
    const сегмент = (HALL_W - DOOR_W) / 2;
    for (const s of [-1, 1] as const) {
      const w = new THREE.Mesh(new THREE.BoxGeometry(сегмент, 4.4, WALL_T), MAT.sandstone);
      w.position.set(s * (DOOR_W / 2 + сегмент / 2), 2.2, WALL_T / 2);
      w.castShadow = true;
      w.receiveShadow = true;
      g.add(w);
    }
    const перемычка = new THREE.Mesh(
      new THREE.BoxGeometry(DOOR_W, 0.8, WALL_T),
      MAT.sandstone,
    );
    перемычка.position.set(0, DOOR_H + 0.4, WALL_T / 2);
    перемычка.castShadow = true;
    g.add(перемычка);

    // Крыша хана: двускатная, читается издалека.
    const крыша = new THREE.Mesh(
      new THREE.ConeGeometry(HALL_W / 2 + 1.2, 2.4, 4),
      MAT.sandstoneDark,
    );
    крыша.position.set(0, 4.4 + 1.2, zЗад + 8);
    крыша.rotation.y = Math.PI / 4;
    крыша.castShadow = true;
    g.add(крыша);

    // ── Дверь ──
    const дверь = new THREE.Mesh(new THREE.BoxGeometry(DOOR_W, DOOR_H, 0.3), MAT.wood);
    дверь.position.set(0, DOOR_H / 2, WALL_T / 2 + 0.15);
    дверь.userData = {
      doorBuilding: 'hanza',
      doorAction: 'enter',
      doorName: t('buildings.hanza'),
    };
    g.add(дверь);
    const заглушка = new THREE.Mesh(
      new THREE.BoxGeometry(ХАНЗА_ЗАГЛУШКА.w, ХАНЗА_ЗАГЛУШКА.h, ХАНЗА_ЗАГЛУШКА.t),
      MAT.dark,
    );
    заглушка.position.set(0, DOOR_H / 2, WALL_T / 2 - 0.05);
    g.add(заглушка);

    // ── Навес над товарными рядами ──
    // Стойки и скат: ряды товара под крышей, как в караван-сарае.
    const навесZ = 3.0;
    for (const s of [-1, 1] as const) {
      for (const pz of [навесZ - canopy.d / 2, навесZ + canopy.d / 2]) {
        const столб = new THREE.Mesh(new THREE.BoxGeometry(0.3, canopy.h, 0.3), MAT.wood);
        столб.position.set(s * (canopy.w / 2 - 0.4), canopy.h / 2, pz);
        столб.castShadow = true;
        g.add(столб);
      }
    }
    const навес = new THREE.Mesh(
      new THREE.BoxGeometry(canopy.w, 0.18, canopy.d),
      MAT.sandstoneDark,
    );
    навес.position.set(0, canopy.h + 0.09, навесZ);
    навес.castShadow = true;
    навес.receiveShadow = true;
    g.add(навес);

    // ── Товарные ряды: мешки и короба ──
    const МЕШКИ: [number, number, number, number][] = [];
    for (let i = 0; i < rows.len; i += 1.6) {
      const mx = -rows.len / 2 + i;
      // Центральный проход от двери до дальнего края двора оставлен свободным:
      // мешок на оси перекроет подъезд и сам проезд. Ширина прохода семь метров.
      if (Math.abs(mx) < 3.5) continue;
      for (const rz of [навесZ - 1.2, навесZ + 1.2]) {
        МЕШКИ.push([mx, rz, 0.5 + (i % 3) * 0.15, (i * 0.7) % 1.2]);
      }
    }
    for (const [mx, mz, mh, rot] of МЕШКИ) {
      const мешок = new THREE.Mesh(
        new THREE.CylinderGeometry(0.5, 0.55, mh, 8),
        MAT.sand,
      );
      мешок.position.set(mx, mh / 2, mz);
      мешок.rotation.y = rot;
      мешок.castShadow = true;
      g.add(мешок);
      // Палитра помельче — коробы.
      const короб = new THREE.Mesh(new THREE.BoxGeometry(1.0, 0.7, 1.0), MAT.wood);
      короб.position.set(mx + 0.8, 0.35, mz + 0.2);
      короб.rotation.y = rot * 1.3;
      короб.castShadow = true;
      g.add(короб);
    }

    // ── Весы у въезда ──
    // Целая пара: стойка, перекладина, чаши. Сломанные весы внутри объясняются
    // этими: товар взвешивали здесь, потом сломали, но двор не закрыли.
    const весыX = YARD_W / 2 - 3.0;
    const весыZ = 2.0;
    const стойка = new THREE.Mesh(new THREE.BoxGeometry(0.3, scales.h, 0.3), MAT.wood);
    стойка.position.set(весыX, scales.h / 2, весыZ);
    стойка.castShadow = true;
    g.add(стойка);
    const перекладина = new THREE.Mesh(new THREE.BoxGeometry(2.6, 0.16, 0.16), MAT.wood);
    перекладина.position.set(весыX, scales.h - 0.1, весыZ);
    g.add(перекладина);
    for (const s of [-1, 1] as const) {
      const чаша = new THREE.Mesh(
        new THREE.CylinderGeometry(0.55, 0.4, 0.25, 10),
        MAT.gold,
      );
      чаша.position.set(весыX + s * 1.15, scales.h - 0.9, весыZ);
      чаша.castShadow = true;
      g.add(чаша);
      const тяга = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.8, 0.06), MAT.wood);
      тяга.position.set(весыX + s * 1.15, scales.h - 0.5, весыZ);
      g.add(тяга);
    }

    // ── Надписи на столбах у въезда ──
    // Плиты разной высоты и наклона, как в интерьере.
    for (let i = 0; i < 3; i++) {
      const высота = 2.0 + (i % 2) * 0.5;
      const столб = new THREE.Mesh(
        new THREE.BoxGeometry(0.6, высота, 0.6),
        MAT.stone,
      );
      столб.position.set(-YARD_W / 2 + 2.5 + i * 2.4, высота / 2, YARD_D - 1.2);
      столб.castShadow = true;
      g.add(столб);
      const плита = new THREE.Mesh(
        new THREE.BoxGeometry(1.4, высота * 0.7, 0.14),
        MAT.sandstone,
      );
      плита.position.set(-YARD_W / 2 + 2.5 + i * 2.4, высота * 0.55, YARD_D - 0.85);
      плита.rotation.z = (i % 2 === 0 ? 1 : -1) * 0.05;
      g.add(плита);
    }

    // ── Следы копыт к въезду и со двора ──
    // Дугой от въезда в плюс z, как в интерьере — отпечатки ведут к выходу.
    const СЛЕДЫ: [number, number][] = [];
    for (let i = 0; i < 8; i++) {
      const side = i % 2 === 0 ? 1 : -1;
      СЛЕДЫ.push([side * (1.8 + i * 0.35), YARD_D + 1.0 + i * 1.6]);
    }
    for (const [sx, sz] of СЛЕДЫ) {
      const след = new THREE.Mesh(
        new THREE.BoxGeometry(0.34, 0.05, 0.5),
        MAT.dark,
      );
      след.position.set(sx, 0.06, sz);
      след.rotation.y = (sx > 0 ? 1 : -1) * 0.2;
      g.add(след);
    }

    // ── Коллайдеры ──
    // Цепочками мелких кругов. Проёмы остаются открытыми: дверь в зале, проём в
    // стенке двора у въезда.
    //
    // Особое внимание к въезду: ворота шире двери на метр с каждой стороны, и
    // проём в стенке двора должен оставаться открытым, иначе торговец не везёт.
    // Передняя стена зала с проёмом двери.
    // Проём считает передняя цепочка по DOOR_W, дубль сегмента не нужен.
    for (let sx = -HALL_W / 2; sx <= HALL_W / 2; sx += 2) {
      if (Math.abs(sx) >= DOOR_W / 2 + 1.5) {
        addCollider(HANZA.x + sx, HANZA.z + WALL_T / 2, 1.1);
      }
    }
    // Задняя и боковые стены зала.
    for (let sx = -HALL_W / 2; sx <= HALL_W / 2; sx += 2) {
      addCollider(HANZA.x + sx, HANZA.z + zЗад + WALL_T / 2, 1.1);
    }
    for (let sz = zЗад + WALL_T; sz <= 0; sz += 2) {
      addCollider(HANZA.x - HALL_W / 2 - WALL_T / 2, HANZA.z + sz, 1.1);
      addCollider(HANZA.x + HALL_W / 2 + WALL_T / 2, HANZA.z + sz, 1.1);
    }
    // Стенки двора: передняя с проёмом, боковые глухие, задняя под залом.
    const проём2 = DOOR_W + 2.0;
    for (let tx = -YARD_W / 2; tx <= YARD_W / 2; tx += 2) {
      if (Math.abs(tx) >= проём2 / 2 + 0.6) {
        addCollider(HANZA.x + tx, HANZA.z + YARD_D + wallYard.t / 2, 1.0);
      }
    }
    for (let tz = 0; tz <= YARD_D; tz += 2) {
      addCollider(HANZA.x - YARD_W / 2 - wallYard.t / 2, HANZA.z + tz, 1.0);
      addCollider(HANZA.x + YARD_W / 2 + wallYard.t / 2, HANZA.z + tz, 1.0);
    }
    for (let tx = -YARD_W / 2; tx <= YARD_W / 2; tx += 2) {
      addCollider(HANZA.x + tx, HANZA.z + zЗад - wallYard.t / 2, 1.0);
    }
    // Стойки навеса.
    for (const s of [-1, 1] as const) {
      for (const pz of [навесZ - canopy.d / 2, навесZ + canopy.d / 2]) {
        addCollider(HANZA.x + s * (canopy.w / 2 - 0.4), HANZA.z + pz, 0.5);
      }
    }
    // Весы: одно кольцо, иначе игрок проходит сквозь стойку.
    addCollider(HANZA.x + весыX, HANZA.z + весыZ, 1.2);
    // Надписи на столбах: у каждого столб-и-плита.
    for (let i = 0; i < 3; i++) {
      addCollider(HANZA.x - YARD_W / 2 + 2.5 + i * 2.4, HANZA.z + YARD_D - 1.2, 0.8);
    }
    // Мешки и короба: по кругу на каждый. Игрок не проходит сквозь товар.
    for (const [mx, mz] of МЕШКИ) {
      addCollider(HANZA.x + mx, HANZA.z + mz, 0.8);
    }

    scene.add(g);
  }
  // ── Гробница Шеиха ─────────────────────────────────────────────
  //
  // Седьмое по счёту здание с экстерьером. Мечетный двор — §63, дворец — §65,
  // таможня — §68, ткацкая — §69, святилище — §70, ханза — §72.
  //
  // ГДЕ. Залив — §63, дворнett — §65, таможня — §68, ткацкая — §69, святилище —
  // §70, ханза — §72.
  //
  // ЧЕМ ОТЛИЧАЕТСЯ. Таможня — застава, ткацкая — мастерская, святилище —
  // руина на уступе, ханза — товарный двор. Здесь гробница: надземный корпус, в
  // который спускаются по лестнице. Дверь подземной комнаты, снаружи — портик.
  //
  // ДВОР ОБЪЯСНЯЕТ ИНТЕРЬЕР, а всё из furnishTomb: саркофаг в центре, решётка,
  // лестница вниз у входа, ниши со свитками, светильники, 20 сундуков. Снаружи:
  //   * лестница вниз к двери — внутри лестница продолжается вниз;
  //   * надземный корпус — внутри подземный зал;
  //   * ворота в ограде — интерьер даётся только после входа.
  //
  // УРОВЕНЬ -2.5. Гробница зарыта в склон: корпус врезается в ложбину задней
  // стеной, а лестница спускается с уровня земли к двери.
  //
  // НАЧАЛО МЕСТНЫХ КООРДИНАТ — ЛИНИЯ ДВЕРИ. В (1400, 1400) сама дверь, выход
  // (1400, 1404) на четыре метра дальше.
  {
    const {
      корпус: { w: HALL_W, d: HALL_D, h: HALL_H, t: WALL_T },
      door: { w: DOOR_W, h: DOOR_H },
      лестница,
      двор: { w: YARD_W },
      wallYard,
    } = TOMB_GEO;
    const zЗад = ГРОБНИЦА_ЗАДНЯЯ_Z;
    const zДвор = ГРОБНИЦА_ДВОР_Z;

    const g = new THREE.Group();
    g.position.set(TOMB.x, TOMB.level, TOMB.z);

    // ── Плита двора ──
    const плитаДвора = new THREE.Mesh(
      new THREE.BoxGeometry(YARD_W, ГРОБНИЦА_ПЛИТА.t, zДвор),
      MAT.sand,
    );
    плитаДвора.position.set(0, ГРОБНИЦА_ПЛИТА.подъём - ГРОБНИЦА_ПЛИТА.t / 2, zДвор / 2);
    плитаДвора.receiveShadow = true;
    g.add(плитаДвора);

    // Плита пола корпуса.
    const пол = new THREE.Mesh(
      new THREE.BoxGeometry(HALL_W, ГРОБНИЦА_ПЛИТА.t, HALL_D),
      MAT.sandstone,
    );
    пол.position.set(0, ГРОБНИЦА_ПЛИТА.подъём - ГРОБНИЦА_ПЛИТА.t / 2, zЗад + HALL_D / 2);
    пол.receiveShadow = true;
    g.add(пол);

    // ── Ограда двора ──
    for (const s of [-1, 1] as const) {
      const бок = new THREE.Mesh(
        new THREE.BoxGeometry(wallYard.t, wallYard.h, zДвор + wallYard.t),
        MAT.sandstoneDark,
      );
      бок.position.set(s * (YARD_W / 2 + wallYard.t / 2), wallYard.h / 2, zДвор / 2 - wallYard.t / 2);
      бок.castShadow = true;
      бок.receiveShadow = true;
      g.add(бок);
    }
    // Передняя стенка с проёмом.
    const проём = DOOR_W + 2.4;
    const полотно = (YARD_W + wallYard.t * 2 - проём) / 2;
    for (const s of [-1, 1] as const) {
      const w = new THREE.Mesh(
        new THREE.BoxGeometry(полотно, wallYard.h, wallYard.t),
        MAT.sandstoneDark,
      );
      w.position.set(s * (проём / 2 + полотно / 2), wallYard.h / 2, zДвор + wallYard.t / 2);
      w.castShadow = true;
      w.receiveShadow = true;
      g.add(w);
    }
    const зад = new THREE.Mesh(
      new THREE.BoxGeometry(YARD_W + wallYard.t * 2, wallYard.h, wallYard.t),
      MAT.sandstoneDark,
    );
    зад.position.set(0, wallYard.h / 2, zЗад - wallYard.t / 2);
    зад.castShadow = true;
    зад.receiveShadow = true;
    g.add(зад);

    // ── Корпус гробницы: три глухие стены и передняя ──
    for (const [hx, hz, hw, hd] of [
      [0, zЗад + WALL_T / 2, HALL_W, WALL_T],
      [-HALL_W / 2 + WALL_T / 2, zЗад + HALL_D / 2, WALL_T, HALL_D],
      [HALL_W / 2 - WALL_T / 2, zЗад + HALL_D / 2, WALL_T, HALL_D],
    ] as const) {
      const w = new THREE.Mesh(new THREE.BoxGeometry(hw, HALL_H, hd), MAT.sandstone);
      w.position.set(hx, HALL_H / 2, hz);
      w.castShadow = true;
      w.receiveShadow = true;
      g.add(w);
    }
    // Передняя стена с проёмом двери.
    const сегмент = (HALL_W - DOOR_W) / 2;
    for (const s of [-1, 1] as const) {
      const w = new THREE.Mesh(new THREE.BoxGeometry(сегмент, HALL_H, WALL_T), MAT.sandstone);
      w.position.set(s * (DOOR_W / 2 + сегмент / 2), HALL_H / 2, WALL_T / 2);
      w.castShadow = true;
      w.receiveShadow = true;
      g.add(w);
    }
    const перемычка = new THREE.Mesh(
      new THREE.BoxGeometry(DOOR_W, HALL_H - DOOR_H, WALL_T),
      MAT.sandstone,
    );
    перемычка.position.set(0, DOOR_H + (HALL_H - DOOR_H) / 2, WALL_T / 2);
    перемычка.castShadow = true;
    g.add(перемычка);

    // Купол/пирамидальная кровля.
    const крыша = new THREE.Mesh(
      new THREE.ConeGeometry(HALL_W / 2 + 1.0, 2.2, 4),
      MAT.sandstoneDark,
    );
    крыша.position.set(0, HALL_H + 1.1, zЗад + HALL_D / 2);
    крыша.rotation.y = Math.PI / 4;
    крыша.castShadow = true;
    g.add(крыша);

    // ── Дверь с решёткой ──
    const дверь = new THREE.Mesh(new THREE.BoxGeometry(DOOR_W, DOOR_H, 0.3), MAT.wood);
    дверь.position.set(0, DOOR_H / 2, WALL_T / 2 + 0.15);
    дверь.userData = {
      doorBuilding: 'tomb',
      doorAction: 'enter',
      doorName: t('buildings.tomb'),
    };
    g.add(дверь);
    const заглушка = new THREE.Mesh(
      new THREE.BoxGeometry(ГРОБНИЦА_ЗАГЛУШКА.w, ГРОБНИЦА_ЗАГЛУШКА.h, ГРОБНИЦА_ЗАГЛУШКА.t),
      MAT.dark,
    );
    заглушка.position.set(0, DOOR_H / 2, WALL_T / 2 - 0.05);
    g.add(заглушка);
    // Решётка в проёме: тонкие прутья, как в интерьере.
    for (let i = 0; i < 5; i++) {
      const bx = -DOOR_W / 2 + (DOOR_W / 4) * i;
      const прут = new THREE.Mesh(new THREE.BoxGeometry(0.08, DOOR_H, 0.08), MAT.dark);
      прут.position.set(bx, DOOR_H / 2, WALL_T / 2 + 0.1);
      g.add(прут);
    }

    // ── Лестница к двери ──
    // Ступени поднимаются от земли к уровню двери, как в интерьере — вниз.
    let ступеньY = 0;
    for (let i = 0; i < лестница.число; i++) {
      ступеньY -= лестница.подъём;
      const ст = new THREE.Mesh(
        new THREE.BoxGeometry(лестница.ширина, лестница.подъём + 0.15, лестница.шаг),
        MAT.stone,
      );
      ст.position.set(0, ступеньY + лестница.подъём / 2, WALL_T / 2 + лестница.шаг / 2 + i * лестница.шаг);
      ст.castShadow = true;
      ст.receiveShadow = true;
      g.add(ст);
    }

    // ── Тенистая площадь перед дверью: столб со светильником ──
    for (const s of [-1, 1] as const) {
      const столб = new THREE.Mesh(new THREE.BoxGeometry(0.4, 2.6, 0.4), MAT.stone);
      столб.position.set(s * (DOOR_W / 2 + 1.6), 1.3, WALL_T / 2 + 1.2);
      столб.castShadow = true;
      g.add(столб);
      const фонарь = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.6, 0.5), MAT.gold);
      фонарь.position.set(s * (DOOR_W / 2 + 1.6), 2.8, WALL_T / 2 + 1.2);
      g.add(фонарь);
    }

    // ── Коллайдеры ──
    // Передняя стена: цепочка с проёмом двери.
    for (let sx = -HALL_W / 2; sx <= HALL_W / 2; sx += 2) {
      if (Math.abs(sx) >= DOOR_W / 2 + 1.5) {
        addCollider(TOMB.x + sx, TOMB.z + WALL_T / 2, 1.1);
      }
    }
    // Задняя и боковые стены корпуса.
    for (let sx = -HALL_W / 2; sx <= HALL_W / 2; sx += 2) {
      addCollider(TOMB.x + sx, TOMB.z + zЗад + WALL_T / 2, 1.1);
    }
    for (let sz = zЗад + WALL_T; sz <= 0; sz += 2) {
      addCollider(TOMB.x - HALL_W / 2 - WALL_T / 2, TOMB.z + sz, 1.1);
      addCollider(TOMB.x + HALL_W / 2 + WALL_T / 2, TOMB.z + sz, 1.1);
    }
    // Ограда двора: передняя с проёмом, боковые глухие, задняя под корпусом.
    const проём2 = DOOR_W + 2.4;
    for (let tx = -YARD_W / 2; tx <= YARD_W / 2; tx += 2) {
      if (Math.abs(tx) >= проём2 / 2 + 0.6) {
        addCollider(TOMB.x + tx, TOMB.z + zДвор + wallYard.t / 2, 1.0);
      }
    }
    for (let tz = 0; tz <= zДвор; tz += 2) {
      addCollider(TOMB.x - YARD_W / 2 - wallYard.t / 2, TOMB.z + tz, 1.0);
      addCollider(TOMB.x + YARD_W / 2 + wallYard.t / 2, TOMB.z + tz, 1.0);
    }
    for (let tx = -YARD_W / 2; tx <= YARD_W / 2; tx += 2) {
      addCollider(TOMB.x + tx, TOMB.z + zЗад - wallYard.t / 2, 1.0);
    }
    // Столбы фонарей.
    for (const s of [-1, 1] as const) {
      addCollider(TOMB.x + s * (DOOR_W / 2 + 1.6), TOMB.z + WALL_T / 2 + 1.2, 0.7);
    }

    scene.add(g);
  }
  // ── Катакомбы Тебриза ─────────────────────────────────────────
//
// Подземный данж 32x32. Внутри: входной зал с аркой и лестницей вниз, казармы,
// тронный зал. Снаружи: входная арка с лестницей вниз, площадка вровень.
//
// ГДЕ: exit (-520, -336), дверь (-520, -340), выход на 4 м в +z.
{
  const { арка, лестница, двор, wallYard } = CATACOMBS_GEO;
  const zДвор = КАТАКОМБЫ_ДВОР_Z;

  const g = new THREE.Group();
  g.position.set(CATACOMBS.x, CATACOMBS.level, CATACOMBS.z);

  // Плита двора.
  const плита = new THREE.Mesh(new THREE.BoxGeometry(двор.w, 0.3, zДвор), MAT.sand);
  плита.position.set(0, 0.04 - 0.15, zДвор / 2);
  плита.receiveShadow = true;
  g.add(плита);

  // Входная арка: два столба и перемычка.
  for (const s of [-1, 1] as const) {
    const столб = new THREE.Mesh(new THREE.BoxGeometry(арка.t, арка.h, арка.t), MAT.stone);
    столб.position.set(s * (арка.w / 2 - арка.t / 2), арка.h / 2, арка.t / 2);
    столб.castShadow = true;
    g.add(столб);
  }
  const перемычка = new THREE.Mesh(new THREE.BoxGeometry(арка.w, арка.t, арка.t), MAT.sandstone);
  перемычка.position.set(0, арка.h + арка.t / 2, арка.t / 2);
  перемычка.castShadow = true;
  g.add(перемычка);

  // Дверной проём — темная заглушка.
  const дверь = new THREE.Mesh(new THREE.BoxGeometry(арка.w - арка.t * 2, арка.h, 0.3), MAT.dark);
  дверь.position.set(0, арка.h / 2, арка.t / 2);
  дверь.userData = { doorBuilding: 'catacombs', doorAction: 'enter', doorName: t('buildings.catacombs') };
  g.add(дверь);

  // Лестница вниз перед аркой.
  let ступеньY = 0;
  for (let i = 0; i < лестница.число; i++) {
    ступеньY -= лестница.подъём;
    const ст = new THREE.Mesh(new THREE.BoxGeometry(лестница.ширина, лестница.подъём + 0.15, лестница.шаг), MAT.stone);
    ст.position.set(0, ступеньY + лестница.подъём / 2, арка.t + лестница.шаг / 2 + i * лестница.шаг);
    ст.castShadow = true;
    g.add(ст);
  }

  // Низкая ограда двора по бокам.
  for (const s of [-1, 1] as const) {
    const бок = new THREE.Mesh(new THREE.BoxGeometry(wallYard.t, wallYard.h, zДвор + wallYard.t), MAT.sandstoneDark);
    бок.position.set(s * (двор.w / 2 + wallYard.t / 2), wallYard.h / 2, zДвор / 2 - wallYard.t / 2);
    бок.castShadow = true;
    g.add(бок);
  }

  // Коллайдеры: столбы арки, бока ограды. Передний проём lasciato открытым.
  for (const s of [-1, 1] as const) {
    addCollider(CATACOMBS.x + s * (арка.w / 2 - арка.t / 2), CATACOMBS.z + арка.t / 2, 1.1);
  }
  for (let tz = 0; tz <= zДвор; tz += 2) {
    addCollider(CATACOMBS.x - двор.w / 2 - wallYard.t / 2, CATACOMBS.z + tz, 1.0);
    addCollider(CATACOMBS.x + двор.w / 2 + wallYard.t / 2, CATACOMBS.z + tz, 1.0);
  }

  scene.add(g);
  // ── Дворцовый данж ───────────────────────────────────────────
//
// Подземный данж 32x32 под дворцом. Вход — арка с лестницей вниз.
// ГДЕ: exit (-160, 244), дверь (-160, 240), выход на 4 м в +z.
{
  const { арка, лестница, двор, wallYard } = PALACE_DUNGEON_GEO;
  const zДвор = ДВОРЦОВЫЙ_ДАНЖ_ДВОР_Z;

  const g = new THREE.Group();
  g.position.set(PALACE_DUNGEON.x, PALACE_DUNGEON.level, PALACE_DUNGEON.z);

  // Плита двора.
  const плита = new THREE.Mesh(new THREE.BoxGeometry(двор.w, 0.3, zДвор), MAT.sand);
  плита.position.set(0, 0.04 - 0.15, zДвор / 2);
  плита.receiveShadow = true;
  g.add(плита);

  // Входная арка: два столба и перемычка.
  for (const s of [-1, 1] as const) {
    const столб = new THREE.Mesh(new THREE.BoxGeometry(арка.t, арка.h, арка.t), MAT.stone);
    столб.position.set(s * (арка.w / 2 - арка.t / 2), арка.h / 2, арка.t / 2);
    столб.castShadow = true;
    g.add(столб);
  }
  const перемычка = new THREE.Mesh(new THREE.BoxGeometry(арка.w, арка.t, арка.t), MAT.sandstone);
  перемычка.position.set(0, арка.h + арка.t / 2, арка.t / 2);
  перемычка.castShadow = true;
  g.add(перемычка);

  // Дверной проём — темная заглушка.
  const дверь = new THREE.Mesh(new THREE.BoxGeometry(арка.w - арка.t * 2, арка.h, 0.3), MAT.dark);
  дверь.position.set(0, арка.h / 2, арка.t / 2);
  дверь.userData = { doorBuilding: 'palace_dungeon', doorAction: 'enter', doorName: t('buildings.palace_dungeon') };
  g.add(дверь);

  // Лестница вниз перед аркой.
  let ступеньY = 0;
  for (let i = 0; i < лестница.число; i++) {
    ступеньY -= лестница.подъём;
    const ст = new THREE.Mesh(new THREE.BoxGeometry(лестница.ширина, лестница.подъём + 0.15, лестница.шаг), MAT.stone);
    ст.position.set(0, ступеньY + лестница.подъём / 2, арка.t + лестница.шаг / 2 + i * лестница.шаг);
    ст.castShadow = true;
    g.add(ст);
  }

  // Низкая ограда двора по бокам.
  for (const s of [-1, 1] as const) {
    const бок = new THREE.Mesh(new THREE.BoxGeometry(wallYard.t, wallYard.h, zДвор + wallYard.t), MAT.sandstoneDark);
    бок.position.set(s * (двор.w / 2 + wallYard.t / 2), wallYard.h / 2, zДвор / 2 - wallYard.t / 2);
    бок.castShadow = true;
    g.add(бок);
  }

  // Коллайдеры: столбы арки, бока ограды.
  for (const s of [-1, 1] as const) {
    addCollider(PALACE_DUNGEON.x + s * (арка.w / 2 - арка.t / 2), PALACE_DUNGEON.z + арка.t / 2, 1.1);
  }
  for (let tz = 0; tz <= zДвор; tz += 2) {
    addCollider(PALACE_DUNGEON.x - двор.w / 2 - wallYard.t / 2, PALACE_DUNGEON.z + tz, 1.0);
    addCollider(PALACE_DUNGEON.x + двор.w / 2 + wallYard.t / 2, PALACE_DUNGEON.z + tz, 1.0);
  }

  scene.add(g);
  // ── Хорасанские пещеры ─────────────────────────────────────────
//
// Подземный данж 32x32. Вход — арка в скале с лестницей вниз.
// ГДЕ: exit (780, -616), дверь (780, -620), выход на 4 м в +z.
{
  const { арка, лестница, двор, wallYard } = KHORASAN_CAVES_GEO;
  const zДвор = ХОРАСАН_ДВОР_Z;

  const g = new THREE.Group();
  g.position.set(KHORASAN_CAVES.x, KHORASAN_CAVES.level, KHORASAN_CAVES.z);

  // Плита двора.
  const плита = new THREE.Mesh(new THREE.BoxGeometry(двор.w, 0.3, zДвор), MAT.sand);
  плита.position.set(0, 0.04 - 0.15, zДвор / 2);
  плита.receiveShadow = true;
  g.add(плита);

  // Входная арка: два столба и перемычка.
  for (const s of [-1, 1] as const) {
    const столб = new THREE.Mesh(new THREE.BoxGeometry(арка.t, арка.h, арка.t), MAT.stone);
    столб.position.set(s * (арка.w / 2 - арка.t / 2), арка.h / 2, арка.t / 2);
    столб.castShadow = true;
    g.add(столб);
  }
  const перемычка = new THREE.Mesh(new THREE.BoxGeometry(арка.w, арка.t, арка.t), MAT.sandstone);
  перемычка.position.set(0, арка.h + арка.t / 2, арка.t / 2);
  перемычка.castShadow = true;
  g.add(перемычка);

  // Дверной проём — темная заглушка.
  const дверь = new THREE.Mesh(new THREE.BoxGeometry(арка.w - арка.t * 2, арка.h, 0.3), MAT.dark);
  дверь.position.set(0, арка.h / 2, арка.t / 2);
  дверь.userData = { doorBuilding: 'khorasan_caves', doorAction: 'enter', doorName: t('buildings.khorasan_caves') };
  g.add(дверь);

  // Лестница вниз перед аркой.
  let ступеньY = 0;
  for (let i = 0; i < лестница.число; i++) {
    ступеньY -= лестница.подъём;
    const ст = new THREE.Mesh(new THREE.BoxGeometry(лестница.ширина, лестница.подъём + 0.15, лестница.шаг), MAT.stone);
    ст.position.set(0, ступеньY + лестница.подъём / 2, арка.t + лестница.шаг / 2 + i * лестница.шаг);
    ст.castShadow = true;
    g.add(ст);
  }

  // Низкая ограда двора по бокам.
  for (const s of [-1, 1] as const) {
    const бок = new THREE.Mesh(new THREE.BoxGeometry(wallYard.t, wallYard.h, zДвор + wallYard.t), MAT.sandstoneDark);
    бок.position.set(s * (двор.w / 2 + wallYard.t / 2), wallYard.h / 2, zДвор / 2 - wallYard.t / 2);
    бок.castShadow = true;
    g.add(бок);
  }

  // Коллайдеры: столбы арки, бока ограды.
  for (const s of [-1, 1] as const) {
    addCollider(KHORASAN_CAVES.x + s * (арка.w / 2 - арка.t / 2), KHORASAN_CAVES.z + арка.t / 2, 1.1);
  }
  for (let tz = 0; tz <= zДвор; tz += 2) {
    addCollider(KHORASAN_CAVES.x - двор.w / 2 - wallYard.t / 2, KHORASAN_CAVES.z + tz, 1.0);
    addCollider(KHORASAN_CAVES.x + двор.w / 2 + wallYard.t / 2, KHORASAN_CAVES.z + tz, 1.0);
  }

  scene.add(g);
  // ── Кавказский форпост ─────────────────────────────────────────
//
// Крепость: ворота с решёткой, сторожевые посты с факелами, стена с зубцами.
// ГДЕ: exit (-880, 524), дверь (-880, 520), выход на 4 м в +z.
{
  const { ворота, решётка, стена, двор } = CAUCASUS_FORT_GEO;
  const zДвор = КАВКАЗ_ДВОР_Z;

  const g = new THREE.Group();
  g.position.set(CAUCASUS_FORT.x, CAUCASUS_FORT.level, CAUCASUS_FORT.z);

  // Плита двора.
  const плита = new THREE.Mesh(new THREE.BoxGeometry(двор.w, 0.3, zДвор), MAT.sand);
  плита.position.set(0, 0.04 - 0.15, zДвор / 2);
  плита.receiveShadow = true;
  g.add(плита);

  // Ворота: два столба и перемычка.
  for (const s of [-1, 1] as const) {
    const столб = new THREE.Mesh(new THREE.BoxGeometry(ворота.t, ворота.h, ворота.t), MAT.stone);
    столб.position.set(s * (ворота.w / 2 - ворота.t / 2), ворота.h / 2, ворота.t / 2);
    столб.castShadow = true;
    g.add(столб);
  }
  const перемычка = new THREE.Mesh(new THREE.BoxGeometry(ворота.w, ворота.t, ворота.t), MAT.sandstone);
  перемычка.position.set(0, ворота.h + ворота.t / 2, ворота.t / 2);
  перемычка.castShadow = true;
  g.add(перемычка);

  // Дверной проём — тёмная заглушка.
  const дверь = new THREE.Mesh(new THREE.BoxGeometry(решётка.w, решётка.h, 0.3), MAT.dark);
  дверь.position.set(0, решётка.h / 2, ворота.t / 2);
  дверь.userData = { doorBuilding: 'caucasus_fort', doorAction: 'enter', doorName: t('buildings.caucasus_fort') };
  g.add(дверь);

  // Решётка в проёме: тонкие прутья.
  for (let i = 0; i < 5; i++) {
    const bx = -решётка.w / 2 + (решётка.w / 4) * i;
    const прут = new THREE.Mesh(new THREE.BoxGeometry(0.12, решётка.h, 0.12), MAT.dark);
    прут.position.set(bx, решётка.h / 2, ворота.t / 2 + 0.1);
    g.add(прут);
  }

  // Сторожевые посты с факелами по краям ворот.
  for (const s of [-1, 1] as const) {
    const px = s * (ворота.w / 2 + 2.0);
    const столб = new THREE.Mesh(new THREE.BoxGeometry(0.4, 2.4, 0.4), MAT.stone);
    столб.position.set(px, 1.2, ворота.t / 2 + 1.0);
    столб.castShadow = true;
    g.add(столб);
    const факел = new THREE.Mesh(new THREE.CylinderGeometry(0.25, 0.2, 0.4, 8), MAT.gold);
    факел.position.set(px, 2.6, ворота.t / 2 + 1.0);
    g.add(факел);
  }

  // Стена с зубцами по бокам двора.
  for (const s of [-1, 1] as const) {
    const бок = new THREE.Mesh(new THREE.BoxGeometry(стена.t, стена.h, zДвор + стена.t), MAT.sandstoneDark);
    бок.position.set(s * (двор.w / 2 + стена.t / 2), стена.h / 2, zДвор / 2 - стена.t / 2);
    бок.castShadow = true;
    g.add(бок);
    // Зубцы.
    for (let i = 0; i < 6; i++) {
      const зубец = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.5, 0.6), MAT.sandstone);
      зубец.position.set(s * (двор.w / 2 + стена.t / 2), стена.h + 0.25, 1 + i * 2.0);
      g.add(зубец);
    }
  }

  // Коллайдеры: столбы ворот, стены, сторожевые посты.
  for (const s of [-1, 1] as const) {
    addCollider(CAUCASUS_FORT.x + s * (ворота.w / 2 - ворота.t / 2), CAUCASUS_FORT.z + ворота.t / 2, 1.1);
    addCollider(CAUCASUS_FORT.x + s * (двор.w / 2 + стена.t / 2), CAUCASUS_FORT.z + zДвор / 2, 1.0);
    addCollider(CAUCASUS_FORT.x + s * (ворота.w / 2 + 2.0), CAUCASUS_FORT.z + ворота.t / 2 + 1.0, 0.7);
  }

  scene.add(g);
}
}
}
}
}


// ── Акведук деревни ──────────────────────────────────────────────────
//
// Разрушенная аркада из пяти сегментов к востоку от лесной деревни: строка
// списка владельца требует у деревни акведуки. Сегмент — готовая модель
// (Tripo, децимация до 66к треугольников, Draco, JPEG), цепочка собирается
// кодом: последний сегмент осел и накренился — руина, а не новостройка.
//
// Площадка замерена: сухо, размах 0.2–0.3, вне домов (кольцо r=10) и полей.
// Загрузка асинхронная: нет файла — деревня стоит без аркады, игра не падает.
export const AQUEDUCT = { x: VILLAGE.x + 20, z: VILLAGE.z - 2, count: 5, step: 1.0 };
const AQUEDUCT_MODEL = 'decor/aqueduct-seg.glb';

/**
 * Готовые модели декора: шатёр, кузница, аркада. Один загрузчик на всех,
 * а не копия на модель: копии расходились бы молча (путь, Draco, fallback).
 */
const decorCache = new Map<string, Promise<THREE.Group | null>>();

export function loadDecorModel(path: string): Promise<THREE.Group | null> {
  const готовый = decorCache.get(path);
  if (готовый) return готовый;
  const задача = new Promise<THREE.Group | null>((готово) => {
    try {
      const draco = new DRACOLoader();
      draco.setDecoderPath('/game/draco/');
      const l = new GLTFLoader();
      l.setDRACOLoader(draco);
      l.load(
        `/game/models/${path}`,
        (gltf) => готово((gltf.scene as THREE.Group) ?? null),
        undefined,
        () => готово(null),
      );
    } catch {
      готово(null);
    }
  });
  decorCache.set(path, задача);
  return задача;
}

function placeDecor(
  scene: THREE.Scene,
  path: string,
  px: number,
  pz: number,
  lift: number,
  ry: number,
  colliderR: number,
  scale = 1,
): void {
  // Коллайдер ставится сразу, модель доезжает: иначе в окно загрузки сквозь
  // стену проходят, а потом стена «появляется» вокруг игрока.
  addCollider(px, pz, colliderR);
  void loadDecorModel(path).then((модель) => {
    if (!модель) return;
    const вещь = модель.clone();
    вещь.position.set(px, groundHeight(px, pz) + lift, pz);
    вещь.rotation.y = ry;
    вещь.scale.setScalar(scale);
    вещь.traverse((o) => {
      const m = o as THREE.Mesh;
      if (!m.isMesh) return;
      m.castShadow = true;
      m.receiveShadow = true;
    });
    scene.add(вещь);
  });
}

export function buildAqueduct(scene: THREE.Scene): void {
  for (let i = 0; i < AQUEDUCT.count; i++) {
    const px = AQUEDUCT.x + (i - (AQUEDUCT.count - 1) / 2) * AQUEDUCT.step;
    const pz = AQUEDUCT.z;
    // Аркада — стена: пролезть между сегментами нельзя, это завал, а не ворота.
    addCollider(px, pz, 0.9);
    void loadDecorModel(AQUEDUCT_MODEL).then((модель) => {
      if (!модель) return;
      const seg = модель.clone();
      seg.position.set(px, groundHeight(px, pz), pz);
      seg.rotation.y = 0.08 * (i % 2 === 0 ? 1 : -1);
      if (i === AQUEDUCT.count - 1) {
        // Последний сегмент осел: руина читается осадкой, а не ровным рядом.
        seg.rotation.z = 0.1;
        seg.position.y -= 0.12;
      }
      seg.traverse((o) => {
        const m = o as THREE.Mesh;
        if (!m.isMesh) return;
        m.castShadow = true;
        m.receiveShadow = true;
      });
      scene.add(seg);
    });
  }
}

// ── Шатёр базара и кузница деревни ─────────────────────────────────
// Третий и четвёртый пакеты из Assets: торговый шатёр в базарный квартал
// столицы и кузница в деревню (у деревни кузницы не было — workshop живёт
// в столице). Подъём над землёй — из габаритов моделей: обе отцентрены,
// низ на −0.91/−0.95, ставить на groundHeight значило бы вкопать.
export const TRADE_TENT = { x: CITY.x + 96, z: CITY.z, lift: 0.91, ry: -0.2 };
export const VILLAGE_FORGE = { x: VILLAGE.x, z: VILLAGE.z - 14, lift: 0.95, ry: 0.15 };

export function buildTradeTent(scene: THREE.Scene): void {
  placeDecor(scene, 'decor/trade-tent.glb', TRADE_TENT.x, TRADE_TENT.z, TRADE_TENT.lift, TRADE_TENT.ry, 1.2);
}

export function buildVillageForge(scene: THREE.Scene): void {
  placeDecor(scene, 'decor/village-forge.glb', VILLAGE_FORGE.x, VILLAGE_FORGE.z, VILLAGE_FORGE.lift, VILLAGE_FORGE.ry, 1.0);
}

// ── Бастионы ворот горной крепости ─────────────────────────────────
//
// Седьмой пакет из Assets: два бастиона по бокам ворот крепости (дверь
// fortress в (-320, -677)). Механика дверей не тронута: бастионы стоят
// сбоку проёма, проход 4 м между коллайдерами. База модели на нуле —
// подъём не нужен. Текстура проверена рендером с ambient (без него EEVEE
// даёт чёрный кадр и врёт про материал).
export const FORT_BASTIONS = { z: -677, dx: 10, r: 8 } as const;

export function buildFortBastions(scene: THREE.Scene): void {
  for (const сторона of [-1, 1]) {
    const px = -320 + сторона * FORT_BASTIONS.dx;
    const pz = FORT_BASTIONS.z;
    addCollider(px, pz, FORT_BASTIONS.r);
    void loadDecorModel('decor/bastion.glb').then((модель) => {
      if (!модель) return;
      const бастион = модель.clone();
      бастион.position.set(px, groundHeight(px, pz), pz);
      бастион.traverse((o) => {
        const m = o as THREE.Mesh;
        if (!m.isMesh) return;
        m.castShadow = true;
        m.receiveShadow = true;
      });
      scene.add(бастион);
    });
  }
}
// ── Руины: капелла у Месопотамии и двор у святилища ─────────────
//
// Восьмой и девятый пакеты из Assets. Капелла — разрушенная часовня в
// пустыне к востоку от города (свой регион, сухо). Двор — заросший дворик
// у зороастрийского святилища. Обе метровые, база на нуле — подъём не нужен,
// масштаб 8 (иначе кукольные домики в метр). Коллайдеры по габариту.
export const RUIN_CHAPEL = { x: -1105, z: -355, scale: 8 };
export const RUIN_COURT = { x: 1225, z: 1215, scale: 8 };

export function buildRuinChapel(scene: THREE.Scene): void {
  placeDecor(scene, 'decor/ruin-chapel.glb', RUIN_CHAPEL.x, RUIN_CHAPEL.z, 0, 0, 4, RUIN_CHAPEL.scale);
}

export function buildRuinCourt(scene: THREE.Scene): void {
  placeDecor(scene, 'decor/ruin-court.glb', RUIN_COURT.x, RUIN_COURT.z, 0, 0, 4, RUIN_COURT.scale);
}
// ── Руины церкви на Кавказе ────────────────────────────
//
// Двадцать третий пакет из свежей пачки Assets (pieve_san_martinos_ruins).
// Конвейер: glTF из архива → Blender (Draco, WEBP 1024) → public/models/decor
// → сцена с коллайдерами по замеру проекции (footprint.py, порог 3 м).
//
// ПЛОЩАДКА. (-1010, 646), зона caucasus_peaks: суша на всём пятне 24x40,
// размах рельефа 0.88 м, город Кавказ в 100 м от края пятна. Церковь на
// Кавказе читается: регион с христианским прошлым.
//
// ПОДЪЯМ. Пол нефа мерен отдельно: 0.93…1.32 от низа модели, медиана 1.07.
// Низ модели (−1.505) — кромка её собственного грунта. Кладём пол на землю
// (lift −0.95): грунт уходит на 2.46 м вглубь и прячется под террейном,
// а пол остаётся на нуле. Подъём по низу (1.505) поднял бы пол на 3.5 м.
//
// КОЛЛАИДЕРЫ. По проекции: внешние стены x −7.9/+8.1, торцы z −13/+15.5,
// аркады x −3.9/+3.1. Южный торец разорван проёмом x −2.4…3.6 (замер при
// пороге 1.5 м) — вход. Приделы (4 м между стеной и аркадой) закрыты:
// с игроком R = 1 там не разойтись. Неф (7 м) проходим: просвет 2.6 м.
export const CHURCH_RUIN = { x: -1010, z: 646, lift: -0.95 };

export function buildChurchRuin(scene: THREE.Scene): void {
  const { x, z, lift } = CHURCH_RUIN;
  const ЛЕВАЯ = -7.9;
  const ПРАВАЯ = 8.1;
  const ЮГ = -13;
  const СЕВЕР = 15.5;
  // Шаг 3.5 при радиусе 1.2: щель между кругами 1.1 м, игрок (R = 1) не пролезет.
  for (let lz = ЮГ; lz <= СЕВЕР; lz += 3.5) {
    addCollider(x + ЛЕВАЯ, z + lz, 1.2);
    addCollider(x + ПРАВАЯ, z + lz, 1.2);
  }
  // Северный торец закрыт целиком: проём только в южном.
  for (let lx = ЛЕВАЯ; lx <= ПРАВАЯ; lx += 3.5) addCollider(x + lx, z + СЕВЕР, 1.2);
  // Южный торец: два круга по краям проёма (окно −2.4…3.4 внутри проёма −2.4…3.6).
  addCollider(x - 4.6, z + ЮГ, 1.2);
  addCollider(x + 5.6, z + ЮГ, 1.2);
  // Аркады: приделы закрыты, неф проходим.
  for (let lz = -8; lz <= 15; lz += 3.5) {
    addCollider(x - 3.9, z + lz, 1.2);
    addCollider(x + 3.1, z + lz, 1.2);
  }

  void loadDecorModel('decor/church-ruin.glb').then((модель) => {
    if (!модель) return;
    const вещь = модель.clone();
    вещь.position.set(x, groundHeight(x, z) + lift, z);
    вещь.traverse((o) => {
      const m = o as THREE.Mesh;
      if (!m.isMesh) return;
      m.castShadow = true;
      m.receiveShadow = true;
    });
    scene.add(вещь);
  });
}
// ── Каменная арка у деревни ─────────────────────────────────────
//
// Двадцать четвёртый пакет из Assets (medieval-village-stone-archway):
// руина ворот со сводом, к востоку от лесной деревни. Площадка замерена
// (site-survey): (-416, -456), пятно 12x28, размах рельефа 0.11 м, зона
// mesopotamia_ruins, регион mesopotamia; деревня в 63 м от края пятна,
// руина моста в 64 м, катакомбы в 96 м. Дороги мимо не идут.
//
// ПОДЪЁМ. Основание — скан по рельефу, плоского среза нет: карта дна
// по ячейкам 3 м даёт медиану -1.62 (min -5.01, max +3.34). Медиана
// на землю (lift 1.62): стена уходит в грунт на 0…3.4 м, как и положено
// руине, а свод юго-востока с дном +0.9…+2.0 встаёт в 2.5…3.6 м над
// землёй — под ним проходит игрок. Нулевой подъём поднял бы свод до
// 0.9 м и упёрся бы в голову.
//
// КОЛЛАИДЕРЫ. Кладка мерена сечениями на высотах 0.3 и 1.7 м
// (collider-runs.py): западная стена идёт вдоль всей длины зигзагом
// x -5.0…-1.2, восточная гряда северного блока x 1.0…4.8 при z -10…0,
// ниже x 0.3…2.5. Радиус = полутолщина кладки + метр на игрока, шаг 3
// меньше захвата круга — сплошь. Расселина северного блока 1.5…2.2 м:
// игроку R = 1 туда не влезть, глыбу закрываем целиком. Южный двор
// (восточнее x -1.2, южнее z 2) и подсводье остаются проходимыми.
export const VILLAGE_ARCHWAY = { x: -416, z: -456, lift: 1.62 };

export function buildVillageArchway(scene: THREE.Scene): void {
  const { x, z, lift } = VILLAGE_ARCHWAY;
  // Северо-западный участок стены: кладка x -3.5…-1.2.
  for (let lz = -11; lz <= -5; lz += 3) addCollider(x - 2.36, z + lz, 2);
  // Западная стена на всю длину: кладка x -5.0…-3.5.
  for (let lz = -5; lz <= 10; lz += 3) addCollider(x - 4.23, z + lz, 1.4);
  // Южный хвост стены: кладка x -4.2…-2.0.
  for (let lz = 10.5; lz <= 16.5; lz += 3) addCollider(x - 3.1, z + lz, 1.7);
  // Восточная гряда северного блока: x 1.0…4.8, ниже — x 0.3…2.5.
  for (let lz = -10; lz <= -7; lz += 3) addCollider(x + 2.9, z + lz, 2.9);
  for (let lz = -4; lz <= -1; lz += 3) addCollider(x + 1.4, z + lz, 2.2);

  void loadDecorModel('decor/village-archway.glb').then((модель) => {
    if (!модель) return;
    const вещь = модель.clone();
    вещь.position.set(x, groundHeight(x, z) + lift, z);
    вещь.traverse((o) => {
      const m = o as THREE.Mesh;
      if (!m.isMesh) return;
      m.castShadow = true;
      m.receiveShadow = true;
    });
    scene.add(вещь);
  });
}

// ── Дверной проём у руин церкви ─────────────────────────────────
//
// Двадцать пятый пакет из Assets (north-doorway-st-martins-holt): стена
// церкви с проёмом, к востоку от её же руин. Площадка замерена
// (site-survey): (-950, 682), пятно 12x8, размах рельефа 0.21 м, зона
// caucasus_peaks, регион caucasus; руины церкви в 46 м от края пятна,
// таможня в 82 м, город Кавказ в 150 м. Дороги рядом нет.
//
// ПОДЪЁМ. У модели есть единственный плоский срез — низ проёма, порог
// на -6.493 (срез кладки, а не медиана дна: медиана тут 3.83 и дала бы
// подъём в минус, то есть задницу). Кладём порог на землю (lift 6.49):
// стена стоит 11.3 м, её низ уходит на 3 мм вглубь, а крошечная плита
// сверху (3.7…4.8 от низа) висит в 10.2…11.3 м над землёй.
//
// КОЛЛАИДЕРЫ. Сечения на 0.3 и 1.7 м (collider-runs.py): стена занимает
// z -0.03…1.47 на всём размахе x -5.4…5.8, включая завал в проёме —
// проём с высоты игрока закрыт, сквозь него не пройти. Одна линия по
// оси стены z = 0.35 с радиусом 1.5 (полутолщина 0.75 + метр игрока,
// плюс полметра на осцилляцию кругов) закрывает и кладку, и завал.
// Севернее — полоса под плитой, южнее — открытый воздух: оба проходимы.
export const CHURCH_DOORWAY = { x: -950, z: 682, lift: 6.49 };

export function buildChurchDoorway(scene: THREE.Scene): void {
  const { x, z, lift } = CHURCH_DOORWAY;
  // Ось стены (кладка z -0.03…1.47), шаг 1.9 — меньше захвата круга.
  for (let i = -56; i <= 58; i += 19) addCollider(x + i / 10, z + 0.35, 1.5);

  void loadDecorModel('decor/church-doorway.glb').then((модель) => {
    if (!модель) return;
    const вещь = модель.clone();
    вещь.position.set(x, groundHeight(x, z) + lift, z);
    вещь.traverse((o) => {
      const m = o as THREE.Mesh;
      if (!m.isMesh) return;
      m.castShadow = true;
      m.receiveShadow = true;
    });
    scene.add(вещь);
  });
}

// ── Купольная башня у мечети ─────────────────────────────────────
//
// Двадцать шестой пакет из Assets: onion-dome-towers-asset-pack. В архиве
// шесть башень рядком (плюс разобранная на части седьмая и дубль
// OnionDomeTower-02-.001 поверх -01), в игру идёт одна — OnionDomeTower-03.
// Выбрана по рендеру силуэтов: купол на широком барабане, столбчатый ствол,
// дно закрыто (6 граней), 25.5 м — в рост сторожевой башни. 1442 грани,
// Draco, WebP 1024, 1.45 МБ: пачку целиком (10 мешей, 71 м) не грузим.
//
// Площадка (site-survey): (60, -480), в 60 м к востоку от мечети, пятно
// 9x10.4, суша, h = 3.50 по всему следу (размах 0.00 — плато), зона
// mesopotamia_ruins, регион mesopotamia. Город в 391 м от края, деревня
// в 533 м, ближайшая дорога в 429 м — ориентир стоит один.
//
// ПОДЪЁМ. Происхождение снято на центр основания, база модели на нуле
// (min y = 0.00), поэтому подъём — это оседание. Кладём 10 см вглубь:
// плита основания не воюет с землёй, а на плато с размахом 0.00 ничего
// не провисает и не всплывает.
//
// КОЛЛАИДЕР. След основания крестом 7.5x7.5 (сечения на 0.05, 0.3 и 1.7 м):
// два крыла и ядро, между ними щели 0.75-1.5 м — игроку в 2 м туда не
// влезть, а в середину не пролезть вовсе: все входы уже диаметра игрока.
// Дальний угол кладки в 5.39 от центра плюс метр игрока — один круг
// r = 4.6, как у сторожевой башни, только шире за счёт креста. Лишнее
// закрыто не дальше 1.45 м сверх линии в метре (у арки 1.4).
export const ONION_DOME_TOWER = { x: 60, z: -480, lift: -0.1 };

export function buildOnionDomeTower(scene: THREE.Scene): void {
  const { x, z, lift } = ONION_DOME_TOWER;
  // Один круг на весь след: щели в основании непроходимы сами по себе.
  addCollider(x, z, 4.6);

  void loadDecorModel('decor/onion-dome-tower.glb').then((модель) => {
    if (!модель) return;
    const башня = модель.clone();
    башня.position.set(x, groundHeight(x, z) + lift, z);
    башня.traverse((o) => {
      const m = o as THREE.Mesh;
      if (!m.isMesh) return;
      m.castShadow = true;
      m.receiveShadow = true;
    });
    scene.add(башня);
  });
}

// ── Гибельный эшафот у стен Исфахана ─────────────────────────────
//
// Пятый пакет из свежей пачки Assets (medieval-gallows.glb): помост на
// столбах, лестница на площадку и рама с петлёй. 5.71x7.72 по земле и
// 5.17 в высоту, пять мешей, Draco, 464952 байт. Текстур нет — два цвета
// материалов (Wood 0.066/0.009/0 и Material.001 0.191/0.024/0.006),
// рендер с ambient проверен: тёмно-красное дерево читается, силуэт не
// сливается в чёрное.
//
// ПЛОЩАДКА. (-67, -89), выбрана владельцем из трёх замеренных:
// 35.1 м за городской стеной по краю пятна (r = 116), 35.2 м от края
// грунтовой дороги на порт, 30 м до руины ворот на той же дороге,
// 190 м от берега озера; суша, зона tabriz_south. Рельеф под пятном
// мерен сеткой 0.4 м: 1.001…1.125 при 1.049 в точке — перепад 0.12 м.
//
// РАЗВОРОТ. ry = -1.558 считан, а не выбран на глаз. Лестница и рама
// модели идут ВДОЛЬ одной оси (Z), поэтому развернуть лестницу точно на
// дорогу нельзя: петля (z = 0) и ближний столб (z = 2.32) встали бы на
// одной прямой — лобовой вид даёт по 4 см петли по бокам столба. ry =
// -1.558 ставит оси под 54.6 градуса к направлению на дорогу — петля
// отходит от столба на 1.89 м и видна, а лестница смотрит на дорогу под
// тем же углом, то есть с дороги к ней подходят.
//
// ПОДЪЁМ. Низ модели -0.048; при lift -0.01 низ встаёт на 0.991, на
// сантиметр ниже самого низкого грунта под пятном: ни одного просвета,
// а на высоком углу рама уходит в землю на 0.13 м.
//
// КОЛЛАИДЕР. Помост держится на столбах: между ножек проход прямо под
// настил, а сами ножки тонкие. Поэтому закрыт весь контур (доска
// 5.71x5.73 плюс лестница 1.55x2.0), а не одни ножки — по контуру игрок
// встаёт на месте, а не лезет под помост. Круги r = 1.2 через 2.5 м по
// локальному контуру, повёрнутому на ry: тело игрока (R = 1) даже между
// кругами не доходит до кромки — остаётся 0.81 м. Лестница в контуре
// целиком: по ней подниматься всё равно некуда.
export const GALLOWS = { x: -67, z: -89, lift: -0.01, ry: -1.558 };

// ── Телега, частокол, баррикада, мельница ───────────────────────────
// Площадки выбраны владельцем из замеренных: рынок внутри стен, compound
// эшафота, обочина дороги на порт, пустыня у караван-сарая. Углы не на
// глаз: телега оглоблями (+Z) вдоль дороги к городу, стена гладью (−Z)
// к эшафоту и подпорками (+Z) наружу, баррикада длинной осью (Z) вдоль
// дороги на порт, мельница дверью (+Z) к караван-сараю. Подъёмы — из
// минимума грунта под повёрнутым пятном, а не из высоты в точке.
export const MARKET_CART = { x: 124, z: 35, lift: -0.006, ry: -1.63229, scale: 1 };
export const GALLOWS_PALISADE = { x: -51, z: -89, lift: -0.05, ry: 1.5708, scale: 0.06 };
export const PORT_ROAD_BARRICADE = { x: -118, z: -85, lift: 0.31, ry: -2.16766, scale: 0.1 };
export const CARAVANSERAI_WINDMILL = { x: 581, z: 40, lift: -0.16, ry: -1.37593, scale: 1 };

// ── Плуг у мельницы ────────────────────────────────────────────
// Площадка выбрана владельцем: 12 м южнее мельницы, 46 м от караван-сарая.
// Рельеф под пятном 0.4 м: ровный 0.01. Крюк (+Z) смотрит от мельницы в поле,
// ry = 0 считан, а не выбран. Низ модели -0.254 (лемех зарывается сам);
// lift 0.237 ставит лемех на сантиметр ниже нижнего грунта.
export const MILL_PLOUGH = { x: 581, z: 52, lift: 0.237, ry: 0, scale: 1 };

// ── Точило у кузницы ─────────────────────────────────────────
// Площадка выбрана владельцем: 7 м восточнее кузницы, 16 м от центра деревни
// (вне кольца домов), дуб в 3 м. Рельеф под пятном ровный 0.01. Круг (-Z)
// смотрит на кузницу, ry = π/2 считан. Низ модели -0.003; lift -0.01 ставит
// станину на сантиметр ниже нижнего грунта.
export const VILLAGE_GRINDSTONE = { x: -488, z: -429, lift: -0.01, ry: 1.5708, scale: 1 };

export function buildGallows(scene: THREE.Scene): void {
  const { x, z, lift, ry } = GALLOWS;
  const c = Math.cos(ry);
  const s = Math.sin(ry);
  // Контур пятна в локальных координатах модели: доска и лестница.
  // Каждая точка проходит то же вращение, что и сама модель.
  const контур: [number, number][] = [
    [-5.44, -2.88], [0.27, -2.88], [0.27, 2.85],
    [-3.27, 2.85], [-3.27, 4.85], [-4.82, 4.85], [-4.82, 2.85], [-5.44, 2.85],
  ];
  for (let i = 0; i < контур.length; i++) {
    const [ax, az] = контур[i];
    const [bx, bz] = контур[(i + 1) % контур.length];
    const длина = Math.hypot(bx - ax, bz - az);
    const шагов = Math.max(1, Math.ceil(длина / 2.5));
    for (let k = 0; k < шагов; k++) {
      const доля = k / шагов;
      const lx = ax + (bx - ax) * доля;
      const lz = az + (bz - az) * доля;
      addCollider(x + lx * c + lz * s, z - lx * s + lz * c, 1.2);
    }
  }

  void loadDecorModel('decor/medieval-gallows.glb').then((модель) => {
    if (!модель) return;
    const эшафот = модель.clone();
    эшафот.position.set(x, groundHeight(x, z) + lift, z);
    эшафот.rotation.y = ry;
    эшафот.traverse((o) => {
      const m = o as THREE.Mesh;
      if (!m.isMesh) return;
      m.castShadow = true;
      m.receiveShadow = true;
    });
    scene.add(эшафот);
  });
}

// Модели со смещённым началом: x/z константы — центр габарита, а не начало
// модели. Сдвиг (cx, cz) задан в единицах модели до масштаба, коллайдеры —
// в метрах мира относительно центра. Поворот тот же, что у самой модели.
function placeCenteredDecor(
  scene: THREE.Scene,
  path: string,
  px: number,
  pz: number,
  lift: number,
  ry: number,
  scale: number,
  cx: number,
  cz: number,
  colliders: { x: number; z: number; r: number }[],
): void {
  const c = Math.cos(ry);
  const s = Math.sin(ry);
  for (const k of colliders) {
    addCollider(px + k.x * c + k.z * s, pz - k.x * s + k.z * c, k.r);
  }
  void loadDecorModel(path).then((модель) => {
    if (!модель) return;
    const вещь = модель.clone();
    вещь.position.set(
      px - (cx * c + cz * s) * scale,
      groundHeight(px, pz) + lift,
      pz - (-cx * s + cz * c) * scale,
    );
    вещь.rotation.y = ry;
    вещь.scale.setScalar(scale);
    вещь.traverse((o) => {
      const m = o as THREE.Mesh;
      if (!m.isMesh) return;
      m.castShadow = true;
      m.receiveShadow = true;
    });
    scene.add(вещь);
  });
}

// Телега с бочкой на рынке: пятно ровно 0.847…0.847, низ −0.004, lift −0.006
// ставит колёса на сантиметр ниже грунта. Два круга закрывают кузов и оглобли.
